  function calculateSuggestedFee(planKey, billingPeriod) {
    let key = planKey;
    if (key === 'plan_culinario') key = 'plan_pro';
    const plan = SERVICE_PLANS_CONFIG[key];
    if (!plan || plan.monthlyFee === 0) return 0;
    const period = billingPeriod || 'mensual';
    if (plan.fees && typeof plan.fees[period] !== 'undefined') {
      return plan.fees[period];
    }
    return plan.monthlyFee;
  }

  // ==========================================================================
  // GESTOR DE PRECIOS GLOBALES DE PLANES (PERSISTENCIA Y PERSONALIZACIÓN)
  // ==========================================================================
  const DEFAULT_PLANS_PRICING = {
    basico: 800000,
    estandar: 1000000,
    pro: 1200000,
    premium: 1500000,
    descTrimestral: 5,
    descSemestral: 10,
    mesesAnual: 10
  };

  function getPlansPricingConfig() {
    try {
      const stored = localStorage.getItem('dc_plans_pricing_config');
      if (stored) {
        const parsed = JSON.parse(stored);
        return Object.assign({}, DEFAULT_PLANS_PRICING, parsed);
      }
    } catch (e) {}
    return Object.assign({}, DEFAULT_PLANS_PRICING);
  }

  function applyPlansPricingConfig(cfg) {
    if (!cfg) return;
    const c = Object.assign({}, DEFAULT_PLANS_PRICING, cfg);

    // Actualizar Plan Básico
    if (SERVICE_PLANS_CONFIG.plan_basico) {
      SERVICE_PLANS_CONFIG.plan_basico.monthlyFee = c.basico;
      SERVICE_PLANS_CONFIG.plan_basico.fees = {
        mensual: c.basico,
        trimestral: Math.round((c.basico * 3 * (1 - (c.descTrimestral / 100))) / 1000) * 1000,
        semestral: Math.round((c.basico * 6 * (1 - (c.descSemestral / 100))) / 1000) * 1000,
        anual: c.basico * c.mesesAnual
      };
    }

    // Actualizar Plan Estándar
    if (SERVICE_PLANS_CONFIG.plan_estandar) {
      SERVICE_PLANS_CONFIG.plan_estandar.monthlyFee = c.estandar;
      SERVICE_PLANS_CONFIG.plan_estandar.fees = {
        mensual: c.estandar,
        trimestral: Math.round((c.estandar * 3 * (1 - (c.descTrimestral / 100))) / 1000) * 1000,
        semestral: Math.round((c.estandar * 6 * (1 - (c.descSemestral / 100))) / 1000) * 1000,
        anual: c.estandar * c.mesesAnual
      };
    }

    // Actualizar Plan Pro
    if (SERVICE_PLANS_CONFIG.plan_pro) {
      SERVICE_PLANS_CONFIG.plan_pro.monthlyFee = c.pro;
      SERVICE_PLANS_CONFIG.plan_pro.fees = {
        mensual: c.pro,
        trimestral: Math.round((c.pro * 3 * (1 - (c.descTrimestral / 100))) / 1000) * 1000,
        semestral: Math.round((c.pro * 6 * (1 - (c.descSemestral / 100))) / 1000) * 1000,
        anual: c.pro * c.mesesAnual
      };
    }

    // Actualizar Plan Premium
    if (SERVICE_PLANS_CONFIG.plan_premium) {
      const premFee = c.premium || DEFAULT_PLANS_PRICING.premium;
      SERVICE_PLANS_CONFIG.plan_premium.monthlyFee = premFee;
      SERVICE_PLANS_CONFIG.plan_premium.fees = {
        mensual: premFee,
        trimestral: Math.round((premFee * 3 * (1 - (c.descTrimestral / 100))) / 1000) * 1000,
        semestral: Math.round((premFee * 6 * (1 - (c.descSemestral / 100))) / 1000) * 1000,
        anual: premFee * c.mesesAnual
      };
    }

    // Actualizar etiquetas en el select de index.html si está en el DOM
    const selPlan = document.getElementById('edit-company-service-plan');
    if (selPlan) {
      const optBasico = selPlan.querySelector('option[value="plan_basico"]');
      const optEstandar = selPlan.querySelector('option[value="plan_estandar"]');
      const optPro = selPlan.querySelector('option[value="plan_pro"]');
      if (optBasico) optBasico.textContent = `🥉 Plan Básico (12 Módulos) • ${formatMoney(c.basico)} / mes`;
      if (optEstandar) optEstandar.textContent = `🥈 Plan Estándar (15 Módulos) • ${formatMoney(c.estandar)} / mes`;
      if (optPro) optPro.textContent = `🚀 Plan Pro (17 Módulos + Culinario) • ${formatMoney(c.pro)} / mes`;
      const optPremium = selPlan.querySelector('option[value="plan_premium"]');
      if (optPremium) optPremium.textContent = `👑 Plan Premium (18 Módulos + Ing. del Menú) • ${formatMoney(c.premium || DEFAULT_PLANS_PRICING.premium)} / mes`;
    }

    const regSelPlan = document.getElementById('reg-service-plan');
    if (regSelPlan) {
      const optBasico = regSelPlan.querySelector('option[value="plan_basico"]');
      const optEstandar = regSelPlan.querySelector('option[value="plan_estandar"]');
      const optPro = regSelPlan.querySelector('option[value="plan_pro"]');
      if (optBasico) optBasico.textContent = `🥉 Plan Básico (12 Módulos) • ${formatMoney(c.basico)} / mes`;
      if (optEstandar) optEstandar.textContent = `🥈 Plan Estándar (15 Módulos) • ${formatMoney(c.estandar)} / mes`;
      if (optPro) optPro.textContent = `🚀 Plan Pro (17 Módulos + Culinario) • ${formatMoney(c.pro)} / mes`;
      const optPremium = regSelPlan.querySelector('option[value="plan_premium"]');
      if (optPremium) optPremium.textContent = `👑 Plan Premium (18 Módulos + Ing. del Menú) • ${formatMoney(c.premium || DEFAULT_PLANS_PRICING.premium)} / mes`;
    }
  }

  // Inicializar tarifas configuradas
  applyPlansPricingConfig(getPlansPricingConfig());

  function openManagePlanPricesModal() {
    const modal = document.getElementById('modal-manage-plan-prices');
    if (!modal) return;

    const cfg = getPlansPricingConfig();
    const inBasico = document.getElementById('cfg-fee-basico');
    const inEstandar = document.getElementById('cfg-fee-estandar');
    const inPro = document.getElementById('cfg-fee-pro');
    const inPremium = document.getElementById('cfg-fee-premium');
    const inTrim = document.getElementById('cfg-desc-trimestral');
    const inSem = document.getElementById('cfg-desc-semestral');
    const inAnual = document.getElementById('cfg-meses-anual');

    if (inBasico) inBasico.value = cfg.basico;
    if (inEstandar) inEstandar.value = cfg.estandar;
    if (inPro) inPro.value = cfg.pro;
    if (inPremium) inPremium.value = cfg.premium || DEFAULT_PLANS_PRICING.premium;
    if (inTrim) inTrim.value = cfg.descTrimestral;
    if (inSem) inSem.value = cfg.descSemestral;
    if (inAnual) inAnual.value = cfg.mesesAnual;

    function renderPreview() {
      const b = Number(inBasico?.value) || 0;
      const e = Number(inEstandar?.value) || 0;
      const p = Number(inPro?.value) || 0;
      const prem = Number(inPremium?.value) || 0;
      const dTrim = Number(inTrim?.value) || 0;
      const dSem = Number(inSem?.value) || 0;
      const mAnual = Number(inAnual?.value) || 10;

      const calc = (base, mult, desc) => Math.round((base * mult * (1 - (desc / 100))) / 1000) * 1000;

      const tbl = document.getElementById('tbl-live-pricing-preview');
      if (!tbl) return;
      tbl.innerHTML = `
        <tr style="border-bottom:1px solid #f1f5f9;">
          <td style="padding:6px 10px; text-align:left; font-weight:600;">🗓️ Mensual</td>
          <td style="padding:6px 10px;">${formatMoney(b)}</td>
          <td style="padding:6px 10px;">${formatMoney(e)}</td>
          <td style="padding:6px 10px; font-weight:700; color:#059669;">${formatMoney(p)}</td>
        </tr>
        <tr style="border-bottom:1px solid #f1f5f9; background:#f8fafc;">
          <td style="padding:6px 10px; text-align:left; font-weight:600;">📊 Trimestral (-${dTrim}%)</td>
          <td style="padding:6px 10px;">${formatMoney(calc(b, 3, dTrim))}</td>
          <td style="padding:6px 10px;">${formatMoney(calc(e, 3, dTrim))}</td>
          <td style="padding:6px 10px; font-weight:700; color:#059669;">${formatMoney(calc(p, 3, dTrim))}</td>
        </tr>
        <tr style="border-bottom:1px solid #f1f5f9;">
          <td style="padding:6px 10px; text-align:left; font-weight:600;">📈 Semestral (-${dSem}%)</td>
          <td style="padding:6px 10px;">${formatMoney(calc(b, 6, dSem))}</td>
          <td style="padding:6px 10px;">${formatMoney(calc(e, 6, dSem))}</td>
          <td style="padding:6px 10px; font-weight:700; color:#059669;">${formatMoney(calc(p, 6, dSem))}</td>
        </tr>
        <tr style="background:#fefce8; font-weight:700;">
          <td style="padding:6px 10px; text-align:left; color:#92400e;">🏆 Anual (${mAnual} meses)</td>
          <td style="padding:6px 10px; color:#92400e;">${formatMoney(b * mAnual)}</td>
          <td style="padding:6px 10px; color:#92400e;">${formatMoney(e * mAnual)}</td>
          <td style="padding:6px 10px; color:#059669;">${formatMoney(p * mAnual)}</td>
        </tr>
      `;
    }

    [inBasico, inEstandar, inPro, inPremium, inTrim, inSem, inAnual].forEach(input => {
      if (input) input.oninput = renderPreview;
    });

    renderPreview();
    modal.classList.remove('hidden');
    modal.style.display = 'flex';
  }

  function closeManagePlanPricesModal() {
    const modal = document.getElementById('modal-manage-plan-prices');
    if (modal) {
      modal.classList.add('hidden');
      modal.style.display = 'none';
    }
  }

