  function isLegitimateCompany(c) {
    if (!c) return false;
    const cid = String(c.id || '').trim().toLowerCase();
    if (!cid || FORBIDDEN_PHANTOM_COMPANY_IDS.has(cid)) return false;
    const cname = String(c.companyName || c.name || c.nombre || '').trim().toLowerCase();
    if (cname === 'delitas' || cname === 'klarens' || cname === 'restaurante sabor colombiano gourmet' || cname === 'auditoría financiera & control s.a.s.') return false;
    if (CANONICAL_AUTHENTIC_COMPANIES[c.id] || CANONICAL_AUTHENTIC_COMPANIES[cid]) return true;
    if (cid === 'comp_demo_pruebas_sandbox') return true;
    if (cid.startsWith('comp_')) return true;
    return false;
  }
  window.isLegitimateCompany = isLegitimateCompany;

  function initDatabase() {
    // 1. Limpieza y blindaje estricto de localStorage de empresas (STORAGE_KEY)
    try {
      const existing = localStorage.getItem(STORAGE_KEY);
      let list = [];
      if (existing) {
        const parsed = JSON.parse(existing);
        if (Array.isArray(parsed)) {
          list = parsed.filter(c => isLegitimateCompany(c));
        }
      }
      const map = new Map(list.map(c => [c.id, c]));
      Object.values(CANONICAL_AUTHENTIC_COMPANIES).forEach(can => {
        if (!map.has(can.id)) {
          map.set(can.id, { ...can });
        } else {
          const c = map.get(can.id);
          if (!c.companyName || c.companyName === can.id || c.companyName === 'Empresa') c.companyName = can.companyName;
          if (!c.nit) c.nit = can.nit;
          if (!c.email) c.email = can.email;
          if (!c.address) c.address = can.address;
          if (!c.phone) c.phone = can.phone;
          if (!c.contactName) c.contactName = can.contactName;
          if (!c.taxRegime) c.taxRegime = can.taxRegime;
          if (!c.servicePlan) c.servicePlan = can.servicePlan;
          if (!c.contractFee) c.contractFee = can.contractFee;
          if (!c.billingPeriod) c.billingPeriod = can.billingPeriod;
          if (!c.userType) c.userType = can.userType;
          if (!c.role) c.role = can.role;
          if (!c.enabledModules || !Array.isArray(c.enabledModules) || c.enabledModules.length === 0) c.enabledModules = [...can.enabledModules];
        }
      });
      localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(map.values())));
    } catch (e) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(Object.values(CANONICAL_AUTHENTIC_COMPANIES)));
    }

    // 2. Limpieza estricta de puntos de auto-backup pre-update
    try {
      const autoBackups = localStorage.getItem('dc_auto_backup_points');
      if (autoBackups) {
        const parsedB = JSON.parse(autoBackups);
        if (Array.isArray(parsedB)) {
          parsedB.forEach(pt => {
            if (pt && Array.isArray(pt.companies)) {
              pt.companies = pt.companies.filter(c => isLegitimateCompany(c));
            }
          });
          localStorage.setItem('dc_auto_backup_points', JSON.stringify(parsedB));
        }
      }
    } catch (eAuto) {}

    // 3. Limpieza de sesión si hubiese quedado seleccionada una empresa no autorizada
    try {
      const sess = sessionStorage.getItem(SESSION_KEY);
      if (sess) {
        const parsedS = JSON.parse(sess);
        if (parsedS && parsedS.company && !isLegitimateCompany(parsedS.company)) {
          sessionStorage.removeItem(SESSION_KEY);
        }
      }
    } catch (eSess) {}
  }

  let inMemoryCompanies = null;

  function getCompanies() {
    let comps = [];
    if (inMemoryCompanies && Array.isArray(inMemoryCompanies) && inMemoryCompanies.length > 0) {
      comps = inMemoryCompanies.filter(c => isLegitimateCompany(c));
    } else {
      try {
        const data = localStorage.getItem(STORAGE_KEY);
        if (data) {
          const rawParsed = JSON.parse(data);
          if (Array.isArray(rawParsed)) {
            comps = rawParsed.filter(c => isLegitimateCompany(c));
          }
        }
      } catch (e) {}
    }

    // Blindaje canónico absoluto: siempre asegurar que las 6 empresas auténticas existan
    const compMap = new Map(comps.map(c => [c.id, c]));
    Object.values(CANONICAL_AUTHENTIC_COMPANIES).forEach(can => {
      if (!compMap.has(can.id)) {
        compMap.set(can.id, { ...can });
      } else {
        const c = compMap.get(can.id);
        if (!c.companyName || c.companyName === can.id || c.companyName === 'Empresa') c.companyName = can.companyName;
        if (!c.nit) c.nit = can.nit;
        if (!c.email) c.email = can.email;
        if (!c.address) c.address = can.address;
        if (!c.phone) c.phone = can.phone;
        if (!c.contactName) c.contactName = can.contactName;
        if (!c.taxRegime) c.taxRegime = can.taxRegime;
        if (!c.servicePlan) c.servicePlan = can.servicePlan;
        if (!c.contractFee) c.contractFee = can.contractFee;
        if (!c.billingPeriod) c.billingPeriod = can.billingPeriod;
        if (!c.userType) c.userType = can.userType;
        if (!c.role) c.role = can.role;
        if (!c.enabledModules || !Array.isArray(c.enabledModules) || c.enabledModules.length === 0) c.enabledModules = [...can.enabledModules];
      }
    });

    const parsed = Array.from(compMap.values());
    parsed.forEach(c => {
      if (!c) return;
      c.companyName = (c.companyName || c.nombre || c.name || c.id || "Empresa").trim();
      c.email = (c.email || c.correo || "").trim().toLowerCase();
      c.nit = (c.nit || c.companyNit || "").trim();
      c.address = (c.address || c.direccion || "").trim();
      c.phone = (c.phone || c.telefono || "").trim();
      if (!c.enabledModules || !Array.isArray(c.enabledModules)) {
        c.enabledModules = [...ALL_SYSTEM_MODULES];
      } else {
        c.enabledModules = c.enabledModules.filter(m => m !== 'tab-13-estadisticas-ventas' && m !== 'tab-inventario-alimentos-medicamentos');
      }
      if (!c.userType) {
        c.userType = (c.role === 'client' || c.role === 'lite') ? 'lite' : 'master';
      }
      if (!c.status) {
        c.status = 'activa';
      }
      if (!c.servicePlan || c.servicePlan === 'plan_culinario') {
        c.servicePlan = (c.id === 'comp_demo_pruebas_sandbox' || c.companyName === 'Natal Coffee') ? 'plan_premium' : 'plan_estandar';
      }
      if (c.companyName === 'Natal Coffee' || c.id === 'comp_demo_pruebas_sandbox') {
        c.servicePlan = 'plan_premium';
        if (!c.enabledModules || !c.enabledModules.includes('tab-menu-engineering')) {
          c.enabledModules = [...SERVICE_PLANS_CONFIG.plan_premium.modules];
        }
      }
      if (!c.billingPeriod) {
        c.billingPeriod = 'mensual';
      }
      if (typeof c.contractFee === 'undefined' || c.contractFee === 320000) {
        c.contractFee = (c.id === 'comp_demo_pruebas_sandbox') ? 750000 : 1000000;
      }
      if (!c.customModules) {
        c.customModules = [];
      }
      if (c.password && c.id !== 'comp_master_dc') {
        if (typeof c.passwordMaster === 'undefined') {
          c.passwordMaster = (c.userType === 'master' || c.role === 'master') ? c.password : '';
        }
        if (typeof c.passwordLite === 'undefined') {
          c.passwordLite = (c.userType === 'lite' || c.role === 'lite' || c.role === 'client') ? c.password : '123456';
        }
      }
      // Migración de datos de ventas si tienen formato antiguo por factura — limpiar
      if (c.businessData && c.businessData.sales && c.businessData.sales.length > 0 && c.businessData.sales[0].invoice) {
        c.businessData.sales = [];
      }
      // Limpiar esquemas corruptos con encabezados binarios
      if (c.moduleSchemas) {
        Object.keys(c.moduleSchemas).forEach(mk => {
          const sch = c.moduleSchemas[mk];
          if (Array.isArray(sch) && sch.length <= 1) {
            delete c.moduleSchemas[mk];
          }
        });
      }
    });

    inMemoryCompanies = parsed;
    return parsed;
  }

