  let firestoreDb = null;
  let isCloudIncoming = false; // Bandera para evitar loops recursivos al recibir cambios remotos
  let syncDebounceTimer = null;

  function updateCloudSyncBadges(state, text) {
    const badges = [
      document.getElementById('master-cloud-sync-status'),
      document.getElementById('dash-cloud-sync-status')
    ];
    badges.forEach(b => {
      if (!b) return;
      b.className = 'cloud-sync-badge';
      if (state === 'syncing') {
        b.classList.add('syncing');
      } else if (state === 'offline') {
        b.classList.add('offline');
      } else if (state === 'error') {
        b.classList.add('error');
      }
      const icon = b.querySelector('i');
      if (icon) {
        if (state === 'syncing') icon.className = 'fa-solid fa-arrows-rotate';
        else if (state === 'offline') icon.className = 'fa-solid fa-cloud-slash';
        else if (state === 'error') icon.className = 'fa-solid fa-triangle-exclamation';
        else icon.className = 'fa-solid fa-cloud';
      }
      const span = b.querySelector('.sync-text');
      if (span) {
        span.textContent = text || 'Sincronizado';
      }
    });
  }

  function initFirebaseCloudSync() {
    try {
      if (typeof firebase === 'undefined') {
        console.warn('Firebase SDK no disponible. Operando en modo local.');
        updateCloudSyncBadges('offline', 'Modo Local');
        return;
      }

      if (!firebase.apps.length) {
        firebase.initializeApp(firebaseConfig);
      }
      firestoreDb = firebase.firestore();

      const connectSnapshot = () => {
      // Sincronización en tiempo real de tarifas globales de planes
      try {
        firestoreDb.collection('system').doc('plans_pricing').onSnapshot((doc) => {
          if (doc && doc.exists) {
            const remoteCfg = doc.data();
            if (remoteCfg && remoteCfg.basico) {
              localStorage.setItem('dc_plans_pricing_config', JSON.stringify(remoteCfg));
              applyPlansPricingConfig(remoteCfg);
            }
          }
        }, (err) => console.warn('Firestore plans_pricing listener offline:', err));
      } catch (e) {
        console.warn('Error setting up plans_pricing listener:', e);
      }

        updateCloudSyncBadges('syncing', 'Conectando nube...');
        firestoreDb.collection('companies').onSnapshot((snapshot) => {
          handleCloudSnapshot(snapshot);
        }, (error) => {
          console.error('Error al escuchar cambios en Firestore:', error);
          updateCloudSyncBadges('offline', 'Modo Local (Offline)');
        });
      };

      // Habilitar persistencia offline sin bloquear onSnapshot
      firestoreDb.enablePersistence({ synchronizeTabs: true })
        .then(() => {
          connectSnapshot();
        })
        .catch(err => {
          console.log('Nota de persistencia offline Firestore:', err ? err.code : err);
          connectSnapshot();
        });

    } catch (e) {
      console.error('Error al inicializar Firebase Firestore:', e);
      updateCloudSyncBadges('offline', 'Modo Local');
    }
  }

  function handleCloudSnapshot(snapshot) {
    if (snapshot.empty) {
      // Blindaje de Seguridad: Si Firestore reporta snapshot vacío por reconexión o permisos,
      // NUNCA auto-subir almacenamiento local obsoleto para evitar resurrección de empresas fantasma.
      console.warn('[Blindaje Nube] Firestore snapshot vacío o en espera. No se sobreescribe la nube.');
      updateCloudSyncBadges('synced', 'Nube Lista');
      return;
    }

    const cloudCompanies = [];
    snapshot.forEach(doc => {
      const data = doc.data();
      if (data) {
        data.id = data.id || doc.id;
        if (!isLegitimateCompany(data)) {
          console.warn('[Blindaje Nube] Se bloqueó documento fantasma o no autorizado recibido de Firestore:', data.id);
          return;
        }
        const can = CANONICAL_AUTHENTIC_COMPANIES[data.id];
        if (can) {
          data.companyName = (data.companyName && data.companyName !== data.id && data.companyName !== 'Empresa') ? data.companyName.trim() : can.companyName;
          data.email = data.email || can.email;
          data.nit = data.nit || can.nit;
          data.address = data.address || can.address;
          data.phone = data.phone || can.phone;
          data.contactName = data.contactName || can.contactName;
          data.taxRegime = data.taxRegime || can.taxRegime;
          data.servicePlan = data.servicePlan || can.servicePlan;
          data.contractFee = data.contractFee || can.contractFee;
          data.billingPeriod = data.billingPeriod || can.billingPeriod;
          data.userType = data.userType || can.userType;
          data.role = data.role || can.role;
        } else {
          data.companyName = (data.companyName || data.nombre || data.name || data.id || 'Empresa').trim();
          data.email = (data.email || data.correo || '').trim().toLowerCase();
          data.nit = (data.nit || data.companyNit || '').trim();
          data.address = (data.address || data.direccion || '').trim();
          data.phone = (data.phone || data.telefono || '').trim();
        }
        if (Array.isArray(data.enabledModules)) {
          data.enabledModules = data.enabledModules.filter(m => m !== 'tab-inventario-alimentos-medicamentos' && m !== 'tab-13-estadisticas-ventas');
        }
        cloudCompanies.push(data);
      }
    });

    if (cloudCompanies.length === 0) return;

    // Actualizamos el estado local sin disparar eco hacia la nube
    isCloudIncoming = true;
    try {
      const localComps = getCompanies();
      const localMap = new Map();
      localComps.forEach(c => localMap.set(c.id, c));

      // Las empresas de la nube son la fuente de verdad multi-dispositivo
      cloudCompanies.forEach(c => {
        const can = CANONICAL_AUTHENTIC_COMPANIES[c.id];
        if (can) {
          if (!c.companyName || c.companyName === c.id || c.companyName === 'Empresa') c.companyName = can.companyName;
          if (!c.nit) c.nit = can.nit;
          if (!c.email) c.email = can.email;
          if (!c.address) c.address = can.address;
          if (!c.phone) c.phone = can.phone;
          if (!c.contactName) c.contactName = can.contactName;
          if (!c.taxRegime) c.taxRegime = can.taxRegime;
          if (!c.servicePlan) c.servicePlan = can.servicePlan;
          if (!c.contractFee) c.contractFee = can.contractFee;
          if (!c.billingPeriod) c.billingPeriod = can.billingPeriod;
          if (!c.userType) c.userType = can.userType;
          if (!c.role) c.role = can.role;
          if (!c.enabledModules || !Array.isArray(c.enabledModules) || c.enabledModules.length === 0) c.enabledModules = [...can.enabledModules];
        }
        const existing = localMap.get(c.id);
        if (!c.enabledModules && existing && existing.enabledModules) {
          c.enabledModules = existing.enabledModules;
        }
        // Si la nube trae businessData y selectedPeriod (ej. subido por el conector POS)
        if (c.businessData && c.selectedPeriod) {
          if (!c.periods) c.periods = {};
          c.periods[c.selectedPeriod] = c.businessData;
        }
        // Si el usuario en este navegador tiene cambios locales sucios (dirty), preservarlos;
        // de lo contrario, la nube manda (la nube prevalece sobre la memoria local)
        if (window._currentPeriodDirty && currentCompany && currentCompany.id === c.id && currentCompany.periods) {
          c.periods = { ...(c.periods || {}), ...currentCompany.periods };
        } else if (currentCompany && currentCompany.id === c.id && currentCompany.periods) {
          c.periods = { ...currentCompany.periods, ...(c.periods || {}) };
        } else if (existing && existing.periods) {
          c.periods = { ...existing.periods, ...(c.periods || {}) };
        }
        localMap.set(c.id, c);
      });

      // Blindar que TODAS las empresas canónicas SIEMPRE permanezcan en memoria local
      Object.values(CANONICAL_AUTHENTIC_COMPANIES).forEach(can => {
        if (!localMap.has(can.id)) {
          localMap.set(can.id, { ...can });
        }
      });

      // Mantener únicamente las empresas registradas en la nube y las canónicas legítimas
      const cloudIds = new Set(cloudCompanies.map(c => c.id));
      const merged = Array.from(localMap.values()).filter(c => (cloudIds.has(c.id) || CANONICAL_AUTHENTIC_COMPANIES[c.id]) && isLegitimateCompany(c));
      merged.forEach(c => ensureCompanyPeriods(c));

      inMemoryCompanies = merged;

      try {
        const lean = merged.map(c => {
          const copy = { ...c };
          delete copy.periods;
          delete copy.businessData;
          return copy;
        });
        localStorage.setItem(STORAGE_KEY, JSON.stringify(lean));
      } catch (eQuota) {
        console.warn('Nota de cuota localStorage al sincronizar nube:', eQuota);
      }
      checkAndCreatePreUpdateAutoBackup();
      updateCloudSyncBadges('synced', 'Sincronizado');

      // Si el usuario tiene una empresa abierta en pantalla, actualizarla en vivo
      if (currentCompany) {
        const updated = merged.find(c => c.id === currentCompany.id);
        if (updated) {
          // NUNCA permitir que la sincronización de la colección de empresas borre los períodos de la subcolección
          if (currentCompany.periods && Object.keys(currentCompany.periods).length > 0) {
            updated.periods = { ...(updated.periods || {}), ...currentCompany.periods };
          }
          ensureCompanyPeriods(updated);
          currentCompany = updated;
          sessionStorage.setItem(SESSION_KEY, JSON.stringify({ company: currentCompany, role: currentUserRole }));

          // Asegurar que la subcolección de períodos esté conectada y sincronizada
          if (typeof attachActivePeriodsListener === 'function') {
            attachActivePeriodsListener(currentCompany.id);
          }

          // Si el dashboard está visible, re-renderizar módulos y cabecera
          if (dashboardSection && !dashboardSection.classList.contains('hidden')) {
            configureCompanyTabs(currentCompany);
            renderAll14Modules();
            updateAuditPeriodBadge();
            if (dashCompanyName) dashCompanyName.textContent = currentCompany.companyName;
            if (detailName) { detailName.textContent = currentCompany.companyName; detailName.title = currentCompany.companyName || ''; }
            if (detailNit) { detailNit.textContent = currentCompany.nit || 'Sin Registrar'; detailNit.title = currentCompany.nit || ''; }
            if (detailEmail) { detailEmail.textContent = currentCompany.email || 'Sin Registrar'; detailEmail.title = currentCompany.email || ''; }
            if (detailPhone) { detailPhone.textContent = currentCompany.phone || 'Sin Registrar'; detailPhone.title = currentCompany.phone || ''; }
            if (detailContact) { detailContact.textContent = currentCompany.contactName || 'Sin Registrar'; detailContact.title = currentCompany.contactName || ''; }
            if (detailAddress) { detailAddress.textContent = currentCompany.address || 'Sin Registrar'; detailAddress.title = currentCompany.address || ''; }
          }
        }
      }

      // Si el panel de selección de empresas master está visible, refrescar
      if (masterCompaniesSection && !masterCompaniesSection.classList.contains('hidden')) {
        renderMasterCompaniesGrid(inputSearchCompanies ? inputSearchCompanies.value : '');
      }

      // Si la Torre de Control está visible en pantalla, refrescar en vivo
      const panelTower = document.getElementById('master-control-tower-panel');
      if (panelTower && !panelTower.classList.contains('hidden')) {
        renderControlTower();
      }

    } catch (err) {
      console.error('Error al procesar datos recibidos de la nube:', err);
    } finally {
      setTimeout(() => { isCloudIncoming = false; }, 150);
    }
  }

  function pushLocalCompaniesToCloud(companies) {
    if (!firestoreDb || !Array.isArray(companies) || companies.length === 0) return;
    const safeCompanies = companies.filter(c => isLegitimateCompany(c));
    if (safeCompanies.length === 0) return;
    try {
      const batch = firestoreDb.batch();
      safeCompanies.forEach(comp => {
        if (comp && comp.id && isLegitimateCompany(comp)) {
          const docRef = firestoreDb.collection('companies').doc(comp.id);
          const clean = JSON.parse(JSON.stringify(comp));
          clean._syncedAt = Date.now();
          const compPeriods = clean.periods;
          delete clean.periods;
          delete clean.businessData;
          batch.set(docRef, clean, { merge: true });

          if (compPeriods && typeof compPeriods === 'object') {
            Object.keys(compPeriods).forEach(pk => {
              const pRef = firestoreDb.collection('companies').doc(comp.id).collection('periods').doc(pk);
              batch.set(pRef, compPeriods[pk], { merge: true });
            });
          }
        }
      });
      batch.commit()
        .then(() => updateCloudSyncBadges('synced', 'Sincronizado'))
        .catch(err => {
          console.error('Error al subir empresas a Firestore:', err);
          updateCloudSyncBadges('offline', 'Error de Nube');
        });
    } catch (e) {
      console.error('Error en batch inicial Firestore:', e);
    }
  }

  function markCurrentPeriodDirty() {
    window._currentPeriodDirty = true;
  }
  window.markCurrentPeriodDirty = markCurrentPeriodDirty;

  function syncCompaniesToCloud(companies) {
    if (!firestoreDb || isCloudIncoming || !Array.isArray(companies)) return;
    const safeCompanies = companies.filter(c => isLegitimateCompany(c));
    if (safeCompanies.length === 0) return;

    updateCloudSyncBadges('syncing', 'Sincronizando...');
    clearTimeout(syncDebounceTimer);
    syncDebounceTimer = setTimeout(() => {
      try {
        const batch = firestoreDb.batch();
        safeCompanies.forEach(comp => {
          if (comp && comp.id && isLegitimateCompany(comp)) {
            const docRef = firestoreDb.collection('companies').doc(comp.id);
            const clean = JSON.parse(JSON.stringify(comp));
            clean._syncedAt = Date.now();
            const compPeriods = clean.periods;
            // NUNCA eliminar businessData con FieldValue.delete() para no borrar subidas del conector
            delete clean.periods;
            delete clean.businessData;

            batch.set(docRef, clean, { merge: true });

            // Sincronizar a la subcolección 'periods' ÚNICAMENTE si el usuario modificó datos en pantalla (dirty)
            if (window._currentPeriodDirty && currentCompany && comp.id === currentCompany.id) {
              const activePk = clean.selectedPeriod || currentCompany.selectedPeriod;
              const periodDataToSave = (compPeriods && activePk && compPeriods[activePk]) 
                ? compPeriods[activePk] 
                : (currentCompany.periods && activePk ? currentCompany.periods[activePk] : null);

              if (periodDataToSave && !checkIsPeriodEmpty(periodDataToSave)) {
                const pRef = firestoreDb.collection('companies').doc(comp.id).collection('periods').doc(activePk);
                batch.set(pRef, periodDataToSave, { merge: true });
              }
            }
          }
        });
        batch.commit()
          .then(() => {
            window._currentPeriodDirty = false;
            updateCloudSyncBadges('synced', 'Sincronizado');
          })
          .catch(err => {
            console.error('Error al guardar en Firestore:', err);
            updateCloudSyncBadges('offline', 'Modo Local');
          });
      } catch (err) {
        console.error('Error en sync batch a Firestore:', err);
        updateCloudSyncBadges('offline', 'Modo Local');
      }
    }, 300);
  }

  function deleteCompanyFromCloud(companyId) {
    if (!firestoreDb || !companyId) return;
    updateCloudSyncBadges('syncing', 'Actualizando nube...');
    firestoreDb.collection('companies').doc(companyId).delete()
      .then(() => {
        updateCloudSyncBadges('synced', 'Sincronizado');
      })
      .catch(err => {
        console.error('Error al eliminar de Firestore:', err);
        updateCloudSyncBadges('offline', 'Modo Local');
      });
  }

  function saveCompanies(companies) {
    const safeCompanies = (companies || []).filter(c => isLegitimateCompany(c));
    inMemoryCompanies = safeCompanies;
    try {
      const lean = safeCompanies.map(c => {
        const copy = { ...c };
        delete copy.periods;
        delete copy.businessData;
        return copy;
      });
      localStorage.setItem(STORAGE_KEY, JSON.stringify(lean));
    } catch (eQuota) {
      console.warn('LocalStorage quota guardando empresas:', eQuota);
    }
    if (!isCloudIncoming) {
      syncCompaniesToCloud(safeCompanies);
    }
  }

  function updateCurrentCompanyData(isDataChange = false) {
    if (isDataChange) {
      window._currentPeriodDirty = true;
    }
    if (!currentCompany || !isLegitimateCompany(currentCompany)) return;
    try {
      const companies = getCompanies();
      let index = -1;
      if (currentCompany.id) {
        index = companies.findIndex(c => c.id === currentCompany.id);
      }
      if (index === -1 && currentCompany.email) {
        index = companies.findIndex(c => c.email && c.email.toLowerCase() === currentCompany.email.toLowerCase());
      }
      if (index !== -1) {
        companies[index] = currentCompany;
      } else {
        companies.push(currentCompany);
      }
      saveCompanies(companies);
      sessionStorage.setItem(SESSION_KEY, JSON.stringify({ company: currentCompany, role: currentUserRole }));
    } catch (err) {
      console.warn('Aviso en updateCurrentCompanyData:', err);
    }
  }

