  function showRegisterView() {
    document.body.classList.remove('auth-screen-active', 'theme-modern-slate', 'is-sandbox-preview');
    document.body.classList.add('register-screen-active');
    if (appContainer) {
      appContainer.classList.remove('wide-layout');
      appContainer.classList.remove('auth-web-mode');
    }
    if (authSection) {
      authSection.classList.remove('auth-card-web');
      authSection.classList.add('auth-card-register');
      authSection.classList.remove('hidden');
    }
    const heroPanel = document.getElementById('auth-hero-panel');
    if (heroPanel) heroPanel.style.display = 'none';

    if (masterCompaniesSection) masterCompaniesSection.classList.add('hidden');
    loginView.classList.add('hidden');
    registerView.classList.remove('hidden');

    // Mostrar selector de rol solo en sesión master
    const isMasterSess = sessionStorage.getItem('isMasterSession') === 'true';
    const roleSelectorBox = document.getElementById('reg-role-selector-box');
    const roleLiteNoticeBox = document.getElementById('reg-role-lite-notice-box');
    if (roleSelectorBox) roleSelectorBox.style.display = isMasterSess ? '' : 'none';
    if (roleLiteNoticeBox) roleLiteNoticeBox.style.display = isMasterSess ? 'none' : '';

    if (typeof initRegisterPlanControls === 'function') {
      initRegisterPlanControls();
    }

    // Adaptar texto del botón inferior de regreso según sesión
    const btnBack = document.getElementById('btn-back-login');
    if (btnBack) {
      btnBack.innerHTML = isMasterSess
        ? '<i class="fa-solid fa-arrow-left"></i> <span>Cancelar y Volver al Panel Master</span>'
        : '<i class="fa-solid fa-arrow-left"></i> <span>Regresar al Inicio de Sesión</span>';
    }

    window.scrollTo({ top: 0, behavior: 'smooth' });
    document.getElementById('reg-company-name').focus();
  }

  function handleCancelRegister() {
    registerForm.reset();
    document.body.classList.remove('register-screen-active');
    const heroPanel = document.getElementById('auth-hero-panel');
    if (heroPanel) heroPanel.style.display = '';
    if (authSection) authSection.classList.remove('auth-card-register');

    if (sessionStorage.getItem('isMasterSession') === 'true') {
      if (authSection) authSection.classList.add('hidden');
      if (registerView) registerView.classList.add('hidden');
      showMasterCompaniesView();
    } else {
      showLoginView();
    }
  }

  function showLoginView() {
    document.body.classList.remove('register-screen-active');
    const heroPanel = document.getElementById('auth-hero-panel');
    if (heroPanel) heroPanel.style.display = '';
    if (authSection) {
      authSection.classList.remove('auth-card-register');
    }

    if (appContainer) {
      appContainer.classList.remove('wide-layout');
      if (document.body.classList.contains('is-web-version') && !document.body.classList.contains('is-mobile-app')) {
        appContainer.classList.add('auth-web-mode');
        document.body.classList.add('auth-screen-active');
      }
    }
    if (authSection && document.body.classList.contains('is-web-version') && !document.body.classList.contains('is-mobile-app')) {
      authSection.classList.add('auth-card-web');
    }
    if (masterCompaniesSection) masterCompaniesSection.classList.add('hidden');
    registerView.classList.add('hidden');
    loginView.classList.remove('hidden');
    document.getElementById('login-email').focus();
  }

  function applyRole(role) {
    currentUserRole = (role === 'lite' || role === 'client') ? 'lite' : 'master';

    if (currentUserRole === 'lite') {
      document.body.classList.remove('role-master');
      document.body.classList.add('role-client');
      document.body.classList.add('role-lite');
      if (userRoleBadge) {
        userRoleBadge.className = 'badge-role lite';
        userRoleBadge.title = 'Rol: Usuario Lite (Solo Lectura)';
        userRoleBadge.innerHTML = '<i class="fa-solid fa-eye"></i> Usuario Lite';
        userRoleBadge.style.whiteSpace = 'nowrap';
      }
    } else {
      document.body.classList.remove('role-client');
      document.body.classList.remove('role-lite');
      document.body.classList.add('role-master');
      if (userRoleBadge) {
        userRoleBadge.className = 'badge-role master';
        userRoleBadge.title = 'Rol: Usuario Master (Acceso Total)';
        userRoleBadge.innerHTML = '<i class="fa-solid fa-crown"></i> Usuario Master';
        userRoleBadge.style.whiteSpace = 'nowrap';
      }
    }
  }

  function activateTab(targetTabId) {
    if (!targetTabId) return;

    if (currentCompany && Array.isArray(currentCompany.enabledModules) && currentCompany.id !== 'comp_demo_pruebas_sandbox') {
      if (!currentCompany.enabledModules.includes(targetTabId)) {
        console.warn(`Módulo ${targetTabId} no está habilitado para ${currentCompany.companyName}.`);
        return;
      }
    }

    // Actualizar botones de pestaña
    document.querySelectorAll('#dynamic-tabs-nav .tab-btn').forEach(btn => {
      if (btn.getAttribute('data-tab') === targetTabId) {
        btn.classList.add('active');
        btn.scrollIntoView({ behavior: 'smooth', inline: 'nearest', block: 'nearest' });
      } else {
        btn.classList.remove('active');
      }
    });

    // Actualizar botones de módulos culinarios en la cabecera azul
    document.querySelectorAll('.btn-profile-culinary').forEach(btn => {
      if (btn.getAttribute('data-tab-target') === targetTabId) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    });

    // Actualizar paneles de contenido
    document.querySelectorAll('.tab-content').forEach(content => {
      if (content.id === targetTabId) {
        content.classList.add('active');
      } else {
        content.classList.remove('active');
      }
    });

    // Desplazar automáticamente la vista a la parte superior del informe
    const periodBar = document.getElementById('main-period-control-bar');
    if (periodBar) {
      const navRect = periodBar.getBoundingClientRect();
      const targetY = window.pageYOffset + navRect.top - 14;
      window.scrollTo({ top: Math.max(0, targetY), behavior: 'smooth' });
    }

    // Resetear el scroll interno de tablas y contenedores del módulo activo
    const activePanel = document.getElementById(targetTabId);
    if (activePanel) {
      activePanel.scrollTop = 0;
      activePanel.querySelectorAll('.table-responsive, .table-container, .tower-table-wrapper').forEach(el => {
        el.scrollTop = 0;
        el.scrollLeft = 0;
      });
    }

    // Sincronizar Cápsula de Navegación y Mega-Menú (Modo Pruebas)
    if (typeof updateCapsuleSelector === 'function') {
      updateCapsuleSelector(targetTabId);
    }

    // Sincronizar botón unificado de Descargar Excel en la barra superior de control
    const tabToModuleExcelMap = {
      'tab-1-ventas-diarias': 'sales',
      'tab-2-ventas-forma-pago': 'paymentMethods',
      'tab-3-productos-diarios': 'dailyProducts',
      'tab-4-productos-mensuales': 'monthlyProducts',
      'tab-5-compras-proveedor': 'suppliers',
      'tab-6-compras-insumos': 'supplies',
      'tab-7-gastos-mensuales': 'expenses',
      'tab-almuerzo-personal': 'staffLunch',
      'tab-bajas-desperdicios': 'waste',
      'tab-8-nomina': 'payroll',
      'tab-9-propinas-vendedor': 'tips',
      'tab-propinas': 'tips',
      'tab-10-costos-ventas': 'cogs',
      'tab-11-costos-compras': 'purchaseCosts',
      'tab-12-comparativo-ventas': 'monthlyComparison',
      'tab-14-analisis-mensual': 'monthlyPL',
      'tab-15-consolidado-anual': 'monthlyPL',
      'tab-0-dashboard': 'sales',
      'tab-reportes-graficos': 'sales',
      'tab-menu-engineering': 'monthlyProducts',
      'tab-recetario': 'dailyProducts',
      'tab-cotizador': 'dailyProducts'
    };
    const topDownloadBtn = document.getElementById('btn-topbar-download-excel');
    if (topDownloadBtn) {
      const modKey = tabToModuleExcelMap[targetTabId] || 'sales';
      topDownloadBtn.setAttribute('data-module', modKey);
    }

    // Si se activa reportes gráficos, refrescar
    if (targetTabId === 'tab-reportes-graficos') {
      setTimeout(() => {
        if (typeof renderChartsModule === 'function') {
          renderChartsModule(selectChartPeriod ? selectChartPeriod.value : 'month');
        }
      }, 50);
    }

    // Si se activa consolidado anual, refrescar
    if (targetTabId === 'tab-15-consolidado-anual') {
      setTimeout(() => {
        if (typeof renderAnnualConsolidatedModule === 'function') {
          renderAnnualConsolidatedModule();
        }
      }, 50);
    }

    // Si se activa Costos de Ventas (COGS), refrescar
    if (targetTabId === 'tab-recetario') {
      setTimeout(() => { if (typeof renderRecipesModule === 'function') renderRecipesModule(); }, 50);
    }
    if (targetTabId === 'tab-cotizador') {
      setTimeout(() => { if (typeof renderQuoterModule === 'function') renderQuoterModule(); }, 50);
    }
    if (targetTabId === 'tab-menu-engineering') {
      setTimeout(() => { if (typeof renderMenuEngineeringModule === 'function') renderMenuEngineeringModule(); }, 50);
    }
    if (targetTabId === 'tab-0-dashboard') {
      setTimeout(() => {
        if (typeof renderExecutiveDashboard === 'function') renderExecutiveDashboard();
      }, 50);
    }
    if (targetTabId === 'tab-10-costos-ventas') {
      setTimeout(() => {
        if (typeof renderCogsModule === 'function') {
          renderCogsModule();
        }
      }, 50);
    }

    // Si se activa Productos Mensuales Vendidos, refrescar
    if (targetTabId === 'tab-4-productos-mensuales') {
      setTimeout(() => {
        if (typeof renderMonthlyProductsModule === 'function') {
          renderMonthlyProductsModule();
        }
      }, 50);
    }
  }

  function configureCompanyTabs(company) {
    const tabsNav = document.getElementById('dynamic-tabs-nav');
    const tabsContainer = document.querySelector('.business-tabs-container');
    if (!tabsNav) return;

    // Eliminar pestañas y contenidos personalizados previos si existen
    document.querySelectorAll('.custom-module-tab').forEach(el => el.remove());
    document.querySelectorAll('.custom-tab-content').forEach(el => el.remove());

    const enabledModules = company.enabledModules || ALL_SYSTEM_MODULES;

    // Control de visibilidad de la Suite Culinaria en la cabecera de la empresa (pastillas redundantes ocultas)
    const culinaryActions = document.getElementById('company-profile-culinary-actions');
    if (culinaryActions) {
      culinaryActions.classList.add('hidden');
      culinaryActions.style.display = 'none';
    }

    // Actualizar badges de Plan y Periodicidad de contrato en la cabecera
    const badgePlan = document.getElementById('company-service-plan-badge');
    const lblPlan = document.getElementById('lbl-service-plan');
    const badgeContractPeriod = document.getElementById('company-contract-period-badge');
    const lblContractPeriod = document.getElementById('lbl-contract-period');

    if (company) {
      let sPlanKey = company.servicePlan || ((company.id === 'comp_demo_pruebas_sandbox' || company.companyName === 'Natal Coffee') ? 'plan_premium' : 'plan_estandar');
      if (sPlanKey === 'plan_culinario') sPlanKey = 'plan_pro';
      const planConfig = (typeof SERVICE_PLANS_CONFIG !== 'undefined' && SERVICE_PLANS_CONFIG[sPlanKey]) ? SERVICE_PLANS_CONFIG[sPlanKey] : null;

      if (badgePlan && lblPlan) {
        lblPlan.textContent = planConfig ? planConfig.name : 'Plan Estándar';
        const iconPlan = badgePlan.querySelector('i');
        if (iconPlan && planConfig) {
          iconPlan.className = `fa-solid ${planConfig.icon || 'fa-layer-group'} text-gold`;
        }
        badgePlan.classList.remove('hidden');
      }

      if (badgeContractPeriod && lblContractPeriod) {
        const billingLabels = {
          mensual: 'Cobro Mensual',
          trimestral: 'Cobro Trimestral',
          semestral: 'Cobro Semestral',
          anual: 'Cobro Anual'
        };
        const bPeriod = company.billingPeriod || 'mensual';
        lblContractPeriod.textContent = billingLabels[bPeriod] || 'Cobro Mensual';
        badgeContractPeriod.classList.remove('hidden');
      }
    }
    const standardButtons = tabsNav.querySelectorAll('.tab-btn:not(.custom-module-tab)');
    let visibleCount = 0;

    standardButtons.forEach(btn => {
      const tabId = btn.getAttribute('data-tab');
      if (enabledModules.includes(tabId)) {
        btn.style.display = 'inline-flex';
        visibleCount++;
      } else {
        btn.style.display = 'none';
        btn.classList.remove('active');
        const content = document.getElementById(tabId);
        if (content) content.classList.remove('active');
      }
    });

    // Si la pestaña actualmente activa fue deshabilitada o no está visible, activar la primera visible
    const currentActiveBtn = tabsNav.querySelector('.tab-btn.active');
    if (!currentActiveBtn || currentActiveBtn.style.display === 'none') {
      const firstVisibleBtn = Array.from(standardButtons).find(b => b.style.display !== 'none');
      if (firstVisibleBtn) {
        activateTab(firstVisibleBtn.getAttribute('data-tab'));
      }
    }

    // Inyectar módulos personalizados / futuros configurados para esta empresa
    if (company.customModules && Array.isArray(company.customModules) && company.customModules.length > 0) {
      company.customModules.forEach((modName, idx) => {
        const customTabId = `tab-custom-${idx + 1}`;
        visibleCount++;

        // Crear botón de pestaña
        const customBtn = document.createElement('button');
        customBtn.className = 'tab-btn custom-module-tab';
        customBtn.setAttribute('data-tab', customTabId);
        customBtn.setAttribute('role', 'tab');
        customBtn.innerHTML = `
          <i class="fa-solid fa-puzzle-piece"></i>
          <span>${modName}</span>
        `;
        tabsNav.appendChild(customBtn);

        // Crear sección de contenido
        const customContent = document.createElement('div');
        customContent.id = customTabId;
        customContent.className = 'tab-content custom-tab-content';
        customContent.innerHTML = `
          <div class="tab-content-header">
            <div>
              <h4 class="tab-title"><i class="fa-solid fa-puzzle-piece"></i> ${modName}</h4>
              <p class="tab-subtitle">Módulo personalizado configurado para ${company.companyName}</p>
            </div>
            <div class="module-action-group master-only">
              <span class="badge-role master"><i class="fa-solid fa-crown"></i> Control Master</span>
            </div>
          </div>

          <div class="custom-module-banner">
            <div class="banner-icon">
              <i class="fa-solid fa-sliders"></i>
            </div>
            <h4>Módulo Personalizado Activo: ${modName}</h4>
            <p>Este módulo ha sido activado y parametrizado especialmente según la estructura operativa de tu negocio en <strong>DC Asesorías</strong>. Los datos reportados aquí se consolidan automáticamente con los estados financieros y análisis mensual.</p>
            
            <div class="custom-module-actions">
              <div class="master-only">
                <button type="button" class="btn btn-outline-gold btn-sm" onclick="alert('Espacio habilitado para cargar datos de ${modName}.')">
                  <i class="fa-solid fa-file-arrow-up"></i>
                  <span>Cargar Archivo Plano (${modName})</span>
                </button>
              </div>
              <button type="button" class="btn btn-outline-dark btn-sm" onclick="alert('Módulo sincronizado correctamente con DC Asesorías.')">
                <i class="fa-solid fa-circle-check"></i>
                <span>Estado: Enlace Operativo Activo</span>
              </button>
            </div>
          </div>
        `;
        if (tabsContainer) {
          tabsContainer.appendChild(customContent);
        }
      });
    }

    // Actualizar badge de conteo en la barra de pestañas
    const countBadge = document.getElementById('active-modules-count-badge');
    if (countBadge) {
      countBadge.textContent = `${visibleCount} Módulos Activos`;
    }

    // Activar automáticamente la primera pestaña visible
    const visibleBtn = tabsNav.querySelector('.tab-btn:not([style*="display: none"])');
    if (visibleBtn) {
      activateTab(visibleBtn.getAttribute('data-tab'));
    }

    // Navegación por Barra Lateral de Opciones (Sidebar Ocultable)
    const sidebarToggleWrapper = document.getElementById('sidebar-toggle-wrapper');
    const unifiedWrapper = document.getElementById('unified-capsule-wrapper');
    const tabsNavWrapper = document.querySelector('.tabs-nav-wrapper');
    const tabsHeaderInfo = document.querySelector('.tabs-header-info');
    const periodRight = document.querySelector('.period-control-right');

    if (sidebarToggleWrapper) {
      sidebarToggleWrapper.style.display = 'inline-flex';
    }
    if (unifiedWrapper) {
      unifiedWrapper.style.display = 'none';
    }
    initSidebarNavigation(company);
    initMegaMenuNavigation(company);

    if (tabsNavWrapper) {
      tabsNavWrapper.style.display = 'none';
    }
    if (tabsHeaderInfo) {
      tabsHeaderInfo.style.display = 'none';
    }
    if (periodRight) {
      periodRight.style.display = 'none';
    }
  }

  

