  // =========================================================================
  // TORRE DE CONTROL MULTI-EMPRESA (CONSOLIDADOR EJECUTIVO EN TIEMPO REAL)
  // =========================================================================

  function getCompanyPeriodData(comp, periodSelection) {
    if (!comp) return { data: getDefaultBusinessData(), periodKey: getCurrentSystemPeriod() };
    ensureCompanyPeriods(comp);

    if (periodSelection && periodSelection !== 'latest') {
      const data = (comp.periods && comp.periods[periodSelection]) ? comp.periods[periodSelection] : getDefaultBusinessData();
      return { data, periodKey: periodSelection };
    }

    // Si periodSelection es 'latest':
    if (comp.selectedPeriod && comp.periods && comp.periods[comp.selectedPeriod] && !checkIsPeriodEmpty(comp.periods[comp.selectedPeriod])) {
      return { data: comp.periods[comp.selectedPeriod], periodKey: comp.selectedPeriod };
    }
    if (comp.periods) {
      const sortedKeys = Object.keys(comp.periods).sort().reverse();
      for (const pk of sortedKeys) {
        if (!checkIsPeriodEmpty(comp.periods[pk])) {
          return { data: comp.periods[pk], periodKey: pk };
        }
      }
    }
    const fallbackKey = comp.selectedPeriod || getCurrentSystemPeriod();
    const fallbackData = (comp.periods && comp.periods[fallbackKey]) ? comp.periods[fallbackKey] : (comp.businessData || getDefaultBusinessData());
    return { data: fallbackData, periodKey: fallbackKey };
  }

  function calculateFinancialMetrics(bd, comp) {
    if (!bd || typeof bd !== 'object') bd = {};

    // 1. Ingresos operacionales (Ventas)
    const sales = bd.sales || [];
    let totSales = 0;
    if (sales.length > 0) {
      sales.forEach(s => {
        totSales += Number(s.total_vta !== undefined ? s.total_vta : (s.vta_neta !== undefined ? s.vta_neta : (s.total || 0))) || 0;
      });
    } else {
      const monthlyProd = bd.monthlyProducts || [];
      if (monthlyProd.length > 0) {
        monthlyProd.forEach(p => {
          totSales += Number(p.venta_total !== undefined ? p.venta_total : (p.total !== undefined ? p.total : ((p.cant || 0) * (p.precio || 0)))) || 0;
        });
      } else {
        const payMethods = bd.paymentMethods || [];
        if (payMethods.length > 0) {
          payMethods.forEach(pm => {
            totSales += Number(pm.monto !== undefined ? pm.monto : (pm.total || 0)) || 0;
          });
        }
      }
    }

    // 2. Costos de ventas o Compras (COGS)
    const cogs = bd.cogs || [];
    let totCogs = 0;
    if (cogs.length > 0) {
      cogs.forEach(c => {
        totCogs += Number(c.venta_costo !== undefined ? c.venta_costo : ((c.costo || 0) * (c.cant || 0))) || 0;
      });
    } else {
      const suppliers = bd.suppliers || [];
      const purchaseCosts = bd.purchaseCosts || [];
      const purchases = (suppliers.length > 0) ? suppliers : purchaseCosts;
      if (purchases.length > 0) {
        purchases.forEach(p => {
          totCogs += Number(p.total !== undefined ? p.total : (p.total_compra !== undefined ? p.total_compra : (p.amount || 0))) || 0;
        });
      } else {
        const supplies = bd.supplies || [];
        if (supplies.length > 0) {
          supplies.forEach(s => {
            totCogs += Number(s.total !== undefined ? s.total : ((s.cant || 0) * (s.precio || 0))) || 0;
          });
        }
      }
    }
    const cogsPct = totSales > 0 ? (totCogs / totSales) * 100 : 0;

    // 3. Mermas y desperdicios
    const rawWaste = bd.waste || [];
    let totWaste = 0;
    rawWaste.forEach(r => {
      const cant = Number(r.cantidad) || 0;
      const cost = Number(r.costo !== undefined ? r.costo : (r.costo_unit !== undefined ? r.costo_unit : 0)) || 0;
      totWaste += Number(r.costo_total !== undefined ? r.costo_total : (cant * cost)) || 0;
    });

    // 4. Utilidad Bruta
    const directCosts = totCogs + totWaste;
    const grossProfit = totSales - directCosts;
    const grossMargin = totSales > 0 ? (grossProfit / totSales) * 100 : 0;

    // 5. Nómina
    const payroll = bd.payroll || [];
    let totPayroll = 0;
    payroll.forEach(p => {
      totPayroll += Number(p.total !== undefined ? p.total : (p.net !== undefined ? p.net : (p.amount || 0))) || 0;
    });
    const payrollPct = totSales > 0 ? (totPayroll / totSales) * 100 : 0;

    // 6. Almuerzo de Personal
    const rawLunch = bd.staffLunch || [];
    let totLunch = 0;
    rawLunch.forEach(r => {
      const cant = Number(r.cantidad) || 0;
      const cost = Number(r.costo !== undefined ? r.costo : (r.costo_unit !== undefined ? r.costo_unit : 0)) || 0;
      totLunch += Number(r.costo_total !== undefined ? r.costo_total : (cant * cost)) || 0;
    });

    // 7. Gastos Operativos (Expenses)
    const expenses = bd.expenses || [];
    let totExpenses = 0;
    expenses.forEach(e => {
      totExpenses += Number(e.total !== undefined ? e.total : (e.amount || 0)) || 0;
    });
    const expensesPct = totSales > 0 ? (totExpenses / totSales) * 100 : 0;

    // 8. OPEX Total (Nómina + Almuerzo + Gastos)
    const totOpex = totPayroll + totLunch + totExpenses;
    const opexPct = totSales > 0 ? (totOpex / totSales) * 100 : 0;

    // 9. Utilidad Neta y Margen Neto
    const netIncome = grossProfit - totOpex;
    const netMargin = totSales > 0 ? (netIncome / totSales) * 100 : 0;

    // 10. Punto de Equilibrio Operativo
    let breakEvenSales = 0;
    if (totOpex > 0 && grossMargin > 0) {
      breakEvenSales = Math.round(totOpex / (grossMargin / 100));
    }

    // 11. Diagnóstico de Salud
    const hasAnyData = totSales > 0 || totCogs > 0 || totOpex > 0;
    let healthCode = 'empty';
    let healthLabel = 'Sin Datos';
    let healthBadgeClass = 'neutral';

    if (!hasAnyData) {
      healthCode = 'empty';
      healthLabel = 'Sin Datos';
      healthBadgeClass = 'neutral';
    } else if (totSales > 0 && totCogs === 0 && totOpex === 0) {
      healthCode = 'pending';
      healthLabel = 'Solo Ventas';
      healthBadgeClass = 'caution';
    } else if (netIncome < 0) {
      healthCode = 'critical';
      healthLabel = 'En Pérdida';
      healthBadgeClass = 'critical';
    } else if (cogsPct > 42) {
      healthCode = 'warning';
      healthLabel = 'Costo Alto';
      healthBadgeClass = 'warning';
    } else if (netMargin < 15) {
      healthCode = 'caution';
      healthLabel = 'Margen Ajustado';
      healthBadgeClass = 'caution';
    } else {
      healthCode = 'healthy';
      healthLabel = 'Saludable';
      healthBadgeClass = 'healthy';
    }

    return {
      totSales,
      totCogs,
      cogsPct,
      totWaste,
      grossProfit,
      grossMargin,
      totPayroll,
      payrollPct,
      totLunch,
      totExpenses,
      expensesPct,
      totOpex,
      opexPct,
      netIncome,
      netMargin,
      breakEvenSales,
      healthCode,
      healthLabel,
      healthBadgeClass,
      hasAnyData
    };
  }

  function updateTowerPeriodOptions() {
    const sel = document.getElementById('select-tower-period');
    if (!sel) return;
    const companies = getCompanies();
    const periodSet = new Set();
    periodSet.add(getCurrentSystemPeriod());

    companies.forEach(c => {
      if (c.periods && typeof c.periods === 'object') {
        Object.keys(c.periods).forEach(k => periodSet.add(k));
      }
      if (c.selectedPeriod) periodSet.add(c.selectedPeriod);
    });

    const sorted = Array.from(periodSet).filter(p => /^\d{4}-\d{2}$/.test(p)).sort().reverse();
    const currentVal = towerSelectedPeriod || 'latest';

    let html = `<option value="latest" ${currentVal === 'latest' ? 'selected' : ''}>📌 Último Período con Datos de Cada Empresa</option>`;
    sorted.forEach(pk => {
      const isCurrent = pk === getCurrentSystemPeriod();
      const label = `${getPeriodLabel(pk)}${isCurrent ? ' [Mes Actual]' : ''}`;
      html += `<option value="${pk}" ${currentVal === pk ? 'selected' : ''}>${label}</option>`;
    });

    sel.innerHTML = html;
  }

  function renderControlTower() {
    updateTowerPeriodOptions();

    const companies = getCompanies();
    const query = (towerSearchQuery || '').trim().toLowerCase();

    // Filtrar empresas
    const filteredCompanies = companies.filter(c => {
      const st = c.status || 'activa';
      if (towerStatusFilter !== 'all' && st !== towerStatusFilter) return false;
      if (!query) return true;
      const name = (c.companyName || '').toLowerCase();
      const nit = (c.nit || '').toLowerCase();
      const email = (c.email || '').toLowerCase();
      return name.includes(query) || nit.includes(query) || email.includes(query);
    });

    // Acumuladores del Portafolio
    let portfolioSales = 0;
    let portfolioCogs = 0;
    let portfolioPayroll = 0;
    let portfolioExpenses = 0;
    let portfolioOpex = 0;
    let portfolioNet = 0;
    let portfolioBreakEven = 0;

    let companiesWithData = 0;
    let countHealthy = 0;
    let countCaution = 0;
    let countWarning = 0;
    let countCritical = 0;
    let countEmpty = 0;

    const rowsData = [];

    filteredCompanies.forEach(c => {
      const periodInfo = getCompanyPeriodData(c, towerSelectedPeriod);
      const metrics = calculateFinancialMetrics(periodInfo.data, c);

      if (metrics.hasAnyData) {
        companiesWithData++;
        portfolioSales += metrics.totSales;
        portfolioCogs += metrics.totCogs;
        portfolioPayroll += metrics.totPayroll;
        portfolioExpenses += metrics.totExpenses;
        portfolioOpex += metrics.totOpex;
        portfolioNet += metrics.netIncome;
        portfolioBreakEven += metrics.breakEvenSales;
      }

      switch (metrics.healthCode) {
        case 'healthy': countHealthy++; break;
        case 'caution': countCaution++; break;
        case 'warning': countWarning++; break;
        case 'critical': countCritical++; break;
        default: countEmpty++; break;
      }

      rowsData.push({
        company: c,
        periodKey: periodInfo.periodKey,
        periodLabel: getPeriodLabel(periodInfo.periodKey),
        metrics
      });
    });

    // Cálculos consolidados ponderados
    const portfolioCogsPct = portfolioSales > 0 ? (portfolioCogs / portfolioSales) * 100 : 0;
    const portfolioOpexPct = portfolioSales > 0 ? (portfolioOpex / portfolioSales) * 100 : 0;
    const portfolioNetMargin = portfolioSales > 0 ? (portfolioNet / portfolioSales) * 100 : 0;

    // Actualizar Tarjetas KPI Globales
    const elKpiCompanies = document.getElementById('tower-kpi-companies');
    const elKpiCompaniesSub = document.getElementById('tower-kpi-companies-sub');
    const elKpiSales = document.getElementById('tower-kpi-sales');
    const elKpiSalesSub = document.getElementById('tower-kpi-sales-sub');
    const elKpiCogs = document.getElementById('tower-kpi-cogs');
    const elKpiCogsSub = document.getElementById('tower-kpi-cogs-sub');
    const elKpiOpex = document.getElementById('tower-kpi-opex');
    const elKpiOpexSub = document.getElementById('tower-kpi-opex-sub');
    const elKpiNet = document.getElementById('tower-kpi-net');
    const elKpiNetMargin = document.getElementById('tower-kpi-net-margin');

    if (elKpiCompanies) elKpiCompanies.textContent = `${filteredCompanies.length}`;
    if (elKpiCompaniesSub) elKpiCompaniesSub.textContent = `${companiesWithData} con datos cargados`;

    if (elKpiSales) elKpiSales.textContent = formatMoney(portfolioSales);
    if (elKpiSalesSub) elKpiSalesSub.textContent = `Ingresos operacionales`;

    if (elKpiCogs) elKpiCogs.textContent = `${portfolioCogsPct.toFixed(1)}%`;
    if (elKpiCogsSub) elKpiCogsSub.textContent = `${formatMoney(portfolioCogs)} en compras/receta`;

    if (elKpiOpex) elKpiOpex.textContent = `${portfolioOpexPct.toFixed(1)}%`;
    if (elKpiOpexSub) elKpiOpexSub.textContent = `${formatMoney(portfolioOpex)} costo operativo`;

    if (elKpiNet) {
      elKpiNet.textContent = formatMoney(portfolioNet);
      elKpiNet.style.color = portfolioNet >= 0 ? '#059669' : '#dc2626';
    }
    if (elKpiNetMargin) {
      elKpiNetMargin.textContent = `Margen Neto: ${portfolioNetMargin.toFixed(1)}%`;
      elKpiNetMargin.style.color = portfolioNetMargin >= 0 ? '#059669' : '#dc2626';
    }

    // Actualizar Semáforo de Salud
    const elChipHealthy = document.getElementById('chip-count-healthy');
    const elChipCaution = document.getElementById('chip-count-caution');
    const elChipWarning = document.getElementById('chip-count-warning');
    const elChipCritical = document.getElementById('chip-count-critical');
    const elChipEmpty = document.getElementById('chip-count-empty');

    if (elChipHealthy) elChipHealthy.textContent = countHealthy;
    if (elChipCaution) elChipCaution.textContent = countCaution;
    if (elChipWarning) elChipWarning.textContent = countWarning;
    if (elChipCritical) elChipCritical.textContent = countCritical;
    if (elChipEmpty) elChipEmpty.textContent = countEmpty;

    // Renderizar Tabla
    const tbody = document.getElementById('tower-table-body');
    const tfoot = document.getElementById('tower-table-footer');
    if (!tbody || !tfoot) return;

    if (rowsData.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="11" style="text-align: center; padding: 42px 20px; color: #64748b;">
            <i class="fa-solid fa-store" style="font-size: 2.2rem; color: #cbd5e1; margin-bottom: 10px; display: block;"></i>
            <strong>No se encontraron empresas con los filtros aplicados.</strong>
          </td>
        </tr>
      `;
      tfoot.innerHTML = '';
      return;
    }

    let tbodyHtml = '';
    rowsData.forEach(row => {
      const c = row.company;
      const m = row.metrics;
      const isTerminated = (c.status || 'activa') === 'terminada';

      const cogsPillClass = m.cogsPct > 42 ? 'pill-bad' : (m.cogsPct > 35 ? 'pill-warn' : 'pill-good');
      const payrollPillClass = m.payrollPct > 32 ? 'pill-bad' : (m.payrollPct > 25 ? 'pill-warn' : 'pill-good');
      const marginPillClass = m.netMargin < 0 ? 'pill-bad' : (m.netMargin < 15 ? 'pill-warn' : 'pill-good');
      const netColor = m.netIncome >= 0 ? '#059669' : '#dc2626';

      tbodyHtml += `
        <tr>
          <td>
            <div class="table-company-cell">
              <span class="table-company-name">${c.companyName}</span>
              <span class="table-company-sub">
                <span>NIT: ${c.nit || '—'}</span>
                <span>•</span>
                <span style="color: ${isTerminated ? '#d97706' : '#10b981'}; font-weight: 600;">
                  ${isTerminated ? 'Contrato Terminado' : 'Activa'}
                </span>
              </span>
            </div>
          </td>
          <td>
            <span style="font-size: 11.5px; font-weight: 600; color: #475569; background: #f1f5f9; padding: 3px 8px; border-radius: 6px; white-space: nowrap;">
              ${row.periodLabel}
            </span>
          </td>
          <td class="text-right" style="font-weight: 700; color: #0f172a;">${formatMoney(m.totSales)}</td>
          <td class="text-right">
            <div>${formatMoney(m.totCogs)}</div>
            <span class="metric-pill ${cogsPillClass}" style="margin-top: 2px;">${m.cogsPct.toFixed(1)}%</span>
          </td>
          <td class="text-right">
            <div>${formatMoney(m.totPayroll)}</div>
            <span class="metric-pill ${payrollPillClass}" style="margin-top: 2px;">${m.payrollPct.toFixed(1)}%</span>
          </td>
          <td class="text-right">
            <div>${formatMoney(m.totExpenses)}</div>
            <span style="font-size: 11px; color: #64748b;">${m.expensesPct.toFixed(1)}%</span>
          </td>
          <td class="text-right" style="font-weight: 800; color: ${netColor};">
            ${formatMoney(m.netIncome)}
          </td>
          <td class="text-center">
            <span class="metric-pill ${marginPillClass}">${m.netMargin.toFixed(1)}%</span>
          </td>
          <td class="text-right" style="font-size: 12px; color: #475569;">
            ${formatMoney(m.breakEvenSales)}
          </td>
          <td class="text-center">
            <span class="badge-health-pill ${m.healthBadgeClass}">
              ${m.healthLabel}
            </span>
          </td>
          <td class="text-center">
            <button type="button" class="btn-tower-enter" data-company-id="${c.id}" title="Abrir y gestionar ${c.companyName}">
              <i class="fa-solid fa-arrow-right-to-bracket"></i>
              <span>Entrar</span>
            </button>
          </td>
        </tr>
      `;
    });

    tbody.innerHTML = tbodyHtml;

    // Fila del pie con totales consolidados
    tfoot.innerHTML = `
      <tr>
        <td style="font-weight: 800; color: #0f4c5c;">
          <i class="fa-solid fa-chart-column text-gold"></i> TOTALES CONSOLIDADOS (${filteredCompanies.length} Emp.)
        </td>
        <td style="font-size: 11px; color: #64748b; font-weight: 700;">PORTAFOLIO</td>
        <td class="text-right" style="font-size: 13.5px; font-weight: 800; color: #0f172a;">${formatMoney(portfolioSales)}</td>
        <td class="text-right">
          <div>${formatMoney(portfolioCogs)}</div>
          <span class="metric-pill ${portfolioCogsPct > 42 ? 'pill-bad' : 'pill-good'}" style="margin-top: 2px;">${portfolioCogsPct.toFixed(1)}% Pond.</span>
        </td>
        <td class="text-right">
          <div>${formatMoney(portfolioPayroll)}</div>
          <span class="metric-pill ${portfolioOpexPct > 35 ? 'pill-warn' : 'pill-good'}" style="margin-top: 2px;">${portfolioSales > 0 ? ((portfolioPayroll/portfolioSales)*100).toFixed(1) : '0.0'}% Pond.</span>
        </td>
        <td class="text-right">
          <div>${formatMoney(portfolioExpenses)}</div>
          <span style="font-size: 11px; color: #64748b;">${portfolioSales > 0 ? ((portfolioExpenses/portfolioSales)*100).toFixed(1) : '0.0'}% Pond.</span>
        </td>
        <td class="text-right" style="font-size: 13.5px; font-weight: 900; color: ${portfolioNet >= 0 ? '#059669' : '#dc2626'};">
          ${formatMoney(portfolioNet)}
        </td>
        <td class="text-center">
          <span class="metric-pill ${portfolioNetMargin < 0 ? 'pill-bad' : (portfolioNetMargin < 15 ? 'pill-warn' : 'pill-good')}">${portfolioNetMargin.toFixed(1)}% Pond.</span>
        </td>
        <td class="text-right" style="font-weight: 700; color: #334155;">
          ${formatMoney(portfolioBreakEven)}
        </td>
        <td class="text-center">
          <span class="badge-health-pill ${portfolioNetMargin >= 15 ? 'healthy' : (portfolioNetMargin >= 0 ? 'caution' : 'critical')}">
            ${portfolioNetMargin >= 15 ? 'Rentable' : (portfolioNetMargin >= 0 ? 'Estable' : 'Alerta Global')}
          </span>
        </td>
        <td></td>
      </tr>
    `;

    // Vincular botones Entrar desde la tabla
    tbody.querySelectorAll('.btn-tower-enter').forEach(btn => {
      btn.addEventListener('click', () => {
        const companyId = btn.getAttribute('data-company-id');
        enterCompanyAsMaster(companyId);
      });
    });
  }

  function exportControlTowerToExcel() {
    try {
      if (typeof XLSX === 'undefined') {
        showToast('La biblioteca de exportación de Excel no está disponible.', 'error');
        return;
      }

      const companies = getCompanies();
      const query = (towerSearchQuery || '').trim().toLowerCase();
      const filtered = companies.filter(c => {
        const st = c.status || 'activa';
        if (towerStatusFilter !== 'all' && st !== towerStatusFilter) return false;
        if (!query) return true;
        const name = (c.companyName || '').toLowerCase();
        const nit = (c.nit || '').toLowerCase();
        const email = (c.email || '').toLowerCase();
        return name.includes(query) || nit.includes(query) || email.includes(query);
      });

      const periodTitle = towerSelectedPeriod === 'latest' ? 'Último Período con Datos' : getPeriodLabel(towerSelectedPeriod);
      const todayStr = new Date().toLocaleDateString('es-CO');

      const rows = [
        ['DC RESTODATA - TORRE DE CONTROL MULTI-EMPRESA', '', '', '', '', '', '', '', '', '', '', '', '', ''],
        ['ADMINISTRADOR MASTER: dcasesorias@gmail.com', '', '', '', '', '', '', '', '', '', '', '', '', ''],
        [`Período Analizado: ${periodTitle}`, `Fecha de Generación: ${todayStr}`, '', '', '', '', '', '', '', '', '', '', '', ''],
        [''],
        [
          'Empresa / Restaurante',
          'NIT',
          'Estado Contrato',
          'Período Evaluado',
          'Ventas Totales ($)',
          'Costo Receta COGS ($)',
          'COGS %',
          'Nómina ($)',
          'Nómina %',
          'Gastos Operativos ($)',
          'Utilidad Neta ($)',
          'Margen Neto %',
          'Punto de Equilibrio ($)',
          'Diagnóstico Salud Financiera'
        ]
      ];

      let totSales = 0;
      let totCogs = 0;
      let totPayroll = 0;
      let totExpenses = 0;
      let totNet = 0;
      let totBreakEven = 0;

      filtered.forEach(c => {
        const pInfo = getCompanyPeriodData(c, towerSelectedPeriod);
        const m = calculateFinancialMetrics(pInfo.data, c);

        totSales += m.totSales;
        totCogs += m.totCogs;
        totPayroll += m.totPayroll;
        totExpenses += m.totExpenses;
        totNet += m.netIncome;
        totBreakEven += m.breakEvenSales;

        rows.push([
          c.companyName,
          c.nit || '—',
          (c.status || 'activa') === 'terminada' ? 'Contrato Terminado' : 'Activa',
          pInfo.periodKey,
          m.totSales,
          m.totCogs,
          Number(m.cogsPct.toFixed(2)),
          m.totPayroll,
          Number(m.payrollPct.toFixed(2)),
          m.totExpenses,
          m.netIncome,
          Number(m.netMargin.toFixed(2)),
          m.breakEvenSales,
          m.healthLabel
        ]);
      });

      // Fila de totales
      const pondCogsPct = totSales > 0 ? (totCogs / totSales) * 100 : 0;
      const pondPayrollPct = totSales > 0 ? (totPayroll / totSales) * 100 : 0;
      const pondNetMargin = totSales > 0 ? (totNet / totSales) * 100 : 0;

      rows.push(['']);
      rows.push([
        'TOTALES CONSOLIDADOS DEL PORTAFOLIO',
        `${filtered.length} Empresas`,
        'CONSOLIDADO',
        periodTitle,
        totSales,
        totCogs,
        Number(pondCogsPct.toFixed(2)),
        totPayroll,
        Number(pondPayrollPct.toFixed(2)),
        totExpenses,
        totNet,
        Number(pondNetMargin.toFixed(2)),
        totBreakEven,
        pondNetMargin >= 15 ? 'Portafolio Rentable' : (pondNetMargin >= 0 ? 'Portafolio Estable' : 'Alerta Global')
      ]);

      const wb = XLSX.utils.book_new();
      const ws = XLSX.utils.aoa_to_sheet(rows);

      ws['!cols'] = [
        { wch: 30 },
        { wch: 16 },
        { wch: 20 },
        { wch: 16 },
        { wch: 20 },
        { wch: 22 },
        { wch: 12 },
        { wch: 18 },
        { wch: 12 },
        { wch: 22 },
        { wch: 20 },
        { wch: 14 },
        { wch: 24 },
        { wch: 28 }
      ];

      XLSX.utils.book_append_sheet(wb, ws, 'Torre_de_Control');

      const dateClean = new Date().toISOString().slice(0, 10).replace(/-/g, '');
      XLSX.writeFile(wb, `DC_Restaurantes_Torre_Control_${dateClean}.xlsx`);
      showToast('Consolidado multi-empresa exportado exitosamente a Excel.', 'success');
    } catch (err) {
      console.error('Error exportando consolidado a Excel:', err);
      showToast('No se pudo exportar el archivo de Excel.', 'error');
    }
  }

  // =========================================================================
  // FICHA TÉCNICA DE EMPRESA (MODAL VER EMPRESA)
  // =========================================================================
  const modalViewCompany = document.getElementById('modal-view-company');
  const btnCloseViewCompany = document.getElementById('btn-close-view-company');
  const btnCloseViewCompanyFooter = document.getElementById('btn-close-view-company-footer');
  const btnViewToEditCompany = document.getElementById('btn-view-to-edit-company');
  const btnViewToEnterCompany = document.getElementById('btn-view-to-enter-company');
  let companyBeingViewed = null;

  function closeViewCompanyModal() {
    if (modalViewCompany) modalViewCompany.classList.add('hidden');
    companyBeingViewed = null;
  }

  function openViewCompanyModal(company) {
    if (!company) return;
    companyBeingViewed = company;
    const body = document.getElementById('view-company-modal-body');
    if (!body) return;

    const isMasterCompany = (company.email || "").toLowerCase() === MASTER_EMAIL.toLowerCase();
    const isTerminated = (company.status || 'activa') === 'terminada';
    const taxRegime = company.taxRegime || 'impoconsumo_8';
    let taxLabel = 'Impoconsumo 8% (Incluido)';
    if (taxRegime === 'no_responsable_0') taxLabel = 'No Responsable (0% Impo)';
    else if (taxRegime === 'impoconsumo_8_net') taxLabel = 'Precios Base + 8% Impo';
    else if (taxRegime === 'iva_19') taxLabel = 'Responsable de IVA (19%)';

    const sPlanKey = company.servicePlan || 'plan_estandar';
    const planConfig = (typeof SERVICE_PLANS_CONFIG !== 'undefined' && SERVICE_PLANS_CONFIG[sPlanKey]) ? SERVICE_PLANS_CONFIG[sPlanKey] : { name: 'Plan Estándar', icon: 'fa-layer-group', color: '#0284c7', bg: '#f0f9ff', border: '#bae6fd', description: '' };

    const enabledModules = Array.isArray(company.enabledModules) ? company.enabledModules : (typeof ALL_SYSTEM_MODULES !== 'undefined' ? ALL_SYSTEM_MODULES : []);
    
    // Generar chips de módulos habilitados
    let modulesHtml = '';
    const metadataList = (typeof SYSTEM_MODULES_METADATA !== 'undefined' && Array.isArray(SYSTEM_MODULES_METADATA)) ? SYSTEM_MODULES_METADATA : [];
    if (metadataList.length > 0) {
      modulesHtml = metadataList.map(mod => {
        const isAct = enabledModules.includes(mod.id);
        if (!isAct) return '';
        const isCul = mod.tag === 'Culinario' || mod.id === 'tab-recetario' || mod.id === 'tab-cotizador' || mod.id === 'tab-menu-engineering';
        const isNom = mod.id === 'tab-8-nomina';
        return `
          <span style="display:inline-flex; align-items:center; gap:6px; font-size:11.5px; font-weight:600; padding:4px 9px; background:${isCul ? '#f0fdf4' : (isNom ? '#fffbeb' : '#eff6ff')}; color:${isCul ? '#15803d' : (isNom ? '#b45309' : '#1e40af')}; border:1px solid ${isCul ? '#bbf7d0' : (isNom ? '#fde68a' : '#bfdbfe')}; border-radius:6px;">
            <i class="fa-solid ${mod.icon}" style="color:${isCul ? '#16a34a' : (isNom ? '#d97706' : '#3b82f6')};"></i> ${mod.name}
          </span>
        `;
      }).filter(Boolean).join('');
    }

    body.innerHTML = `
      <div style="background: linear-gradient(135deg, #0b192c 0%, #1e3a8a 100%); color: white; padding: 18px 20px; border-radius: 12px; margin-bottom: 20px; display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap;">
        <div style="display: flex; align-items: center; gap: 14px;">
          <div style="width: 50px; height: 50px; border-radius: 12px; background: rgba(255,255,255,0.15); display: flex; align-items: center; justify-content: center; font-size: 1.5rem; color: #fbbf24; border: 1px solid rgba(255,255,255,0.2);">
            <i class="fa-solid ${isMasterCompany ? 'fa-crown' : 'fa-building'}"></i>
          </div>
          <div>
            <h3 style="margin: 0; font-size: 1.25rem; font-weight: 700; color: #ffffff;">${company.companyName}</h3>
            <p style="margin: 2px 0 0 0; font-size: 0.85rem; color: #cbd5e1;">NIT: <strong>${company.nit || 'Sin registrar'}</strong></p>
          </div>
        </div>
        <div style="display: flex; gap: 6px; flex-wrap: wrap;">
          <span style="font-size: 11px; font-weight: 700; padding: 4px 10px; border-radius: 20px; background: ${isTerminated ? '#fef2f2' : '#ecfdf5'}; color: ${isTerminated ? '#991b1b' : '#065f46'}; border: 1px solid ${isTerminated ? '#fca5a5' : '#a7f3d0'};">
            <i class="fa-solid ${isTerminated ? 'fa-clock-rotate-left' : 'fa-circle-check'}"></i> ${isTerminated ? 'Contrato Terminado' : 'Empresa Activa'}
          </span>
          <span style="font-size: 11px; font-weight: 700; padding: 4px 10px; border-radius: 20px; background: #f0f9ff; color: #0369a1; border: 1px solid #bae6fd;">
            <i class="fa-solid ${planConfig.icon || 'fa-layer-group'}"></i> ${planConfig.name}
          </span>
        </div>
      </div>

      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 20px;">
        <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px;">
          <div style="font-size: 0.75rem; text-transform: uppercase; font-weight: 700; color: #64748b; margin-bottom: 4px;">Correo de Acceso</div>
          <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;">
            <strong style="font-size: 0.92rem; color: #0f172a; word-break: break-all;">${company.email}</strong>
            <button type="button" class="btn-copy-view-creds" data-text="${company.email}" title="Copiar correo" style="background: none; border: none; color: #0284c7; cursor: pointer; padding: 2px;">
              <i class="fa-regular fa-copy"></i>
            </button>
          </div>
        </div>

        <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px;">
          <div style="font-size: 0.75rem; text-transform: uppercase; font-weight: 700; color: #64748b; margin-bottom: 4px;">Contraseña de Acceso</div>
          <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;">
            <strong style="font-size: 0.92rem; font-family: monospace; background: #fef3c7; color: #92400e; padding: 1px 8px; border-radius: 4px; border: 1px solid #fde68a;">${company.password || '123456'}</strong>
            <button type="button" class="btn-copy-view-creds" data-text="${company.password || '123456'}" title="Copiar clave" style="background: none; border: none; color: #d97706; cursor: pointer; padding: 2px;">
              <i class="fa-regular fa-copy"></i>
            </button>
          </div>
        </div>

        <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px;">
          <div style="font-size: 0.75rem; text-transform: uppercase; font-weight: 700; color: #64748b; margin-bottom: 4px;">Régimen Tributario</div>
          <strong style="font-size: 0.88rem; color: #0f172a;"><i class="fa-solid fa-receipt" style="color:#0d9488; margin-right:4px;"></i>${taxLabel}</strong>
        </div>

        <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px;">
          <div style="font-size: 0.75rem; text-transform: uppercase; font-weight: 700; color: #64748b; margin-bottom: 4px;">Tarifa y Cobro</div>
          <strong style="font-size: 0.88rem; color: #0f172a;">${company.contractFee > 0 ? formatMoney(company.contractFee) : '$0'} · ${company.billingPeriod || 'mensual'} (Día ${company.billingDay || 1})</strong>
        </div>

        <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px;">
          <div style="font-size: 0.75rem; text-transform: uppercase; font-weight: 700; color: #64748b; margin-bottom: 4px;">Teléfono / WhatsApp</div>
          <strong style="font-size: 0.88rem; color: #0f172a;"><i class="fa-solid fa-phone" style="color:#10b981; margin-right:4px;"></i>${company.phone || 'No registrado'}</strong>
        </div>

        <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px;">
          <div style="font-size: 0.75rem; text-transform: uppercase; font-weight: 700; color: #64748b; margin-bottom: 4px;">Contacto Principal</div>
          <strong style="font-size: 0.88rem; color: #0f172a;"><i class="fa-solid fa-user-tie" style="color:#6366f1; margin-right:4px;"></i>${company.contactName || 'No registrado'}</strong>
        </div>

        <div style="grid-column: span 2; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px;">
          <div style="font-size: 0.75rem; text-transform: uppercase; font-weight: 700; color: #64748b; margin-bottom: 4px;">Dirección Física</div>
          <strong style="font-size: 0.88rem; color: #0f172a;"><i class="fa-solid fa-location-dot" style="color:#ef4444; margin-right:4px;"></i>${company.address || 'No registrada'}</strong>
        </div>

        <div style="grid-column: span 2; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px;">
          <div style="font-size: 0.75rem; text-transform: uppercase; font-weight: 700; color: #64748b; margin-bottom: 4px;">ID de Empresa en Firebase</div>
          <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;">
            <code style="font-family: monospace; font-size: 0.88rem; background: #e0e7ff; color: #3730a3; padding: 3px 8px; border-radius: 6px;">${company.id}</code>
            <button type="button" class="btn-copy-view-creds" data-text="${company.id}" title="Copiar ID Firebase" style="background: none; border: none; color: #4f46e5; cursor: pointer; padding: 2px;">
              <i class="fa-regular fa-copy"></i> Copiar ID
            </button>
          </div>
        </div>

        ${company.contractNotes ? `
          <div style="grid-column: span 2; background: #fffbeb; border: 1px solid #fde68a; border-radius: 10px; padding: 12px;">
            <div style="font-size: 0.75rem; text-transform: uppercase; font-weight: 700; color: #b45309; margin-bottom: 4px;">Notas y Observaciones de Contrato</div>
            <p style="margin: 0; font-size: 0.85rem; color: #78350f; white-space: pre-wrap;">${company.contractNotes}</p>
          </div>
        ` : ''}
      </div>

      <div>
        <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px;">
          <strong style="font-size: 0.9rem; color: #0f172a;"><i class="fa-solid fa-cubes text-gold" style="margin-right: 6px;"></i>Módulos Habilitados (${enabledModules.length})</strong>
          <span style="font-size: 0.8rem; color: #64748b;">Disponibles para este cliente</span>
        </div>
        <div style="display: flex; flex-wrap: wrap; gap: 6px;">
          ${modulesHtml || '<span style="color:#94a3b8; font-size:0.85rem;">Todos los módulos habilitados</span>'}
        </div>
      </div>
    `;

    // Vincular botones de copia dentro del modal
    body.querySelectorAll('.btn-copy-view-creds').forEach(btn => {
      btn.addEventListener('click', () => {
        const txt = btn.getAttribute('data-text');
        copyToClipboardText(txt, '¡Copiado al portapapeles!');
      });
    });

    if (modalViewCompany) modalViewCompany.classList.remove('hidden');
  }

  if (btnCloseViewCompany) btnCloseViewCompany.addEventListener('click', closeViewCompanyModal);
  if (btnCloseViewCompanyFooter) btnCloseViewCompanyFooter.addEventListener('click', closeViewCompanyModal);
  if (btnViewToEditCompany) {
    btnViewToEditCompany.addEventListener('click', () => {
      const comp = companyBeingViewed;
      closeViewCompanyModal();
      if (comp) openEditCompanyModal(comp);
    });
  }
  if (btnViewToEnterCompany) {
    btnViewToEnterCompany.addEventListener('click', () => {
      const comp = companyBeingViewed;
      closeViewCompanyModal();
      if (comp) enterCompanyAsMaster(comp.id);
    });
  }
  if (modalViewCompany) {
    modalViewCompany.addEventListener('click', (e) => {
      if (e.target === modalViewCompany) closeViewCompanyModal();
    });
  }
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modalViewCompany && !modalViewCompany.classList.contains('hidden')) {
      closeViewCompanyModal();
    }
  });

  // =========================================================================
  // GESTIÓN Y EDICIÓN DE EMPRESAS (MODAL EDITAR EMPRESA)
  // =========================================================================
  const modalEditCompany = document.getElementById('modal-edit-company');
  const btnCloseEditCompany = document.getElementById('btn-close-edit-company');
  const btnCancelEditCompany = document.getElementById('btn-cancel-edit-company');
  const btnSaveEditCompany = document.getElementById('btn-save-edit-company');

  function openEditCompanyModal(company) {
    if (!company) return;
    const idEl = document.getElementById('edit-company-id');
    const nameEl = document.getElementById('edit-company-name');
    const nitEl = document.getElementById('edit-company-nit');
    const emailEl = document.getElementById('edit-company-email');
    const phoneEl = document.getElementById('edit-company-phone');
    const contactEl = document.getElementById('edit-company-contact');
    const addressEl = document.getElementById('edit-company-address');
    const usertypeEl = document.getElementById('edit-company-usertype');
    const statusEl = document.getElementById('edit-company-status');
    const taxRegimeEl = document.getElementById('edit-company-tax-regime');
    const passEl = document.getElementById('edit-company-password');
    const passMasterEl = document.getElementById('edit-company-password-master');
    const passLiteEl = document.getElementById('edit-company-password-lite');

    if (idEl) idEl.value = company.id || '';
    if (nameEl) nameEl.value = company.companyName || '';
    if (nitEl) nitEl.value = company.nit || '';
    if (emailEl) emailEl.value = company.email || '';
    if (phoneEl) phoneEl.value = company.phone || '';
    if (contactEl) contactEl.value = company.contactName || '';
    if (addressEl) addressEl.value = company.address || '';
    if (usertypeEl) usertypeEl.value = company.userType || company.role || 'lite';
    if (statusEl) statusEl.value = company.status || 'activa';
    if (taxRegimeEl) taxRegimeEl.value = company.taxRegime || 'impoconsumo_8';

    const servicePlanEl = document.getElementById('edit-company-service-plan');
    const billingPeriodEl = document.getElementById('edit-company-billing-period');
    const contractFeeEl = document.getElementById('edit-company-contract-fee');
    const billingDayEl = document.getElementById('edit-company-billing-day');
    const contractNotesEl = document.getElementById('edit-company-contract-notes');
    const planFeeHint = document.getElementById('plan-fee-hint');

    let curPlan = company.servicePlan || ((company.id === 'comp_demo_pruebas_sandbox') ? 'plan_pro' : 'plan_estandar');
    if (curPlan === 'plan_culinario') curPlan = 'plan_pro';
    const curPeriod = company.billingPeriod || 'mensual';

    if (servicePlanEl) servicePlanEl.value = curPlan;
    if (billingPeriodEl) billingPeriodEl.value = curPeriod;
    if (contractFeeEl) contractFeeEl.value = (typeof company.contractFee !== 'undefined' && company.contractFee !== null && company.contractFee !== '') ? company.contractFee : calculateSuggestedFee(curPlan, curPeriod);
    if (billingDayEl) billingDayEl.value = company.billingDay || 1;
    if (contractNotesEl) contractNotesEl.value = company.contractNotes || '';

    function updatePlanHint() {
      let p = servicePlanEl ? servicePlanEl.value : 'plan_pro';
      if (p === 'plan_culinario') p = 'plan_pro';
      const b = billingPeriodEl ? billingPeriodEl.value : 'mensual';
      const fee = calculateSuggestedFee(p, b);
      if (planFeeHint) {
        if (p === 'plan_personalizado') {
          planFeeHint.textContent = 'Tarifa Personalizada';
        } else {
          const savings = b === 'trimestral' ? ' (5% desc)' : (b === 'semestral' ? ' (10% desc)' : (b === 'anual' ? ' (2 meses gratis)' : ''));
          planFeeHint.textContent = `Sugerido: ${formatMoney(fee)} [${b}]${savings}`;
        }
      }
    }

    if (servicePlanEl) {
      servicePlanEl.onchange = () => {
        const p = servicePlanEl.value;
        const b = billingPeriodEl ? billingPeriodEl.value : 'mensual';
        const fee = calculateSuggestedFee(p, b);
        if (contractFeeEl && p !== 'plan_personalizado') {
          contractFeeEl.value = fee;
        }
        updatePlanHint();
      };
    }

    if (billingPeriodEl) {
      billingPeriodEl.onchange = () => {
        const p = servicePlanEl ? servicePlanEl.value : 'plan_estandar';
        const b = billingPeriodEl.value;
        const fee = calculateSuggestedFee(p, b);
        if (contractFeeEl && p !== 'plan_personalizado') {
          contractFeeEl.value = fee;
        }
        updatePlanHint();
      };
    }

    updatePlanHint();
    if (passEl) passEl.value = company.password || '';
    if (passMasterEl) passMasterEl.value = company.passwordMaster || '';
    if (passLiteEl) passLiteEl.value = company.passwordLite || '';

    if (modalEditCompany) modalEditCompany.classList.remove('hidden');
  }

  function closeEditCompanyModal() {
    if (modalEditCompany) modalEditCompany.classList.add('hidden');
  }

  if (btnCloseEditCompany) btnCloseEditCompany.addEventListener('click', closeEditCompanyModal);
  if (btnCancelEditCompany) btnCancelEditCompany.addEventListener('click', closeEditCompanyModal);
  if (modalEditCompany) {
    modalEditCompany.addEventListener('click', (e) => {
      if (e.target === modalEditCompany) closeEditCompanyModal();
    });
  }
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modalEditCompany && !modalEditCompany.classList.contains('hidden')) {
      closeEditCompanyModal();
    }
  });

  if (btnSaveEditCompany) {
    btnSaveEditCompany.addEventListener('click', () => {
      const companyId = (document.getElementById('edit-company-id')?.value || '').trim();
      const companyName = (document.getElementById('edit-company-name')?.value || '').trim();
      const nit = (document.getElementById('edit-company-nit')?.value || '').trim();
      const email = (document.getElementById('edit-company-email')?.value || '').trim().toLowerCase();
      const phone = (document.getElementById('edit-company-phone')?.value || '').trim();
      const contactName = (document.getElementById('edit-company-contact')?.value || '').trim();
      const address = (document.getElementById('edit-company-address')?.value || '').trim();
      const userType = document.getElementById('edit-company-usertype')?.value || 'lite';
      const status = document.getElementById('edit-company-status')?.value || 'activa';
      const taxRegime = document.getElementById('edit-company-tax-regime')?.value || 'impoconsumo_8';
      const servicePlan = document.getElementById('edit-company-service-plan')?.value || 'plan_estandar';
      const billingPeriod = document.getElementById('edit-company-billing-period')?.value || 'mensual';
      const contractFee = Number(document.getElementById('edit-company-contract-fee')?.value) || 0;
      const billingDay = Number(document.getElementById('edit-company-billing-day')?.value) || 1;
      const contractNotes = (document.getElementById('edit-company-contract-notes')?.value || '').trim();
      const password = (document.getElementById('edit-company-password')?.value || '').trim();
      const passwordMaster = (document.getElementById('edit-company-password-master')?.value || '').trim();
      const passwordLite = (document.getElementById('edit-company-password-lite')?.value || '').trim();

      if (!companyName) {
        showToast('El nombre de la empresa es obligatorio.', 'error');
        return;
      }
      if (!email) {
        showToast('El correo electrónico de acceso es obligatorio.', 'error');
        return;
      }

      const companies = getCompanies();
      const comp = companies.find(c => c.id === companyId);
      if (!comp) {
        showToast('No se encontró la empresa a editar.', 'error');
        return;
      }

      // Validar si el correo cambió y ya existe en otra empresa
      const emailDuplicate = companies.some(c => c.id !== companyId && (c.email || "").toLowerCase() === email);
      if (emailDuplicate) {
        showToast(`Ya existe otra empresa registrada con el correo "${email}".`, 'error');
        return;
      }

      // Actualizar datos
      comp.companyName = companyName;
      comp.nit = nit;
      comp.email = email;
      comp.phone = phone;
      comp.contactName = contactName;
      comp.address = address;
      comp.userType = userType;
      comp.role = userType;
      comp.status = status;
      comp.taxRegime = taxRegime;
      comp.servicePlan = servicePlan;
      comp.billingPeriod = billingPeriod;
      comp.contractFee = contractFee;
      comp.billingDay = billingDay;
      comp.contractNotes = contractNotes;

      // Asignar los módulos oficiales del plan seleccionado (Básico, Estándar o Pro)
      if (servicePlan !== 'plan_personalizado' && SERVICE_PLANS_CONFIG[servicePlan]) {
        comp.enabledModules = [...SERVICE_PLANS_CONFIG[servicePlan].modules];
      }
      if (password) comp.password = password;
      comp.passwordMaster = passwordMaster;
      comp.passwordLite = passwordLite;
      comp._updatedAt = Date.now();

      saveCompanies(companies);
      syncCompaniesToCloud(companies);

      if (currentCompany && currentCompany.id === comp.id) {
        currentCompany.companyName = companyName;
        currentCompany.nit = nit;
        currentCompany.email = email;
        currentCompany.phone = phone;
        currentCompany.contactName = contactName;
        currentCompany.address = address;
        currentCompany.userType = userType;
        currentCompany.role = userType;
        currentCompany.status = status;
        currentCompany.taxRegime = taxRegime;
        currentCompany.servicePlan = servicePlan;
        if (servicePlan === 'plan_premium' && typeof SERVICE_PLANS_CONFIG !== 'undefined' && SERVICE_PLANS_CONFIG.plan_premium) {
          currentCompany.enabledModules = [...SERVICE_PLANS_CONFIG.plan_premium.modules];
        }
        currentCompany.billingPeriod = billingPeriod;
        currentCompany.contractFee = contractFee;
        currentCompany.billingDay = billingDay;
        currentCompany.contractNotes = contractNotes;
        if (servicePlan !== 'plan_personalizado' && SERVICE_PLANS_CONFIG[servicePlan]) {
          currentCompany.enabledModules = [...SERVICE_PLANS_CONFIG[servicePlan].modules];
        }
        if (password) currentCompany.password = password;
        currentCompany.passwordMaster = passwordMaster;
        currentCompany.passwordLite = passwordLite;
        sessionStorage.setItem(SESSION_KEY, JSON.stringify({ company: currentCompany, role: currentUserRole }));
        
        const dashCompanyName = document.getElementById('dash-company-name');
        const detailName = document.getElementById('detail-name');
        const detailNit = document.getElementById('detail-nit');
        const detailEmail = document.getElementById('detail-email');
        const detailPhone = document.getElementById('detail-phone');
        const detailContact = document.getElementById('detail-contact');
        const detailAddress = document.getElementById('detail-address');
        const topbarCompName = document.getElementById('topbar-company-name');
        if (dashCompanyName) dashCompanyName.textContent = companyName;
        if (detailName) detailName.textContent = companyName;
        if (detailNit) detailNit.textContent = nit || 'Sin Registrar';
        if (detailEmail) detailEmail.textContent = email;
        if (detailPhone) detailPhone.textContent = phone || 'Sin Registrar';
        if (detailContact) detailContact.textContent = contactName || 'Sin Registrar';
        if (detailAddress) detailAddress.textContent = address || 'Sin Registrar';
        if (topbarCompName) topbarCompName.textContent = companyName;
      }

      closeEditCompanyModal();
      renderMasterCompaniesGrid(inputSearchCompanies ? inputSearchCompanies.value : '');
      showToast(`¡Empresa "${companyName}" actualizada exitosamente!`, 'success');
    });
  }

  let activeChangePassCompanyId = null;

  function copyToClipboardText(text, successMsg) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(() => {
        showToast(successMsg, 'success');
      }).catch(() => {
        execFallbackCopy(text, successMsg);
      });
    } else {
      execFallbackCopy(text, successMsg);
    }
  }

  function execFallbackCopy(text, successMsg) {
    const el = document.createElement('textarea');
    el.value = text;
    el.setAttribute('readonly', '');
    el.style.position = 'absolute';
    el.style.left = '-9999px';
    document.body.appendChild(el);
    el.select();
    try {
      document.execCommand('copy');
      showToast(successMsg, 'success');
    } catch (err) {
      showToast('No se pudo copiar automáticamente. Puedes ver la clave en la tarjeta.', 'info');
    }
    document.body.removeChild(el);
  }

  function openChangePasswordModal(companyId, companyName, companyEmail, currentPass) {
    const modal = document.getElementById('modal-change-company-password');
    const lblName = document.getElementById('lbl-change-pass-company-name');
    const lblEmail = document.getElementById('lbl-change-pass-company-email');
    const inputPass = document.getElementById('input-new-company-password');

    if (!modal) return;
    activeChangePassCompanyId = companyId;
    if (lblName) lblName.textContent = companyName || '—';
    if (lblEmail) lblEmail.textContent = companyEmail || '—';
    if (inputPass) {
      inputPass.value = currentPass || '';
      inputPass.focus();
    }
    modal.classList.remove('hidden');
  }

  function closeChangePasswordModal() {
    const modal = document.getElementById('modal-change-company-password');
    if (modal) modal.classList.add('hidden');
    activeChangePassCompanyId = null;
  }

  function updateCompanyStatus(companyId, newStatus) {
    const companies = getCompanies();
    const comp = companies.find(c => c.id === companyId);
    if (!comp) return;
    comp.status = newStatus;
    saveCompanies(companies);
    if (currentCompany && currentCompany.id === companyId) {
      currentCompany.status = newStatus;
      sessionStorage.setItem(SESSION_KEY, JSON.stringify({ company: currentCompany, role: currentUserRole }));
    }
    renderMasterCompaniesGrid(inputSearchCompanies ? inputSearchCompanies.value : '');
    showToast(`El estado de "${comp.companyName}" ahora es: ${newStatus === 'terminada' ? 'Contrato Terminado' : 'Activa'}.`, 'info');
  }

  function deleteCompany(companyId, companyName) {
    let companies = getCompanies();
    const targetComp = companies.find(c => c.id === companyId);
    if (!targetComp) return;

    companies = companies.filter(c => c.id !== companyId);
    saveCompanies(companies);
    deleteCompanyFromCloud(companyId);

    if (currentCompany && currentCompany.id === companyId) {
      if (companies.length > 0) {
        const nextComp = companies.find(c => (c.email || "").toLowerCase() === MASTER_EMAIL.toLowerCase()) || companies[0];
        currentCompany = nextComp;
        sessionStorage.setItem(SESSION_KEY, JSON.stringify({ company: currentCompany, role: currentUserRole }));
      } else {
        currentCompany = null;
        sessionStorage.removeItem(SESSION_KEY);
      }
    }

    renderMasterCompaniesGrid(inputSearchCompanies ? inputSearchCompanies.value : '');
    showToast(`Empresa "${companyName}" eliminada permanentemente del sistema.`, 'success');
  }

  // ==========================================================================
  // CONFIGURACIÓN INTERACTIVA DE MÓDULOS DE LA EMPRESA (NÓMINA, COSTOS, ETC.)
  // ==========================================================================
  const SYSTEM_MODULES_METADATA = [
    { id: 'tab-0-dashboard', name: 'Dashboard General', icon: 'fa-gauge-high' },
    { id: 'tab-reportes-graficos', name: 'Reportes Gráficos', icon: 'fa-chart-pie' },
    { id: 'tab-1-ventas-diarias', name: 'Ventas Diarias', icon: 'fa-chart-line' },
    { id: 'tab-2-ventas-forma-pago', name: 'Ventas x Forma de Pago', icon: 'fa-credit-card' },
    { id: 'tab-3-productos-diarios', name: 'Productos Diarios', icon: 'fa-utensils' },
    { id: 'tab-4-productos-mensuales', name: 'Productos Mensuales', icon: 'fa-calendar-days' },
    { id: 'tab-5-compras-proveedor', name: 'Compras x Proveedor', icon: 'fa-truck-field' },
    { id: 'tab-6-compras-insumos', name: 'Compras x Insumos', icon: 'fa-boxes-stacked' },
    { id: 'tab-7-gastos-mensuales', name: 'Gastos Mensuales', icon: 'fa-file-invoice-dollar' },
    { id: 'tab-almuerzo-personal', name: 'Almuerzo Personal', icon: 'fa-bowl-food' },
    { id: 'tab-bajas-desperdicios', name: 'Bajas o Desperdicios', icon: 'fa-trash-can-arrow-up' },
    { id: 'tab-8-nomina', name: 'Nómina', icon: 'fa-users' },
    { id: 'tab-9-propinas-vendedor', name: 'Ventas x Vendedor', icon: 'fa-user-tag' },
    { id: 'tab-propinas', name: 'Propinas', icon: 'fa-hand-holding-dollar' },
    { id: 'tab-10-costos-ventas', name: 'Costos de Ventas (COGS)', icon: 'fa-calculator' },
    { id: 'tab-11-costos-compras', name: 'Costos de Compras', icon: 'fa-dolly' },
    { id: 'tab-recetario', name: 'Recetario y Fichas Técnicas', icon: 'fa-book-open-reader', tag: 'Culinario' },
    { id: 'tab-cotizador', name: 'Cotizador Financiero de Platos', icon: 'fa-calculator', tag: 'Culinario' },
    { id: 'tab-menu-engineering', name: 'Ingeniería del Menú', icon: 'fa-chess-knight', tag: 'Culinario' },
    { id: 'tab-12-comparativo-ventas', name: 'Comparativo Ventas', icon: 'fa-chart-column' },
    { id: 'tab-14-analisis-mensual', name: 'Análisis Mensual (P&L)', icon: 'fa-magnifying-glass-chart' },
    { id: 'tab-15-consolidado-anual', name: 'Consolidado Anual', icon: 'fa-calendar-check' }
  ];

  let companyBeingEdited = null;

  function openManageModulesModal(comp) {
    if (!comp) return;
    companyBeingEdited = comp;
    const modal = document.getElementById('modal-manage-company-modules');
    const lblName = document.getElementById('lbl-manage-modules-company-name');
    const container = document.getElementById('manage-modules-checklist');
    if (!modal || !container) return;

    if (lblName) lblName.textContent = comp.companyName;

    const enabled = Array.isArray(comp.enabledModules) ? comp.enabledModules : ALL_SYSTEM_MODULES;

    container.innerHTML = '';
    SYSTEM_MODULES_METADATA.forEach(mod => {
      const isChecked = enabled.includes(mod.id);
      const isNomina = mod.id === 'tab-8-nomina';
      const isCulinario = mod.tag === 'Culinario' || mod.id === 'tab-recetario' || mod.id === 'tab-cotizador' || mod.id === 'tab-menu-engineering';
      const label = document.createElement('label');
      label.className = 'module-check-card';
      const activeBg = isCulinario ? '#f0fdf4' : '#f0f9ff';
      const activeBorder = isCulinario ? '#86efac' : '#38bdf8';
      const iconColor = isNomina ? '#f59e0b' : (isCulinario ? '#059669' : '#0284c7');
      const accentColor = isCulinario ? '#059669' : '#0284c7';

      label.style.cssText = 'display:flex; align-items:center; gap:10px; padding:10px 14px; background:' + (isChecked ? activeBg : '#ffffff') + '; border:1.5px solid ' + (isChecked ? activeBorder : '#e2e8f0') + '; border-radius:10px; cursor:pointer; font-size:0.86rem; font-weight:600; color:#1e293b; user-select:none; transition:all 0.2s;';
      label.innerHTML = `
        <input type="checkbox" value="${mod.id}" ${isChecked ? 'checked' : ''} style="width:18px; height:18px; cursor:pointer; accent-color:${accentColor};">
        <i class="fa-solid ${mod.icon}" style="color:${iconColor}; font-size:16px;"></i>
        <span>${mod.name}</span>
        ${isNomina ? '<span style="font-size:10px; font-weight:700; background:#fef3c7; color:#b45309; padding:2px 7px; border-radius:6px; margin-left:auto;">P&L</span>' : ''}
        ${isCulinario ? '<span style="font-size:10px; font-weight:700; background:#dcfce7; color:#15803d; padding:2px 7px; border-radius:6px; margin-left:auto;">Culinario</span>' : ''}
      `;
      const input = label.querySelector('input');
      input.addEventListener('change', () => {
        label.style.borderColor = input.checked ? activeBorder : '#e2e8f0';
        label.style.background = input.checked ? activeBg : '#ffffff';
      });
      container.appendChild(label);
    });

    modal.classList.remove('hidden');
  }

  function closeManageModulesModal() {
    const modal = document.getElementById('modal-manage-company-modules');
    if (modal) modal.classList.add('hidden');
    companyBeingEdited = null;
  }

  const btnSaveManageModules = document.getElementById('btn-save-manage-modules');
  if (btnSaveManageModules) {
    btnSaveManageModules.addEventListener('click', () => {
      if (!companyBeingEdited) return;
      const checked = Array.from(document.querySelectorAll('#manage-modules-checklist input[type="checkbox"]:checked')).map(cb => cb.value);
      if (checked.length === 0) {
        showToast('Debes mantener al menos un módulo habilitado.', 'error');
        return;
      }

      companyBeingEdited.enabledModules = checked;

      const companies = getCompanies();
      const idx = companies.findIndex(c => c.id === companyBeingEdited.id);
      if (idx !== -1) {
        companies[idx] = companyBeingEdited;
        saveCompanies(companies);
      }

      if (firestoreDb && companyBeingEdited.id) {
        firestoreDb.collection('companies').doc(companyBeingEdited.id).update({
          enabledModules: checked,
          _syncedAt: Date.now()
        }).catch(err => console.error('Error actualizando módulos en Firestore:', err));
      }

      if (currentCompany && currentCompany.id === companyBeingEdited.id) {
        currentCompany = companyBeingEdited;
        sessionStorage.setItem(SESSION_KEY, JSON.stringify({ company: currentCompany, role: currentUserRole }));
        configureCompanyTabs(currentCompany);
        renderAll14Modules();
        updateAuditPeriodBadge();
      }

      if (masterCompaniesSection && !masterCompaniesSection.classList.contains('hidden')) {
        renderMasterCompaniesGrid(inputSearchCompanies ? inputSearchCompanies.value : '');
      }

      const hasNom = checked.includes('tab-8-nomina');
      showToast(`Módulos actualizados para "${companyBeingEdited.companyName}". Nómina: ${hasNom ? 'Activa' : 'Inactiva (Excluida del P&L)'}.`, 'success');
      closeManageModulesModal();
    });
  }

  const btnCloseManageModules = document.getElementById('btn-close-manage-modules');
  const btnCancelManageModules = document.getElementById('btn-cancel-manage-modules');
  if (btnCloseManageModules) btnCloseManageModules.addEventListener('click', closeManageModulesModal);
  if (btnCancelManageModules) btnCancelManageModules.addEventListener('click', closeManageModulesModal);

  // Modal de restablecer contraseña de empresa
  const btnCloseChangePass = document.getElementById('btn-close-change-pass');
  const btnCancelChangePass = document.getElementById('btn-cancel-change-pass');
  const btnSaveChangePass = document.getElementById('btn-save-change-pass');
  const modalChangeCompanyPass = document.getElementById('modal-change-company-password');
  const linkForgotPassword = document.getElementById('link-forgot-password');

  if (btnCloseChangePass) btnCloseChangePass.addEventListener('click', closeChangePasswordModal);
  if (btnCancelChangePass) btnCancelChangePass.addEventListener('click', closeChangePasswordModal);
  if (modalChangeCompanyPass) {
    modalChangeCompanyPass.addEventListener('click', (e) => {
      if (e.target === modalChangeCompanyPass) closeChangePasswordModal();
    });
  }
  if (btnSaveChangePass) {
    btnSaveChangePass.addEventListener('click', () => {
      const inputPass = document.getElementById('input-new-company-password');
      const newPass = inputPass ? inputPass.value.trim() : '';
      if (!newPass) {
        showToast('Por favor ingresa la nueva contraseña.', 'error');
        return;
      }
      if (newPass.length < 4) {
        showToast('La contraseña debe tener al menos 4 caracteres.', 'error');
        return;
      }
      const companies = getCompanies();
      const comp = companies.find(c => c.id === activeChangePassCompanyId);
      if (comp) {
        comp.password = newPass;
        saveCompanies(companies);
        if (currentCompany && currentCompany.id === comp.id) {
          currentCompany.password = newPass;
          sessionStorage.setItem(SESSION_KEY, JSON.stringify({ company: currentCompany, role: currentUserRole }));
        }
        closeChangePasswordModal();
        renderMasterCompaniesGrid(inputSearchCompanies ? inputSearchCompanies.value : '');
        showToast(`¡Contraseña actualizada con éxito para "${comp.companyName}"! La nueva clave es: ${newPass}`, 'success');
      }
    });
  }

  if (linkForgotPassword) {
    linkForgotPassword.addEventListener('click', (e) => {
      e.preventDefault();
      showToast('Si olvidaste tu contraseña, el Administrador Master de DC Asesorías (dcasesoriascol@gmail.com / WhatsApp: 316 544 3285) puede consultarla o cambiártela de inmediato en el Panel Master.', 'info');
    });
  }

  const btnMasterManageModules = document.getElementById('btn-master-manage-modules');
  if (btnMasterManageModules) {
    btnMasterManageModules.addEventListener('click', () => {
      if (!currentCompany) {
        showToast('Selecciona una empresa primero.', 'info');
        return;
      }
      openManageModulesModal(currentCompany);
    });
  }

  function enterCompanyAsMaster(companyId) {
    const companies = getCompanies();
    const targetCompany = companies.find(c => c.id === companyId);
    if (!targetCompany) {
      showToast('No se encontró la empresa seleccionada.', 'error');
      return;
    }

    if (masterCompaniesSection) {
      masterCompaniesSection.classList.add('hidden');
    }
    dashboardSection.classList.remove('hidden');

    // Siempre entra con rol Master para poder subir archivos, auditar y gestionar
    currentUserRole = 'master';
    showDashboard(targetCompany, 'master');
    showToast(`🏢 Ahora estás gestionando: ${targetCompany.companyName}`, 'success');
  }

  function checkActiveSession() {
    const isMaster = sessionStorage.getItem('isMasterSession') === 'true';
    const active = sessionStorage.getItem(SESSION_KEY);
    if (active) {
      try {
        const sessionData = JSON.parse(active);
        const comp = sessionData.company || sessionData;
        if (comp && comp.id) {
          const companies = getCompanies();
          let targetComp = companies.find(c => c.id === comp.id) || comp;
          // Preservar períodos y datos que ya estaban en sesión
          if (comp.periods && Object.keys(comp.periods).length > 0) {
            targetComp.periods = { ...(targetComp.periods || {}), ...comp.periods };
          }
          if (comp.businessData) {
            targetComp.businessData = comp.businessData;
          }
          if (comp.selectedPeriod) {
            targetComp.selectedPeriod = comp.selectedPeriod;
          }
          const role = isMaster ? 'master' : (sessionData.role || 'lite');
          showDashboard(targetComp, role);
          return;
        }
      } catch (e) {
        sessionStorage.removeItem(SESSION_KEY);
      }
    }
    if (isMaster) {
      showMasterCompaniesView();
      return;
    }
    document.documentElement.classList.remove('has-active-session');
    if (authSection) authSection.classList.remove('hidden');
  }

  // ==========================================================================
  // RENDERIZADO DE LOS 14 MÓDULOS EN ORDEN
  // ==========================================================================
  
  // ==========================================================================
  // DASHBOARD GENERAL EJECUTIVO (TABLERO 360° DE GESTIÓN INTEGRAL)
  // ==========================================================================
  function renderExecutiveDashboard() {
    if (!currentCompany || !currentCompany.businessData) return;
    const bd = currentCompany.businessData;

    // 1. RECOLECCIÓN Y CONSOLIDACIÓN DE DATOS
    const sales = bd.sales || [];
    const paymentMethods = bd.paymentMethods || [];
    const monthlyProducts = bd.monthlyProducts || [];
    const dailyProducts = bd.dailyProducts || [];
    const expenses = bd.expenses || [];
    const payroll = bd.payroll || [];
    const suppliers = bd.suppliers || [];
    const supplies = bd.supplies || [];
    const cogs = bd.cogs || [];
    const purchaseCosts = bd.purchaseCosts || [];

    // VENTAS TOTALES Y DÍAS
    let totalSales = 0;
    let salesDays = 0;
    let totalPax = 0;
    let totalCtas = 0;

    if (sales.length > 0) {
      sales.forEach(row => {
        const vta = Number(row.total_vta) || 0;
        if (vta > 0) salesDays++;
        totalSales += vta;
        totalPax += Number(row.no_pax) || 0;
        totalCtas += Number(row.no_ctas) || 0;
      });
    } else if (dailyProducts.length > 0) {
      dailyProducts.forEach(p => {
        totalSales += Number(p.venta_total !== undefined ? p.venta_total : (p.total || ((Number(p.und_vendidas || p.cantidad || 0)) * (Number(p.precio_con_impo || p.precio || 0))))) || 0;
      });
      salesDays = 1;
    } else if (monthlyProducts.length > 0) {
      monthlyProducts.forEach(p => {
        totalSales += Number(p.venta_total !== undefined ? p.venta_total : (p.total_venta !== undefined ? p.total_venta : (p.total || ((Number(p.cantidad || 0)) * (Number(p.precio || 0)))))) || 0;
      });
      salesDays = 30;
    } else if (paymentMethods.length > 0) {
      paymentMethods.forEach(pm => {
        totalSales += Number(pm.monto !== undefined ? pm.monto : (pm.venta_dia !== undefined ? pm.venta_dia : (pm.total || 0))) || 0;
      });
      salesDays = 1;
    }

    // COSTO DE MATERIA PRIMA (COGS / INSUMOS)
    let totalCogs = 0;
    if (cogs.length > 0) {
      cogs.forEach(c => {
        totalCogs += Number(c.venta_costo !== undefined ? c.venta_costo : ((c.costo || 0) * (c.cant || 0))) || 0;
      });
    } else if (purchaseCosts.length > 0) {
      totalCogs = purchaseCosts.reduce((acc, r) => acc + (Number(r.total) || 0), 0);
    } else if (suppliers.length > 0) {
      totalCogs = suppliers.reduce((acc, r) => acc + (Number(r.total) || 0), 0);
    } else if (supplies.length > 0) {
      supplies.forEach(s => {
        totalCogs += Number(s.total !== undefined ? s.total : ((s.cant || 0) * (s.costo || s.precio || 0))) || 0;
      });
    }

    // GASTOS OPERATIVOS (OPEX)
    let totalExpenses = 0;
    expenses.forEach(e => {
      totalExpenses += Number(e.total !== undefined ? e.total : (e.monto !== undefined ? e.monto : (e.amount || 0))) || 0;
    });

    // NÓMINA (PERSONAL)
    let totalPayroll = 0;
    const hasPayrollModule = (typeof isCompanyPDSA === 'function' ? !isCompanyPDSA() : true) && (!currentCompany.enabledModules || currentCompany.enabledModules.includes('tab-8-nomina'));
    if (hasPayrollModule) {
      payroll.forEach(p => {
        totalPayroll += Number(p.total !== undefined ? p.total : (p.net !== undefined ? p.net : (p.amount || 0))) || 0;
      });
    }

    // RENTABILIDAD Y MÁRGENES
    const grossProfit = totalSales - totalCogs;
    const grossMarginPct = totalSales > 0 ? (grossProfit / totalSales) * 100 : 0;
    const opexTotal = totalExpenses + totalPayroll;
    const opexPct = totalSales > 0 ? (opexTotal / totalSales) * 100 : 0;
    const netProfit = grossProfit - opexTotal;
    const netMarginPct = totalSales > 0 ? (netProfit / totalSales) * 100 : 0;
    const cogsPct = totalSales > 0 ? (totalCogs / totalSales) * 100 : 0;
    const avgTicket = totalCtas > 0 ? Math.round(totalSales / totalCtas) : 0;
    const avgSalesDay = salesDays > 0 ? Math.round(totalSales / salesDays) : 0;

    // ACTUALIZAR KPI 1: VENTAS
    const elSales = document.getElementById('dash-kpi-total-sales');
    const elDays = document.getElementById('dash-kpi-sales-days');
    const elAvg = document.getElementById('dash-kpi-sales-avg');
    if (elSales) elSales.textContent = formatMoney(totalSales);
    if (elDays) elDays.innerHTML = `<i class="fa-regular fa-calendar-days"></i> ${salesDays} ${salesDays === 1 ? 'día' : 'días'}`;
    if (elAvg) elAvg.textContent = `Prom: ${formatMoney(avgSalesDay)} / día`;

    // ACTUALIZAR KPI 2: UTILIDAD NETA
    const elNet = document.getElementById('dash-kpi-net-profit');
    const elNetPct = document.getElementById('dash-kpi-profit-margin');
    const elGross = document.getElementById('dash-kpi-gross-profit');
    if (elNet) {
      elNet.textContent = formatMoney(netProfit);
      elNet.style.color = netProfit >= 0 ? '#15803d' : '#b91c1c';
    }
    if (elNetPct) {
      elNetPct.innerHTML = `<i class="fa-solid fa-percent"></i> ${netMarginPct.toFixed(1)}% Margen`;
      if (netMarginPct >= 18) {
        elNetPct.className = 'kpi-badge profit-badge';
        elNetPct.style.background = '#dcfce7'; elNetPct.style.color = '#15803d';
      } else if (netMarginPct >= 8) {
        elNetPct.className = 'kpi-badge profit-badge';
        elNetPct.style.background = '#fef3c7'; elNetPct.style.color = '#b45309';
      } else {
        elNetPct.className = 'kpi-badge profit-badge';
        elNetPct.style.background = '#fee2e2'; elNetPct.style.color = '#b91c1c';
      }
    }
    if (elGross) elGross.textContent = `Bruta: ${formatMoney(grossProfit)}`;

    // ACTUALIZAR KPI 3: FOOD COST (COGS)
    const elCogsPct = document.getElementById('dash-kpi-cogs-pct');
    const elCogsStatus = document.getElementById('dash-kpi-cogs-status');
    const elCogsTot = document.getElementById('dash-kpi-cogs-total');
    if (elCogsPct) elCogsPct.textContent = `${cogsPct.toFixed(1)}%`;
    if (elCogsTot) elCogsTot.textContent = `Costo: ${formatMoney(totalCogs)}`;
    if (elCogsStatus) {
      if (cogsPct === 0) {
        elCogsStatus.innerHTML = '<i class="fa-solid fa-info-circle"></i> Sin Datos';
        elCogsStatus.style.background = '#f1f5f9'; elCogsStatus.style.color = '#475569';
      } else if (cogsPct <= 32) {
        elCogsStatus.innerHTML = '<i class="fa-solid fa-circle-check"></i> Óptimo (≤32%)';
        elCogsStatus.style.background = '#dcfce7'; elCogsStatus.style.color = '#15803d';
      } else if (cogsPct <= 36) {
        elCogsStatus.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i> En Alerta (33-36%)';
        elCogsStatus.style.background = '#fef3c7'; elCogsStatus.style.color = '#b45309';
      } else {
        elCogsStatus.innerHTML = '<i class="fa-solid fa-circle-exclamation"></i> Desviado (>36%)';
        elCogsStatus.style.background = '#fee2e2'; elCogsStatus.style.color = '#b91c1c';
      }
    }

    // ACTUALIZAR KPI 4: GASTOS Y NÓMINA
    const elOpexTot = document.getElementById('dash-kpi-opex-total');
    const elOpexPct = document.getElementById('dash-kpi-opex-pct');
    const elPayrollSub = document.getElementById('dash-kpi-payroll-sub');
    if (elOpexTot) elOpexTot.textContent = formatMoney(opexTotal);
    if (elOpexPct) elOpexPct.textContent = `${opexPct.toFixed(1)}% s/ventas`;
    if (elPayrollSub) elPayrollSub.textContent = `Nómina: ${formatMoney(totalPayroll)} (${totalSales > 0 ? ((totalPayroll/totalSales)*100).toFixed(0) : 0}%)`;

    // ACTUALIZAR KPI 5: TICKET PROMEDIO Y VOLUMEN
    const elAvgTick = document.getElementById('dash-kpi-avg-ticket');
    const elInvCount = document.getElementById('dash-kpi-invoices-count');
    const elPaxCount = document.getElementById('dash-kpi-pax-count');
    if (elAvgTick) elAvgTick.textContent = formatMoney(avgTicket);
    if (elInvCount) elInvCount.innerHTML = `<i class="fa-solid fa-file-invoice"></i> ${totalCtas} Facturas`;
    if (elPaxCount) elPaxCount.textContent = `${totalPax} Pax atendidos`;

    // ACTUALIZAR KPI 6: DIAGNÓSTICO OPERATIVO
    const elHealthStat = document.getElementById('dash-kpi-health-status');
    const elHealthBdg = document.getElementById('dash-kpi-health-badge');
    const elHealthDesc = document.getElementById('dash-kpi-health-desc');
    if (elHealthStat && elHealthBdg && elHealthDesc) {
      if (totalSales === 0) {
        elHealthStat.textContent = 'En Espera';
        elHealthBdg.innerHTML = '<i class="fa-solid fa-calendar-plus"></i> Sin Datos';
        elHealthBdg.style.background = '#f1f5f9'; elHealthBdg.style.color = '#475569';
        elHealthDesc.textContent = 'Pendiente subir ventas del período';
      } else if (netProfit > 0 && netMarginPct >= 15) {
        elHealthStat.textContent = 'Superávit Alto';
        elHealthBdg.innerHTML = '<i class="fa-solid fa-crown text-gold"></i> Operación Excelente';
        elHealthBdg.style.background = '#dcfce7'; elHealthBdg.style.color = '#15803d';
        elHealthDesc.textContent = `Rentabilidad sobresaliente (${netMarginPct.toFixed(1)}%)`;
      } else if (netProfit >= 0) {
        elHealthStat.textContent = 'Superávit';
        elHealthBdg.innerHTML = '<i class="fa-solid fa-check"></i> Operación Sana';
        elHealthBdg.style.background = '#ecfeff'; elHealthBdg.style.color = '#0e7490';
        elHealthDesc.textContent = 'Margen equilibrado y positivo';
      } else {
        elHealthStat.textContent = 'Déficit';
        elHealthBdg.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i> En Pérdida';
        elHealthBdg.style.background = '#fee2e2'; elHealthBdg.style.color = '#b91c1c';
        elHealthDesc.textContent = 'Revisar costos de insumos y nómina';
      }
    }

    // ACTUALIZAR BARRA APILADA DE P&L
    const segCogs = document.getElementById('bar-seg-cogs');
    const segPay = document.getElementById('bar-seg-payroll');
    const segExp = document.getElementById('bar-seg-expenses');
    const segNet = document.getElementById('bar-seg-net');

    const legCogs = document.getElementById('legend-cogs-val');
    const legPay = document.getElementById('legend-payroll-val');
    const legExp = document.getElementById('legend-expenses-val');
    const legNet = document.getElementById('legend-net-val');

    if (totalSales > 0) {
      const pCogs = Math.max(0, Math.min(100, (totalCogs / totalSales) * 100));
      const pPay = Math.max(0, Math.min(100, (totalPayroll / totalSales) * 100));
      const pExp = Math.max(0, Math.min(100, (totalExpenses / totalSales) * 100));
      const pNet = Math.max(0, Math.min(100, (Math.max(0, netProfit) / totalSales) * 100));

      if (segCogs) segCogs.style.width = `${pCogs.toFixed(1)}%`;
      if (segPay) segPay.style.width = `${pPay.toFixed(1)}%`;
      if (segExp) segExp.style.width = `${pExp.toFixed(1)}%`;
      if (segNet) segNet.style.width = `${pNet.toFixed(1)}%`;

      if (legCogs) legCogs.textContent = `${formatMoney(totalCogs)} (${pCogs.toFixed(1)}%)`;
      if (legPay) legPay.textContent = `${formatMoney(totalPayroll)} (${pPay.toFixed(1)}%)`;
      if (legExp) legExp.textContent = `${formatMoney(totalExpenses)} (${pExp.toFixed(1)}%)`;
      if (legNet) legNet.textContent = `${formatMoney(netProfit)} (${netMarginPct.toFixed(1)}%)`;
    } else {
      if (segCogs) segCogs.style.width = '0%';
      if (segPay) segPay.style.width = '0%';
      if (segExp) segExp.style.width = '0%';
      if (segNet) segNet.style.width = '0%';
      if (legCogs) legCogs.textContent = '$ 0 (0%)';
      if (legPay) legPay.textContent = '$ 0 (0%)';
      if (legExp) legExp.textContent = '$ 0 (0%)';
      if (legNet) legNet.textContent = '$ 0 (0%)';
    }

    // ACTUALIZAR FORMAS DE PAGO
    const containerPayments = document.getElementById('dash-payment-methods-list');
    const badgeTopChannel = document.getElementById('dash-payment-top-channel');
    if (containerPayments) {
      let pmTotals = {
        'Tarjetas Débito / Crédito': 0,
        'Efectivo': 0,
        'Transferencias / Nequi / Daviplata': 0,
        'Otros': 0
      };

      if (paymentMethods.length > 0) {
        paymentMethods.forEach(row => {
          const m = Number(row.monto !== undefined ? row.monto : (row.venta_dia !== undefined ? row.venta_dia : (row.total || 0))) || 0;
          const metodo = (row.metodo || row.forma_pago || row.canal || '').trim().toLowerCase();
          if (metodo.includes('tarjet') || metodo.includes('datafono') || metodo.includes('pos') || metodo.includes('credito') || metodo.includes('debito')) {
            pmTotals['Tarjetas Débito / Crédito'] += m;
          } else if (metodo.includes('efectivo') || metodo.includes('cash')) {
            pmTotals['Efectivo'] += m;
          } else if (metodo.includes('nequi') || metodo.includes('daviplata') || metodo.includes('transf') || metodo.includes('bancolombia')) {
            pmTotals['Transferencias / Nequi / Daviplata'] += m;
          } else {
            pmTotals['Otros'] += m;
          }
        });
      }

      const totalPM = Object.values(pmTotals).reduce((a, b) => a + b, 0) || totalSales || 1;
      let topChannelName = 'Sin Datos';
      let topChannelVal = 0;

      let htmlPM = '';
      const colors = {
        'Tarjetas Débito / Crédito': '#3b82f6',
        'Efectivo': '#10b981',
        'Transferencias / Nequi / Daviplata': '#8b5cf6',
        'Otros': '#64748b'
      };
      const icons = {
        'Tarjetas Débito / Crédito': 'fa-credit-card',
        'Efectivo': 'fa-money-bill-wave',
        'Transferencias / Nequi / Daviplata': 'fa-mobile-screen-button',
        'Otros': 'fa-receipt'
      };

      Object.keys(pmTotals).forEach(ch => {
        const val = pmTotals[ch];
        if (val > topChannelVal) {
          topChannelVal = val;
          topChannelName = ch;
        }
        const pct = totalPM > 0 ? (val / totalPM) * 100 : 0;
        htmlPM += `
          <div class="payment-bar-row">
            <span class="payment-bar-label"><i class="fa-solid ${icons[ch] || 'fa-coins'}" style="color:${colors[ch]};"></i> ${ch}</span>
            <div class="payment-bar-track">
              <div class="payment-bar-fill" style="width:${pct.toFixed(1)}%; background:${colors[ch]};"></div>
            </div>
            <span class="payment-bar-val">${formatMoney(val)} <span style="font-size:10.5px; color:#64748b;">(${pct.toFixed(0)}%)</span></span>
          </div>`;
      });

      containerPayments.innerHTML = htmlPM;
      if (badgeTopChannel) {
        badgeTopChannel.textContent = topChannelVal > 0 ? `Canal Líder: ${topChannelName} (${((topChannelVal/totalPM)*100).toFixed(0)}%)` : 'Canal Líder: --';
      }
    }

    // ACTUALIZAR MATRIZ KASAVANA (RESUMEN 4 CUADRANTES)
    const elKasStars = document.getElementById('dash-kas-stars-count');
    const elKasPlow = document.getElementById('dash-kas-plow-count');
    const elKasPuz = document.getElementById('dash-kas-puzzle-count');
    const elKasDogs = document.getElementById('dash-kas-dogs-count');

    let countStars = 0, countHorses = 0, countPuzzles = 0, countDogs = 0;
    let menuItems = [];
    if (typeof getActiveCompanyMenuEngData === 'function') {
      try {
        menuItems = getActiveCompanyMenuEngData() || [];
      } catch (e) {
        console.warn('Aviso obteniendo datos de ingeniería para dashboard:', e);
      }
    }

    if (menuItems.length > 0) {
      const N = menuItems.length;
      let totalUnits = 0;
      let totalMenuCM = 0;
      menuItems.forEach(item => {
        const margin = (Number(item.price) || 0) - (Number(item.cost) || 0);
        const units = Number(item.unitsSold) || 0;
        totalUnits += units;
        totalMenuCM += (margin * units);
      });
      const avgMargin = totalUnits > 0 ? (totalMenuCM / totalUnits) : (menuItems.reduce((acc, i) => acc + (Number(i.price) - Number(i.cost)), 0) / (N || 1));
      const hurdleUnits = N > 0 ? (0.70 * (totalUnits / N)) : 0;

      menuItems.forEach(item => {
        const margin = (Number(item.price) || 0) - (Number(item.cost) || 0);
        const units = Number(item.unitsSold) || 0;
        const highProfit = margin >= avgMargin;
        const highPopularity = units >= hurdleUnits;

        if (highProfit && highPopularity) countStars++;
        else if (!highProfit && highPopularity) countHorses++;
        else if (highProfit && !highPopularity) countPuzzles++;
        else countDogs++;
      });
    }

    if (elKasStars) elKasStars.textContent = countStars;
    if (elKasPlow) elKasPlow.textContent = countHorses;
    if (elKasPuz) elKasPuz.textContent = countPuzzles;
    if (elKasDogs) elKasDogs.textContent = countDogs;

    // ACTUALIZAR TOP 5 PRODUCTOS MÁS VENDIDOS
    const containerTopProds = document.getElementById('dash-top-products-list');
    if (containerTopProds) {
      let prodsPool = [];
      if (dailyProducts.length > 0) prodsPool = dailyProducts;
      else if (monthlyProducts.length > 0) prodsPool = monthlyProducts;
      else if (menuItems.length > 0) {
        prodsPool = menuItems.map(m => ({
          producto: m.name,
          und_vendidas: m.unitsSold,
          venta_total: m.price * m.unitsSold
        }));
      }

      if (prodsPool.length > 0) {
        const grouped = {};
        prodsPool.forEach(p => {
          const name = (p.producto || p.name || p.nombre || 'Producto').trim();
          const units = Number(p.und_vendidas !== undefined ? p.und_vendidas : (p.cantidad || p.unitsSold || 0)) || 0;
          const total = Number(p.venta_total !== undefined ? p.venta_total : (p.total !== undefined ? p.total : (p.total_venta || (units * (Number(p.precio || p.price || 0)))))) || 0;
          if (!grouped[name]) grouped[name] = { name, units: 0, total: 0 };
          grouped[name].units += units;
          grouped[name].total += total;
        });

        const sortedProds = Object.values(grouped).sort((a, b) => b.total - a.total).slice(0, 5);
        let htmlProds = '';
        sortedProds.forEach((p, idx) => {
          htmlProds += `
            <div class="top-product-item">
              <div class="top-prod-left">
                <span class="top-prod-rank rank-${idx + 1}">${idx + 1}</span>
                <span class="top-prod-name" title="${p.name}">${p.name}</span>
              </div>
              <span class="top-prod-stats">${formatMoney(p.total)} <span style="font-size:11px; color:#64748b; font-weight:normal;">(${p.units} und)</span></span>
            </div>`;
        });
        containerTopProds.innerHTML = htmlProds;
      } else {
        containerTopProds.innerHTML = `
          <div style="text-align:center; padding:18px 10px; color:#64748b; font-size:12px;">
            <i class="fa-solid fa-utensils" style="font-size:20px; color:#cbd5e1; display:block; margin-bottom:6px;"></i>
            Sin registro de productos vendidos para este período
          </div>`;
      }
    }
  }

  // Inicializar listeners del Dashboard Ejecutivo y Modal Ficha
  
  // ==========================================================================
  // GESTOR DE LA PASTILLA Y MODAL DE CUENTA (EMPRESA, CONTRATO Y USUARIOS)
  // ==========================================================================
  function renderAccountUsersTable() {
    const tbody = document.getElementById('account-users-tbody');
    if (!tbody || !currentCompany) return;

    let usersList = [];

    // 1. Usuario Master Administrador de la Empresa
    const masterAdminName = currentCompany.contactName ? `Administrador (${currentCompany.contactName})` : 'Usuario Administrador Master';
    usersList.push({
      name: masterAdminName,
      email: currentCompany.email || 'Sin correo',
      role: 'master',
      roleLabel: 'Master (Control Total)',
      permissions: 'Gestión Completa, Carga de Archivos y Configuración',
      status: 'Activo',
      isSystem: true
    });

    // 2. Usuario Lite Operativo / Consulta
    usersList.push({
      name: 'Usuario de Consulta Operativa',
      email: currentCompany.email || 'Sin correo',
      role: 'lite',
      roleLabel: 'Lite (Solo Lectura)',
      permissions: 'Visualización y Auditoría de Informes',
      status: 'Activo',
      isSystem: true
    });

    // 3. Usuarios adicionales creados en la empresa
    if (Array.isArray(currentCompany.users)) {
      currentCompany.users.forEach((u, idx) => {
        usersList.push({
          index: idx,
          name: u.name || 'Colaborador',
          email: u.email || '',
          role: u.role || 'lite',
          roleLabel: u.role === 'master' ? 'Master (Control Total)' : 'Lite (Solo Lectura)',
          permissions: u.role === 'master' ? 'Gestión Completa y Cargas' : 'Visualización de Informes',
          status: u.status || 'Activo',
          isSystem: false
        });
      });
    }

    let html = '';
    usersList.forEach(u => {
      const isMaster = u.role === 'master';
      html += `
        <tr>
          <td>
            <div style="display:flex; align-items:center; gap:8px;">
              <div style="width:28px; height:28px; border-radius:50%; background:${isMaster ? '#fffbeb' : '#eff6ff'}; color:${isMaster ? '#b45309' : '#1d4ed8'}; display:flex; align-items:center; justify-content:center; font-size:12px; font-weight:700;">
                <i class="fa-solid ${isMaster ? 'fa-crown' : 'fa-user'}"></i>
              </div>
              <div>
                <strong style="color:#0f172a; display:block;">${u.name}</strong>
                ${u.isSystem ? '<span style="font-size:10px; color:#64748b;">Usuario del Sistema</span>' : '<span style="font-size:10px; color:#10b981;">Creado en la Empresa</span>'}
              </div>
            </div>
          </td>
          <td><span style="color:#334155; font-family:monospace;">${u.email}</span></td>
          <td>
            <span class="user-badge-role ${isMaster ? 'master' : 'lite'}">
              <i class="fa-solid ${isMaster ? 'fa-crown text-gold' : 'fa-eye'}"></i>
              ${u.roleLabel}
            </span>
          </td>
          <td><span style="font-size:11.5px; color:#475569;">${u.permissions}</span></td>
          <td><span class="user-badge-status">${u.status}</span></td>
          <td style="text-align:center;">
            ${u.isSystem ? 
              '<span style="font-size:11px; color:#94a3b8; font-style:italic;">Predeterminado</span>' : 
              `<button type="button" class="btn btn-xs btn-outline-danger btn-delete-account-user" data-user-idx="${u.index}" title="Eliminar usuario">
                 <i class="fa-solid fa-trash-can"></i>
               </button>`
            }
          </td>
        </tr>`;
    });

    tbody.innerHTML = html;

    // Listener para eliminar usuario creado
    tbody.querySelectorAll('.btn-delete-account-user').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const idx = parseInt(btn.getAttribute('data-user-idx'), 10);
        if (!isNaN(idx) && currentCompany && Array.isArray(currentCompany.users)) {
          const removedUser = currentCompany.users[idx];
          if (confirm(`¿Estás seguro de eliminar el usuario "${removedUser ? removedUser.name : ''}"?`)) {
            currentCompany.users.splice(idx, 1);
            try {
              updateCurrentCompanyData(true);
            } catch (err) {
              console.warn('Error al guardar eliminación de usuario:', err);
            }
            renderAccountUsersTable();
            if (typeof showToast === 'function') {
              showToast('Usuario eliminado correctamente.', 'success');
            }
          }
        }
      });
    });
  }

  function initAccountModalListeners() {
    const btnTopbarAccount = document.getElementById('btn-topbar-account');
    const modalAccount = document.getElementById('account-modal');
    const btnClose1 = document.getElementById('btn-close-account-modal');
    const btnClose2 = document.getElementById('btn-close-account-modal-2');

    // Botón para desplegar formulario de nuevo usuario
    const btnToggleForm = document.getElementById('btn-toggle-create-user-form');
    const formContainer = document.getElementById('create-user-form-container');
    const btnCancelForm = document.getElementById('btn-cancel-create-user');
    const btnSaveUser = document.getElementById('btn-save-new-user');

    // Pestañas internas del modal
    document.querySelectorAll('.account-tab-btn').forEach(tabBtn => {
      tabBtn.addEventListener('click', () => {
        const targetId = tabBtn.getAttribute('data-acc-tab');
        document.querySelectorAll('.account-tab-btn').forEach(b => b.classList.remove('active'));
        document.querySelectorAll('.account-tab-pane').forEach(p => p.classList.remove('active'));

        tabBtn.classList.add('active');
        const targetPane = document.getElementById(targetId);
        if (targetPane) targetPane.classList.add('active');

        if (targetId === 'acc-tab-usuarios') {
          renderAccountUsersTable();
        }
      });
    });

    // Abrir modal de cuenta
    if (btnTopbarAccount && modalAccount) {
      btnTopbarAccount.addEventListener('click', () => {
        if (!currentCompany) return;
        
        // Sincronizar nombres y datos en la cabecera del modal
        const subTitle = document.getElementById('account-modal-company-title');
        if (subTitle) subTitle.textContent = currentCompany.companyName || 'Empresa';
        
        const topAccountName = document.getElementById('topbar-account-company-name');
        if (topAccountName) topAccountName.textContent = currentCompany.companyName || 'Empresa';

        // Renderizar tabla de usuarios
        renderAccountUsersTable();

        modalAccount.classList.remove('hidden');
        modalAccount.style.display = 'flex';
      });
    }

    // Cerrar modal de cuenta
    [btnClose1, btnClose2].forEach(btn => {
      if (btn && modalAccount) {
        btn.addEventListener('click', () => {
          modalAccount.classList.add('hidden');
          modalAccount.style.display = 'none';
        });
      }
    });

    if (modalAccount) {
      modalAccount.addEventListener('click', (e) => {
        if (e.target === modalAccount) {
          modalAccount.classList.add('hidden');
          modalAccount.style.display = 'none';
        }
      });
    }

    // Control de formulario crear usuario
    if (btnToggleForm && formContainer) {
      btnToggleForm.addEventListener('click', () => {
        const isHidden = formContainer.style.display === 'none';
        formContainer.style.display = isHidden ? 'block' : 'none';
        if (isHidden) {
          const inp = document.getElementById('new-user-name');
          if (inp) inp.focus();
        }
      });
    }

    if (btnCancelForm && formContainer) {
      btnCancelForm.addEventListener('click', () => {
        formContainer.style.display = 'none';
        const in1 = document.getElementById('new-user-name');
        const in2 = document.getElementById('new-user-email');
        const in3 = document.getElementById('new-user-password');
        if (in1) in1.value = '';
        if (in2) in2.value = '';
        if (in3) in3.value = '';
      });
    }

    if (btnSaveUser) {
      btnSaveUser.addEventListener('click', () => {
        if (!currentCompany) return;

        const nameInp = document.getElementById('new-user-name');
        const emailInp = document.getElementById('new-user-email');
        const passInp = document.getElementById('new-user-password');
        const roleInp = document.getElementById('new-user-role');

        const name = (nameInp ? nameInp.value : '').trim();
        const email = (emailInp ? emailInp.value : '').trim().toLowerCase();
        const password = (passInp ? passInp.value : '').trim();
        const role = roleInp ? roleInp.value : 'lite';

        if (!name || !email || !password) {
          if (typeof showToast === 'function') {
            showToast('Por favor completa el nombre, correo y contraseña del usuario.', 'warning');
          }
          return;
        }

        if (!Array.isArray(currentCompany.users)) {
          currentCompany.users = [];
        }

        // Verificar si el correo ya existe
        const exists = currentCompany.users.some(u => u.email && u.email.toLowerCase() === email);
        if (exists) {
          if (typeof showToast === 'function') {
            showToast('Ya existe un usuario registrado con este correo en la empresa.', 'warning');
          }
          return;
        }

        const newUser = {
          name,
          email,
          password,
          role,
          status: 'Activo',
          createdAt: new Date().toISOString()
        };

        currentCompany.users.push(newUser);

        try {
          updateCurrentCompanyData(true);
        } catch (e) {
          console.warn('Aviso guardando nuevo usuario:', e);
        }

        // Limpiar y ocultar formulario
        if (formContainer) formContainer.style.display = 'none';
        if (nameInp) nameInp.value = '';
        if (emailInp) emailInp.value = '';
        if (passInp) passInp.value = '';

        renderAccountUsersTable();

        if (typeof showToast === 'function') {
          showToast(`¡Usuario "${name}" creado exitosamente para ${currentCompany.companyName}!`, 'success');
        }
      });
    }
  }

