  function renderSalesModule() {
    let allSales = currentCompany.businessData.sales || [];

    // Si habia formato antiguo por factura, limpiar
    if (allSales.length > 0 && allSales[0].invoice && !allSales[0].total_vta) {
      allSales = [];
      currentCompany.businessData.sales = [];
      updateCurrentCompanyData();
    }

    const isPDSA = Boolean(currentCompany && (
      currentCompany.id === 'comp_1791651122479_m1xepxt' ||
      (currentCompany.companyName && currentCompany.companyName.toLowerCase().includes('plazoleta'))
    ));

    // Configurar encabezados dinámicos (10 cols para Plazoleta, 15 cols para las demás)
    updateSalesTableHeaders(isPDSA);

    const tbody = document.getElementById('tbody-sales');
    const tfoot = document.getElementById('tfoot-sales');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (tfoot) tfoot.innerHTML = '';

    // Controles del filtro de rango de fechas
    const filterFromInput = document.getElementById('sales-filter-from');
    const filterToInput   = document.getElementById('sales-filter-to');
    const filterBadge     = document.getElementById('sales-filter-active-badge');
    const labelTotalEl    = document.getElementById('kpi-sales-total-label');

    // Estado vacío: mostrar mensaje orientador
    if (allSales.length === 0) {
      if (filterFromInput) { filterFromInput.value = ''; filterFromInput.min = ''; filterFromInput.max = ''; }
      if (filterToInput)   { filterToInput.value = ''; filterToInput.min = ''; filterToInput.max = ''; }
      if (filterBadge)     filterBadge.classList.add('hidden');
      if (labelTotalEl)    labelTotalEl.innerHTML = '<i class="fa-solid fa-cash-register"></i> VENTA TOTAL A LA FECHA';

      tbody.innerHTML = `
        <tr>
          <td colspan="${isPDSA ? 10 : 15}" style="text-align:center; padding:40px 20px; color:#555; font-size:0.88rem;">
            <i class="fa-solid fa-file-arrow-up" style="font-size:2rem; color:#aaa; display:block; margin-bottom:12px;"></i>
            <strong>Sin datos de ventas cargados</strong><br>
            <span style="color:#888; font-size:0.82rem;">
              Descarga la plantilla oficial, complétala con los datos del mes y súbela usando el botón <strong>"Subir Archivo Excel"</strong>.
            </span>
          </td>
        </tr>`;
      // KPIs en cero
      ['kpi-sales-total','kpi-sales-invoices','kpi-sales-avg','kpi-sales-bestday-val'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = id.includes('invoices') ? '0' : '$ 0';
      });
      ['kpi-sales-invoices-sub','kpi-sales-avg-sub','kpi-sales-bestday-date',
       'kpi-sales-lastmonth-val','kpi-sales-lastyear-val',
       'kpi-sales-lastmonth-delta','kpi-sales-lastyear-delta'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = '—';
      });
      return;
    }

    // Mapear la secuencia completa de días calendario rellenando días sin ventas con ceros
    const salesWithMeta = getCompleteSalesWithZeroDays(allSales);

    // Determinar fechas mínimas y máximas disponibles en los datos
    const validISOs = salesWithMeta.map(m => m.iso).filter(Boolean).sort();
    const minAvailableISO = validISOs.length > 0 ? validISOs[0] : '';
    const maxAvailableISO = validISOs.length > 0 ? validISOs[validISOs.length - 1] : '';

    if (filterFromInput && filterToInput) {
      if (minAvailableISO && maxAvailableISO) {
        filterFromInput.min = minAvailableISO;
        filterFromInput.max = maxAvailableISO;
        filterToInput.min   = minAvailableISO;
        filterToInput.max   = maxAvailableISO;
      }
      if (!salesDateFilter.from && minAvailableISO) {
        filterFromInput.value = minAvailableISO;
      } else if (salesDateFilter.from) {
        filterFromInput.value = salesDateFilter.from;
      }
      if (!salesDateFilter.to && maxAvailableISO) {
        filterToInput.value = maxAvailableISO;
      } else if (salesDateFilter.to) {
        filterToInput.value = salesDateFilter.to;
      }
    }

    // Detectar si el filtro está restringiendo las fechas
    const isFilterActive = Boolean(
      (salesDateFilter.from && minAvailableISO && salesDateFilter.from > minAvailableISO) ||
      (salesDateFilter.to && maxAvailableISO && salesDateFilter.to < maxAvailableISO) ||
      (salesDateFilter.from && !minAvailableISO) ||
      (salesDateFilter.to && !maxAvailableISO)
    );

    // Filtrar filas según rango seleccionado
    let filteredMeta = salesWithMeta;
    if (salesDateFilter.from) {
      filteredMeta = filteredMeta.filter(m => !m.iso || m.iso >= salesDateFilter.from);
    }
    if (salesDateFilter.to) {
      filteredMeta = filteredMeta.filter(m => !m.iso || m.iso <= salesDateFilter.to);
    }

    if (filterBadge) {
      if (isFilterActive) {
        filterBadge.classList.remove('hidden');
        filterBadge.innerHTML = `<i class="fa-solid fa-filter"></i> Filtro activo: ${formatShortDate(salesDateFilter.from || minAvailableISO)} al ${formatShortDate(salesDateFilter.to || maxAvailableISO)} (${filteredMeta.length} días)`;
      } else {
        filterBadge.classList.add('hidden');
      }
    }

    if (labelTotalEl) {
      labelTotalEl.innerHTML = `<i class="fa-solid fa-cash-register"></i> ${isFilterActive ? 'VENTA DEL RANGO SELECCIONADO' : 'VENTA TOTAL A LA FECHA'}`;
    }

    const sales = filteredMeta.map(m => m.row);

    // Si después de filtrar no hay datos en el rango
    if (sales.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="${isPDSA ? 10 : 15}" style="text-align:center; padding:35px 20px; color:#555; font-size:0.88rem;">
            <i class="fa-solid fa-calendar-xmark" style="font-size:2rem; color:#f59e0b; display:block; margin-bottom:12px;"></i>
            <strong>No hay ventas registradas en el rango seleccionado</strong><br>
            <span style="color:#888; font-size:0.82rem; margin-top:4px; display:inline-block;">
              Del ${formatShortDate(salesDateFilter.from)} al ${formatShortDate(salesDateFilter.to)}. Puedes ajustar las fechas o hacer clic en "Todo el período".
            </span>
          </td>
        </tr>`;
      ['kpi-sales-total','kpi-sales-invoices','kpi-sales-avg','kpi-sales-bestday-val'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = id.includes('invoices') ? '0' : '$ 0';
      });
      ['kpi-sales-invoices-sub','kpi-sales-avg-sub','kpi-sales-bestday-date',
       'kpi-sales-lastmonth-val','kpi-sales-lastyear-val',
       'kpi-sales-lastmonth-delta','kpi-sales-lastyear-delta'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.textContent = '—';
      });
      return;
    }

    let totAlimentos = 0;
    let totBebidas = 0;
    let totOtros = 0;
    let totCortesias = 0;
    let totDescuentos = 0;
    let totVtaBruta = 0;
    let totImpo = 0;
    let totTotalVta = 0;
    let totPropina = 0;
    let totPax = 0;
    let totCtas = 0;

    sales.forEach(row => {
      const alim = Number(row.alimentos) || 0;
      const beb = Number(row.bebidas) || 0;
      const otr = Number(row.otros) || 0;
      const cort = Number(row.cortesias) || 0;
      const desc = Number(row.descuentos) || 0;
      const vBruta = Number(row.vta_bruta) || (alim + beb + otr);
      const imp = Number(row.impo) || 0;
      const vTotal = Number(row.total_vta) || 0;
      const prop = Number(row.propina) || 0;
      const pax = Math.round(Number(row.no_pax) || 0);
      const ctas = Math.round(Number(row.no_ctas) || 0);
      const promPax = Math.round(Number(row.prom_x_pax) || (pax > 0 ? (vTotal / pax) : 0));
      const promCta = Math.round(Number(row.prom_x_cuenta) || (ctas > 0 ? (vTotal / ctas) : 0));

      totAlimentos += alim;
      totBebidas += beb;
      totOtros += otr;
      totCortesias += cort;
      totDescuentos += desc;
      totVtaBruta += vBruta;
      totImpo += imp;
      totTotalVta += vTotal;
      totPropina += prop;
      totPax += pax;
      totCtas += ctas;

      const isZero = (vTotal === 0);
      const cleanDia = formatSpanishDayName(row.dia, row.fecha);
      const isWeekend = (cleanDia === 'Sábado' || cleanDia === 'Domingo');

      const tr = document.createElement('tr');
      if (isZero) tr.className = 'row-sales-zero';

      // Todas las celdas en cero muestran "0" en negro — no guiones invisibles
      const fmt$    = (v) => v > 0 ? formatMoney(v) : '<span class="cell-zero">$ 0</span>';
      const fmtNeg  = (v) => v > 0 ? '- ' + formatMoney(v) : '<span class="cell-zero">0</span>';

      if (isPDSA) {
        tr.innerHTML = `
          <td class="col-fecha"><strong>${formatShortDate(row.fecha)}</strong></td>
          <td class="col-dia text-center"><span class="badge-day ${isWeekend ? 'weekend' : ''}">${cleanDia}</span></td>
          <td class="text-right">${fmt$(alim)}</td>
          <td class="text-right">${fmt$(beb)}</td>
          <td class="text-right col-pdsa-otros">${fmt$(otr)}</td>
          <td class="text-right col-subtot">${fmt$(vBruta)}</td>
          <td class="text-right col-impo">${fmt$(imp)}</td>
          <td class="text-right col-highlight col-total-vta"><strong>${fmt$(vTotal)}</strong></td>
          <td class="text-right col-propina">${fmt$(prop)}</td>
          <td class="text-right col-neg">${fmtNeg(desc)}</td>
        `;
      } else {
        tr.innerHTML = `
          <td class="col-fecha"><strong>${formatShortDate(row.fecha)}</strong></td>
          <td class="col-dia text-center"><span class="badge-day ${isWeekend ? 'weekend' : ''}">${cleanDia}</span></td>
          <td class="text-right">${fmt$(alim)}</td>
          <td class="text-right">${fmt$(beb)}</td>
          <td class="text-right">${fmt$(otr)}</td>
          <td class="text-right">${fmt$(cort)}</td>
          <td class="text-right col-neg">${fmtNeg(desc)}</td>
          <td class="text-right col-subtot">${fmt$(vBruta)}</td>
          <td class="text-right col-impo">${fmt$(imp)}</td>
          <td class="text-right col-highlight col-total-vta"><strong>${fmt$(vTotal)}</strong></td>
          <td class="text-right col-propina">${fmt$(prop)}</td>
          <td class="text-center">${pax > 0 ? '<strong>' + pax + '</strong>' : '<span class="cell-zero">0</span>'}</td>
          <td class="text-center">${ctas > 0 ? '<strong>' + ctas + '</strong>' : '<span class="cell-zero">0</span>'}</td>
          <td class="text-right">${promPax > 0 ? formatMoney(promPax) : '<span class="cell-zero">$ 0</span>'}</td>
          <td class="text-right">${promCta > 0 ? formatMoney(promCta) : '<span class="cell-zero">$ 0</span>'}</td>
        `;
      }
      tbody.appendChild(tr);
    });

    const avgMonthlyCta = totCtas > 0 ? Math.round(totTotalVta / totCtas) : 0;
    const avgMonthlyPax = totPax > 0 ? Math.round(totTotalVta / totPax) : 0;

    // Fila de totales en el pie de tabla
    if (tfoot) {
      if (isPDSA) {
        tfoot.innerHTML = `
          <tr>
            <td colspan="2"><strong>${isFilterActive ? 'TOTALES DEL RANGO:' : 'TOTALES ACUMULADOS:'}</strong></td>
            <td class="text-right"><strong>${formatMoney(totAlimentos)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totBebidas)}</strong></td>
            <td class="text-right col-pdsa-otros"><strong>${formatMoney(totOtros)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totVtaBruta)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totImpo)}</strong></td>
            <td class="text-right col-highlight total-gold"><strong>${formatMoney(totTotalVta)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totPropina)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totDescuentos)}</strong></td>
          </tr>
        `;
      } else {
        tfoot.innerHTML = `
          <tr>
            <td colspan="2"><strong>${isFilterActive ? 'TOTALES DEL RANGO:' : 'TOTALES ACUMULADOS:'}</strong></td>
            <td class="text-right"><strong>${formatMoney(totAlimentos)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totBebidas)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totOtros)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totCortesias)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totDescuentos)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totVtaBruta)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totImpo)}</strong></td>
            <td class="text-right col-highlight total-gold"><strong>${formatMoney(totTotalVta)}</strong></td>
            <td class="text-right"><strong>${formatMoney(totPropina)}</strong></td>
            <td class="text-center"><strong>${totPax} PAX</strong></td>
            <td class="text-center"><strong>${totCtas} CTAS</strong></td>
            <td class="text-right"><strong>${formatMoney(avgMonthlyPax)}</strong></td>
            <td class="text-right"><strong>${formatMoney(avgMonthlyCta)}</strong></td>
          </tr>
        `;
      }
    }

    // ---- KPI 1: VENTA TOTAL DEL RANGO O A LA FECHA ----
    const elTotal = document.getElementById('kpi-sales-total');
    if (elTotal) elTotal.textContent = formatMoney(totTotalVta);

    // ---- COMPARATIVOS: MISMO LAPSO / RANGO DE DÍAS EXACTO ----
    // Extraer días del mes presentes en la visualización (minDay a maxDay)
    const currentDays = filteredMeta.map(m => m.dayNum).filter(d => d >= 1 && d <= 31);
    const minDay = currentDays.length > 0 ? Math.min(...currentDays) : 1;
    const maxDay = currentDays.length > 0 ? Math.max(...currentDays) : 31;

    const prevPeriodKey = getPreviousPeriod(currentCompany.selectedPeriod);
    const prevYearPeriodKey = getPreviousYearPeriod(currentCompany.selectedPeriod);

    const prevMonthBD = (currentCompany.periods && currentCompany.periods[prevPeriodKey]) || null;
    const prevYearBD  = (currentCompany.periods && currentCompany.periods[prevYearPeriodKey]) || null;

    const prevMonthSales = (prevMonthBD && prevMonthBD.sales && prevMonthBD.sales.length > 0)
      ? prevMonthBD.sales
      : (currentCompany.businessData.prevMonthSales || []);
    const prevYearSales  = (prevYearBD && prevYearBD.sales && prevYearBD.sales.length > 0)
      ? prevYearBD.sales
      : (currentCompany.businessData.prevYearSales  || []);

    // Función auxiliar para obtener el día del mes de una fila
    function getRowDayNum(r, idx) {
      if (r && r.fecha) {
        const p = parseDateToParts(r.fecha);
        if (p && p.day >= 1 && p.day <= 31) return p.day;
      }
      if (r && r.dia) {
        const num = parseInt(r.dia, 10);
        if (!isNaN(num) && num >= 1 && num <= 31) return num;
      }
      return idx + 1;
    }

    // Filtrar mes anterior y año anterior para que coincidan EXACTAMENTE con el mismo lapso (días minDay a maxDay)
    const prevMonthFiltered = prevMonthSales.filter((r, idx) => {
      const d = getRowDayNum(r, idx);
      return d >= minDay && d <= maxDay;
    });

    const prevYearFiltered = prevYearSales.filter((r, idx) => {
      const d = getRowDayNum(r, idx);
      return d >= minDay && d <= maxDay;
    });

    const prevMonthTotal = prevMonthFiltered.reduce((s, r) => s + (Number(r.total_vta) || 0), 0);
    const prevYearTotal  = prevYearFiltered.reduce((s, r) => s + (Number(r.total_vta) || 0), 0);

    // Actualizar etiquetas explicativas de la comparación para total transparencia
    const lapsoTexto = (minDay === maxDay)
      ? `día ${minDay}`
      : `días ${minDay} al ${maxDay}`;

    const labelMonthEl = document.getElementById('kpi-sales-lastmonth-label');
    const labelYearEl  = document.getElementById('kpi-sales-lastyear-label');
    if (labelMonthEl) labelMonthEl.textContent = `Mismo lapso mes ant. (${lapsoTexto}):`;
    if (labelYearEl)  labelYearEl.textContent  = `Mismo lapso año ant. (${lapsoTexto}):`;

    function renderCompKpi(valId, deltaId, prevTotal) {
      const valEl   = document.getElementById(valId);
      const deltaEl = document.getElementById(deltaId);
      if (!valEl || !deltaEl) return;
      if (prevTotal > 0) {
        valEl.textContent = formatMoney(prevTotal);
        const pct = Math.round((totTotalVta - prevTotal) / prevTotal * 100);
        const up  = totTotalVta >= prevTotal;
        deltaEl.innerHTML = `<i class="fa-solid ${up ? 'fa-arrow-trend-up' : 'fa-arrow-trend-down'}"></i> ${up ? '+' : ''}${pct}%`;
        deltaEl.className = `kpi-comp-delta ${up ? 'positive' : 'negative'}`;
      } else {
        valEl.textContent  = 'Sin datos';
        deltaEl.textContent = '';
      }
    }
    renderCompKpi('kpi-sales-lastmonth-val', 'kpi-sales-lastmonth-delta', prevMonthTotal);
    renderCompKpi('kpi-sales-lastyear-val',  'kpi-sales-lastyear-delta',  prevYearTotal);

    // ---- KPI 2: TOTAL FACTURAS EMITIDAS ----
    const elInvoices = document.getElementById('kpi-sales-invoices');
    if (elInvoices) elInvoices.textContent = totCtas.toLocaleString('es-CO');
    const elInvoicesSub = document.getElementById('kpi-sales-invoices-sub');
    if (elInvoicesSub) elInvoicesSub.textContent = `${totPax} PAX acumulados al período`;

    // ---- KPI 3: TICKET PROMEDIO ----
    const elAvg = document.getElementById('kpi-sales-avg');
    if (elAvg) elAvg.textContent = formatMoney(avgMonthlyCta);
    const elAvgSub = document.getElementById('kpi-sales-avg-sub');
    if (elAvgSub) elAvgSub.textContent = totCtas > 0 ? `Basado en ${totCtas} cuentas` : 'Sin datos';

    // ---- KPI 4: DIA DE MAYOR VENTA DENTRO DEL RANGO ----
    let bestRow = null;
    let bestVal = 0;
    sales.forEach(r => {
      const v = Number(r.total_vta) || 0;
      if (v > bestVal) { bestVal = v; bestRow = r; }
    });
    const elBestVal  = document.getElementById('kpi-sales-bestday-val');
    const elBestDate = document.getElementById('kpi-sales-bestday-date');
    if (elBestVal)  elBestVal.textContent  = bestRow ? formatMoney(bestVal) : '$ 0';
    if (elBestDate) elBestDate.textContent = bestRow
      ? `${formatShortDate(bestRow.fecha)} — ${bestRow.dia || ''}`
      : '—';
  }


  // ==========================================================================
  // CONFIGURACIÓN DE NOMBRES DE COLUMNAS DE MEDIOS DE PAGO POR EMPRESA
  // ==========================================================================
  const DEFAULT_PAYMENT_LABELS = {
    efectivo: 'Efectivo',
    tarjetas: 'Tarjetas',
    nequi: 'Nequi',
    daviplata: 'Daviplata',
    qr: 'QR'
  };

  function getCompanyPaymentLabels(comp) {
    const c = comp || currentCompany;
    const custom = (c && c.paymentMethodLabels) ? c.paymentMethodLabels : {};
    return {
      efectivo: (custom.efectivo || DEFAULT_PAYMENT_LABELS.efectivo).trim(),
      tarjetas: (custom.tarjetas || DEFAULT_PAYMENT_LABELS.tarjetas).trim(),
      nequi: (custom.nequi || DEFAULT_PAYMENT_LABELS.nequi).trim(),
      daviplata: (custom.daviplata || DEFAULT_PAYMENT_LABELS.daviplata).trim(),
      qr: (custom.qr || DEFAULT_PAYMENT_LABELS.qr).trim()
    };
  }

  function applyPaymentMethodLabels() {
    const labels = getCompanyPaymentLabels();

    // Actualizar encabezados de la tabla
    const thEf = document.getElementById('th-pm-efectivo');
    if (thEf) thEf.textContent = labels.efectivo;
    const thTar = document.getElementById('th-pm-tarjetas');
    if (thTar) thTar.textContent = labels.tarjetas;
    const thNeq = document.getElementById('th-pm-nequi');
    if (thNeq) thNeq.textContent = labels.nequi;
    const thDav = document.getElementById('th-pm-daviplata');
    if (thDav) thDav.textContent = labels.daviplata;
    const thQr = document.getElementById('th-pm-qr');
    if (thQr) thQr.textContent = labels.qr;

    // Actualizar etiquetas en el modal de editar día
    const lblEf = document.getElementById('lbl-edit-pm-efectivo');
    if (lblEf) lblEf.textContent = labels.efectivo;
    const lblTar = document.getElementById('lbl-edit-pm-tarjetas');
    if (lblTar) lblTar.textContent = labels.tarjetas;
    const lblNeq = document.getElementById('lbl-edit-pm-nequi');
    if (lblNeq) lblNeq.textContent = labels.nequi;
    const lblDav = document.getElementById('lbl-edit-pm-daviplata');
    if (lblDav) lblDav.textContent = labels.daviplata;
    const lblQr = document.getElementById('lbl-edit-pm-qr');
    if (lblQr) lblQr.textContent = labels.qr;
  }

