  function renderCogsModule() {
    const isPDSA = isCompanyPDSA();
    updateCogsTableHeaders(isPDSA);

    const { cogsList: cogs, isAutoCalculated } = getEffectiveCogsData();
    const tbody = document.getElementById('tbody-cogs');
    const tfoot = document.getElementById('tfoot-cogs');
    const lblSubtitle = document.getElementById('lbl-cogs-subtitle');

    if (lblSubtitle) {
      if (isAutoCalculated) {
        lblSubtitle.innerHTML = '<span style="color:#0284c7;font-weight:600;"><i class="fa-solid fa-wand-magic-sparkles"></i> Generado automáticamente:</span> Cruzando las cantidades vendidas con los costos unitarios de recetas extraídos de SoftRestaurant.';
      } else {
        lblSubtitle.textContent = 'Costo directo de producción de los productos, venta neta sin impuesto, costo de venta y utilidad bruta';
      }
    }

    if (!tbody) return;
    tbody.innerHTML = '';
    if (tfoot) tfoot.innerHTML = '';

    const selGrupo = document.getElementById('filter-cogs-grupo');
    const selProducto = document.getElementById('filter-cogs-producto');
    const countBadge = document.getElementById('filter-cogs-count');

    // Manejo de estado vacío
    if (!cogs || cogs.length === 0) {
      if (selGrupo) selGrupo.innerHTML = '<option value="ALL">-- Todos los Grupos --</option>';
      if (selProducto) selProducto.innerHTML = '<option value="ALL">-- Todos los Productos --</option>';
      if (countBadge) countBadge.textContent = '0 productos';
      tbody.innerHTML = `
        <tr>
          <td colspan="9" style="text-align:center; padding:36px 20px; color:#64748b; font-size:0.88rem;">
            <i class="fa-solid fa-calculator" style="font-size:2rem; color:#cbd5e1; display:block; margin-bottom:10px;"></i>
            <strong>No hay registros de costos de ventas ni productos cargados</strong><br>
            <span style="color:#94a3b8; font-size:0.82rem;">Sincroniza tus turnos con el conector de SoftRestaurant o sube la plantilla oficial de Costos de Ventas.</span>
          </td>
        </tr>`;
      updateCogsKPIs(0, 0, 0, 0);
      return;
    }

    // 1. NIVEL 1: Grupos únicos
    const uniqueGrupos = [...new Set(cogs.map(r => (r.grupo || r.category || '').trim()).filter(Boolean))].sort((a,b) => a.localeCompare(b, 'es'));
    if (selGrupo) {
      const currentGrupo = filterCogsState.grupo;
      selGrupo.innerHTML = '<option value="ALL">-- Todos los Grupos --</option>';
      uniqueGrupos.forEach(g => {
        const opt = document.createElement('option');
        opt.value = g;
        opt.textContent = g;
        if (g.toLowerCase() === currentGrupo.toLowerCase()) opt.selected = true;
        selGrupo.appendChild(opt);
      });
      if (currentGrupo !== 'ALL' && !uniqueGrupos.some(g => g.toLowerCase() === currentGrupo.toLowerCase())) {
        filterCogsState.grupo = 'ALL';
        selGrupo.value = 'ALL';
      }
    }

    // Registros filtrados por Grupo
    const recordsL1 = (filterCogsState.grupo === 'ALL')
      ? cogs
      : cogs.filter(r => (r.grupo || r.category || '').trim().toLowerCase() === filterCogsState.grupo.toLowerCase());

    // 2. NIVEL 2: Productos disponibles dentro del Grupo seleccionado
    const uniqueProductos = [...new Set(recordsL1.map(r => (r.producto || r.product || '').trim()).filter(Boolean))].sort((a,b) => a.localeCompare(b, 'es'));

    if (selProducto) {
      const currentProducto = filterCogsState.producto;
      selProducto.innerHTML = '<option value="ALL">-- Todos los Productos --</option>';
      uniqueProductos.forEach(p => {
        const opt = document.createElement('option');
        opt.value = p;
        opt.textContent = p;
        if (p.toLowerCase() === currentProducto.toLowerCase()) opt.selected = true;
        selProducto.appendChild(opt);
      });
      if (currentProducto !== 'ALL' && !uniqueProductos.some(p => p.toLowerCase() === currentProducto.toLowerCase())) {
        filterCogsState.producto = 'ALL';
        selProducto.value = 'ALL';
      }
    }

    // Registros finales filtrados
    const filtered = (filterCogsState.producto === 'ALL')
      ? recordsL1
      : recordsL1.filter(r => (r.producto || r.product || '').trim().toLowerCase() === filterCogsState.producto.toLowerCase());

    if (countBadge) {
      countBadge.textContent = `Mostrando ${filtered.length} de ${cogs.length} productos`;
      countBadge.style.color = (filtered.length === cogs.length) ? '#334155' : '#0369a1';
    }

    if (filtered.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="9" style="text-align:center; padding:36px 20px; color:#64748b; font-size:0.88rem;">
            <i class="fa-solid fa-filter-circle-xmark" style="font-size:2rem; color:#cbd5e1; display:block; margin-bottom:10px;"></i>
            <strong>No se encontraron productos para los filtros seleccionados</strong><br>
            <span style="color:#94a3b8; font-size:0.82rem;">Prueba cambiando el grupo o el producto, o haz clic en "Limpiar Filtros".</span>
          </td>
        </tr>`;
      updateCogsKPIs(0, 0, 0, 0);
      return;
    }

    const fmt$ = (v) => {
      const n = Number(v) || 0;
      return n > 0 ? formatMoney(n) : '<span class="cell-zero">$ 0</span>';
    };

    let sumVtaTotalSinImpo = 0;
    let sumVentaCosto = 0;
    let sumUtilidad = 0;
    let sumCantidad = 0;

    filtered.forEach(item => {
      const prod = item.producto || item.product || '—';
      const grupo = item.grupo || item.category || '—';
      const precio = Number(item.precio !== undefined ? item.precio : (item.salePrice !== undefined ? item.salePrice : item.precio_venta)) || 0;
      const cant = Number(item.cant !== undefined ? item.cant : (item.cantidad !== undefined ? item.cantidad : 0)) || 0;
      const vtaTotalSinImpo = Number(item.vta_total_sin_impo !== undefined ? item.vta_total_sin_impo : item.venta_total_sin_impo) || 0;
      const costo = Number(item.costo !== undefined ? item.costo : item.rawCost) || 0;
      const ventaCosto = Number(item.venta_costo !== undefined ? item.venta_costo : (costo * cant)) || 0;
      const utilidad = Number(item.utilidad !== undefined ? item.utilidad : (vtaTotalSinImpo - ventaCosto)) || 0;

      let pctCostoVal = item.pct_costo;
      let pctCosto = 0;
      if (typeof pctCostoVal === 'number' && !isNaN(pctCostoVal)) {
        pctCosto = pctCostoVal <= 1 && pctCostoVal > 0 ? pctCostoVal * 100 : pctCostoVal;
      } else if (vtaTotalSinImpo > 0) {
        pctCosto = (ventaCosto / vtaTotalSinImpo) * 100;
      }

      sumVtaTotalSinImpo += vtaTotalSinImpo;
      sumVentaCosto += ventaCosto;
      sumUtilidad += utilidad;
      sumCantidad += cant;

      const tr = document.createElement('tr');
      if (vtaTotalSinImpo === 0 && ventaCosto === 0) tr.className = 'row-sales-zero';

      if (isPDSA) {
        tr.innerHTML = `
          <td><span class="badge-tag">${grupo}</span></td>
          <td><strong><i class="fa-solid fa-utensils" style="color:var(--accent-gold);margin-right:6px;"></i> ${prod}</strong></td>
          <td class="text-center"><strong>${cant.toLocaleString('es-CO')}</strong></td>
          <td class="text-right">${fmt$(precio)}</td>
          <td class="text-right col-highlight"><strong>${fmt$(vtaTotalSinImpo)}</strong></td>
          <td class="text-right">${fmt$(costo)}</td>
          <td class="text-right col-highlight"><strong>${fmt$(ventaCosto)}</strong></td>
          <td class="text-right col-highlight ${utilidad >= 0 ? 'positive' : 'warning'}"><strong>${fmt$(utilidad)}</strong></td>
          <td class="text-center"><span class="badge-tag ${pctCosto > 40 ? 'status-pending' : ''}">${Math.round(pctCosto)}%</span></td>
        `;
      } else {
        tr.innerHTML = `
          <td><strong><i class="fa-solid fa-utensils" style="color:var(--accent-gold);margin-right:6px;"></i> ${prod}</strong></td>
          <td><span class="badge-tag">${grupo}</span></td>
          <td class="text-right">${fmt$(precio)}</td>
          <td class="text-center"><strong>${cant.toLocaleString('es-CO')}</strong></td>
          <td class="text-right col-highlight"><strong>${fmt$(vtaTotalSinImpo)}</strong></td>
          <td class="text-right">${fmt$(costo)}</td>
          <td class="text-right col-highlight"><strong>${fmt$(ventaCosto)}</strong></td>
          <td class="text-right col-highlight ${utilidad >= 0 ? 'positive' : 'warning'}"><strong>${fmt$(utilidad)}</strong></td>
          <td class="text-center"><span class="badge-tag ${pctCosto > 40 ? 'status-pending' : ''}">${Math.round(pctCosto)}%</span></td>
        `;
      }
      tbody.appendChild(tr);
    });

    const overallPctCosto = sumVtaTotalSinImpo > 0 ? (sumVentaCosto / sumVtaTotalSinImpo) * 100 : 0;

    // 4. Totales en tfoot
    if (tfoot) {
      if (isPDSA) {
        tfoot.innerHTML = `
          <tr>
            <td colspan="2"><strong>TOTALES ACUMULADOS (${filtered.length} productos):</strong></td>
            <td class="text-center"><strong>${sumCantidad.toLocaleString('es-CO')}</strong></td>
            <td class="text-right"><strong>—</strong></td>
            <td class="text-right col-highlight total-gold"><strong>${formatMoney(sumVtaTotalSinImpo)}</strong></td>
            <td class="text-right"><strong>—</strong></td>
            <td class="text-right col-highlight total-gold"><strong>${formatMoney(sumVentaCosto)}</strong></td>
            <td class="text-right col-highlight total-gold"><strong>${formatMoney(sumUtilidad)}</strong></td>
            <td class="text-center"><strong>${Math.round(overallPctCosto)}%</strong></td>
          </tr>`;
      } else {
        tfoot.innerHTML = `
          <tr>
            <td colspan="2"><strong>TOTALES ACUMULADOS (${filtered.length} productos):</strong></td>
            <td class="text-right"><strong>—</strong></td>
            <td class="text-center"><strong>${sumCantidad.toLocaleString('es-CO')}</strong></td>
            <td class="text-right col-highlight total-gold"><strong>${formatMoney(sumVtaTotalSinImpo)}</strong></td>
            <td class="text-right"><strong>—</strong></td>
            <td class="text-right col-highlight total-gold"><strong>${formatMoney(sumVentaCosto)}</strong></td>
            <td class="text-right col-highlight total-gold"><strong>${formatMoney(sumUtilidad)}</strong></td>
            <td class="text-center"><strong>${Math.round(overallPctCosto)}%</strong></td>
          </tr>`;
      }
    }

    // 5. Actualizar KPIs superiores
    updateCogsKPIs(sumVtaTotalSinImpo, sumVentaCosto, sumUtilidad, overallPctCosto);
  }

  function updateCogsKPIs(ventasNetas, costoTotal, utilidadBruta, pctCosto) {
    const elVentas = document.getElementById('kpi-cogs-ventas');
    const elVentasSub = document.getElementById('kpi-cogs-ventas-sub');
    const elCosto = document.getElementById('kpi-cogs-costo');
    const elCostoSub = document.getElementById('kpi-cogs-costo-sub');
    const elUtilidad = document.getElementById('kpi-cogs-utilidad');
    const elUtilidadSub = document.getElementById('kpi-cogs-utilidad-sub');
    const elPct = document.getElementById('kpi-cogs-pct');
    const elPctSub = document.getElementById('kpi-cogs-pct-sub');

    if (elVentas) elVentas.textContent = formatMoney(ventasNetas);
    if (elVentasSub) elVentasSub.textContent = ventasNetas > 0 ? 'Ingresos netos del período' : 'Sin ventas registradas';

    if (elCosto) elCosto.textContent = formatMoney(costoTotal);
    if (elCostoSub) elCostoSub.textContent = costoTotal > 0 ? `${Math.round(pctCosto)}% sobre venta neta` : 'Costo de mercancía';

    if (elUtilidad) elUtilidad.textContent = formatMoney(utilidadBruta);
    if (elUtilidadSub) {
      const margenUtilidad = ventasNetas > 0 ? Math.round((utilidadBruta / ventasNetas) * 100) : 0;
      elUtilidadSub.textContent = utilidadBruta > 0 ? `Margen bruto: ${margenUtilidad}%` : 'Margen bruto en pesos';
    }

    if (elPct) elPct.textContent = `${Math.round(pctCosto)}%`;
    if (elPctSub) {
      const taxRegime = (currentCompany && currentCompany.taxRegime) ? currentCompany.taxRegime : 'impoconsumo_8';
      if (taxRegime === 'no_responsable_0' || taxRegime === 'impoconsumo_8_net') {
        elPctSub.textContent = pctCosto > 0 ? 'Costo global de ventas' : 'Sobre venta 100% neta';
      } else if (taxRegime === 'iva_19') {
        elPctSub.textContent = pctCosto > 0 ? 'Costo global de ventas' : 'Sobre venta sin IVA (19%)';
      } else {
        elPctSub.textContent = pctCosto > 0 ? 'Costo global de ventas' : 'Sobre venta sin impoconsumo (8%)';
      }
    }
  }

  // Helper global para obtener el total de ventas del período consolidando los módulos de ingresos
  function getMonthlySalesTotal() {
    if (!currentCompany || !currentCompany.businessData) return 0;
    const bd = currentCompany.businessData;

    // 1. Módulo 1: Ventas Diarias
    if (Array.isArray(bd.sales) && bd.sales.length > 0) {
      const sum = bd.sales.reduce((acc, r) => acc + (Number(r.total_vta) || 0), 0);
      if (sum > 0) return sum;
    }

    // 2. Módulo 2: Formas de Pago
    if (Array.isArray(bd.paymentMethods) && bd.paymentMethods.length > 0) {
      const sum = bd.paymentMethods.reduce((acc, r) => acc + (Number(r.venta_dia) || 0), 0);
      if (sum > 0) return sum;
    }

    // 3. Módulo 4: Productos Mensuales Vendidos
    if (Array.isArray(bd.monthlyProducts) && bd.monthlyProducts.length > 0) {
      const sum = bd.monthlyProducts.reduce((acc, r) => {
        const cant = Number(r.cantidad !== undefined ? r.cantidad : r.cant) || 0;
        const precio = Number(r.precio !== undefined ? r.precio : r.price) || 0;
        const tot = Number(r.total) || (cant * precio);
        return acc + tot;
      }, 0);
      if (sum > 0) return sum;
    }

    // 4. Módulo 10: Costos de Ventas (COGS)
    if (Array.isArray(bd.cogs) && bd.cogs.length > 0) {
      const sum = bd.cogs.reduce((acc, r) => acc + (Number(r.vta_total_sin_impo !== undefined ? r.vta_total_sin_impo : r.venta_total_sin_impo) || 0), 0);
      if (sum > 0) return sum;
    }

    // 5. Módulo 8: Ventas x Vendedor (tips)
    if (Array.isArray(bd.tips) && bd.tips.length > 0) {
      const sum = bd.tips.reduce((acc, r) => acc + (Number(r.venta_total !== undefined ? r.venta_total : (r.amount ? r.amount * 10 : 0)) || 0), 0);
      if (sum > 0) return sum;
    }

    return 0;
  }

  function updatePurchaseCostsTableHeaders(isPDSA) {
    const table = document.getElementById('table-purchase-costs');
    if (!table) return;

    if (isPDSA) {
      table.classList.add('table-purchase-costs-pdsa');
    } else {
      table.classList.remove('table-purchase-costs-pdsa');
    }

    const colgroup = table.querySelector('colgroup');
    const thead = table.querySelector('thead');
    if (!colgroup || !thead) return;

    if (isPDSA) {
      // Plazoleta de San Antonio: replica la plantilla de Compras x Proveedor (FECHA | DIA | FACTURA | PROVEEDOR | TOTAL) + Análisis (% S/VENTAS | % S/COMPRAS | IMPACTO)
      colgroup.innerHTML = `
        <col style="width:110px; min-width:95px">
        <col style="width:95px; min-width:85px">
        <col style="width:130px; min-width:110px">
        <col style="min-width:240px">
        <col style="width:170px; min-width:140px">
        <col style="width:140px; min-width:120px">
        <col style="width:140px; min-width:120px">
        <col style="width:130px; min-width:110px">
      `;
      thead.innerHTML = `
        <tr class="thead-group-row">
          <th colspan="2" class="th-group th-group-date"><i class="fa-regular fa-calendar"></i> Fecha y Día</th>
          <th colspan="2" class="th-group th-group-service"><i class="fa-solid fa-receipt"></i> Factura y Proveedor</th>
          <th colspan="1" class="th-group th-group-totals"><i class="fa-solid fa-dollar-sign"></i> Monto Facturado</th>
          <th colspan="3" class="th-group th-group-audit"><i class="fa-solid fa-chart-pie"></i> Análisis Sobre Ventas y Compras</th>
        </tr>
        <tr class="thead-detail-row">
          <th class="col-fecha text-center">Fecha</th>
          <th class="text-center col-dia">Día</th>
          <th class="text-center">Factura</th>
          <th style="text-align:left;">Proveedor</th>
          <th class="text-right col-highlight">Total Compra ($)</th>
          <th class="text-center">% S/Ventas</th>
          <th class="text-center">% S/Compras</th>
          <th class="text-center">Impacto</th>
        </tr>
      `;
    } else {
      colgroup.innerHTML = `
        <col style="width:110px; min-width:90px">
        <col style="width:130px; min-width:105px">
        <col style="width:130px; min-width:110px">
        <col style="min-width:240px">
        <col style="width:170px; min-width:140px">
        <col style="width:145px; min-width:125px">
        <col style="width:145px; min-width:125px">
        <col style="width:140px; min-width:120px">
      `;
      thead.innerHTML = `
        <tr class="thead-group-row">
          <th colspan="3" class="th-group th-group-date"><i class="fa-solid fa-file-invoice"></i> Comprobante y Fecha</th>
          <th colspan="2" class="th-group th-group-totals"><i class="fa-solid fa-truck"></i> Proveedor y Monto Facturado</th>
          <th colspan="3" class="th-group th-group-audit"><i class="fa-solid fa-chart-pie"></i> Análisis Sobre Ventas y Compras</th>
        </tr>
        <tr class="thead-detail-row">
          <th class="text-center">Folio</th>
          <th class="text-center">Factura</th>
          <th class="col-fecha text-center">Fecha</th>
          <th style="text-align:left;">Proveedor</th>
          <th class="text-right col-highlight">Total Compra ($)</th>
          <th class="text-center">% S/Ventas</th>
          <th class="text-center">% S/Compras</th>
          <th class="text-center">Impacto</th>
        </tr>
      `;
    }
  }

  // 11. Costos de Compras (Toma las compras a proveedores y calcula el costo sobre las ventas mensuales)
  function renderPurchaseCostsModule() {
    const isPDSA = isCompanyPDSA();
    updatePurchaseCostsTableHeaders(isPDSA);

    const bd = (currentCompany && currentCompany.businessData) ? currentCompany.businessData : {};
    const suppliers = bd.suppliers || [];
    const purchaseCosts = bd.purchaseCosts || [];
    // Toma la misma información que sale en compras x proveedor
    const purchases = (suppliers.length > 0) ? suppliers : purchaseCosts;

    const tbody = document.getElementById('tbody-purchase-costs');
    const tfoot = document.getElementById('tfoot-purchase-costs');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (tfoot) tfoot.innerHTML = '';

    const selProv = document.getElementById('filter-cost-compras-proveedor');
    const selFecha = document.getElementById('filter-cost-compras-fecha');
    const countBadge = document.getElementById('filter-cost-compras-count');

    // 1. Extraer proveedores y fechas únicas de compras
    const uniqueProvs = [...new Set(purchases.map(s => (s.proveedor || s.name || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'es'));
    const uniqueFechas = [...new Set(purchases.map(s => (s.fecha || '').trim()).filter(Boolean))].sort();

    // 2. Poblar selector de Proveedores
    if (selProv) {
      const currentVal = filterPurchaseCostsState.proveedor;
      selProv.innerHTML = '<option value="ALL">-- Todos los Proveedores --</option>';
      uniqueProvs.forEach(p => {
        const opt = document.createElement('option');
        opt.value = p;
        opt.textContent = p;
        if (p.toLowerCase() === currentVal.toLowerCase()) opt.selected = true;
        selProv.appendChild(opt);
      });
      if (currentVal !== 'ALL' && !uniqueProvs.some(p => p.toLowerCase() === currentVal.toLowerCase())) {
        filterPurchaseCostsState.proveedor = 'ALL';
        selProv.value = 'ALL';
      }
    }

    // 3. Poblar selector de Fechas
    if (selFecha) {
      const currentVal = filterPurchaseCostsState.fecha;
      selFecha.innerHTML = '<option value="ALL">-- Todas las Fechas --</option>';
      uniqueFechas.forEach(f => {
        const opt = document.createElement('option');
        opt.value = f;
        opt.textContent = formatShortDate(f);
        if (f === currentVal) opt.selected = true;
        selFecha.appendChild(opt);
      });
      if (currentVal !== 'ALL' && !uniqueFechas.includes(currentVal)) {
        filterPurchaseCostsState.fecha = 'ALL';
        selFecha.value = 'ALL';
      }
    }

    // Estado cuando no hay compras cargadas
    if (purchases.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" style="text-align:center; padding:40px 20px; color:#555; font-size:0.88rem;">
            <i class="fa-solid fa-file-invoice-dollar" style="font-size:2rem; color:#aaa; display:block; margin-bottom:12px;"></i>
            <strong>Sin datos de compras para análisis de costos</strong><br>
            <span style="color:#888; font-size:0.82rem;">
              Carga las facturas en el módulo de <strong>Compras x Proveedor</strong> o sube la plantilla oficial de <strong>Costos de Compras</strong>.
            </span>
          </td>
        </tr>`;
      if (countBadge) countBadge.textContent = '0 comprobantes';
      updatePurchaseCostsKPIs(0, 0, 0, 0);
      return;
    }

    // 4. Calcular métricas globales financieras (Matriz oficial D:\INIS)
    const totalComprasMesGlobal = purchases.reduce((acc, r) => acc + (Number(r.total) || 0), 0);
    const totalVentasMes = getMonthlySalesTotal();
    const costoComprasPct = totalVentasMes > 0 ? (totalComprasMesGlobal / totalVentasMes) * 100 : 0;

    // 5. Filtrar compras según los filtros activos
    const filtered = purchases.filter(s => {
      const sProv = (s.proveedor || s.name || '').trim().toLowerCase();
      const sFecha = (s.fecha || '').trim();
      const matchProv = (filterPurchaseCostsState.proveedor === 'ALL') || (sProv === filterPurchaseCostsState.proveedor.toLowerCase());
      const matchFecha = (filterPurchaseCostsState.fecha === 'ALL') || (sFecha === filterPurchaseCostsState.fecha);
      return matchProv && matchFecha;
    });

    if (countBadge) {
      countBadge.textContent = `Mostrando ${filtered.length} de ${purchases.length} comprobantes`;
      countBadge.style.color = (filtered.length === purchases.length) ? '#334155' : '#0369a1';
    }

    if (filtered.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" style="text-align:center; padding:36px 20px; color:#64748b; font-size:0.88rem;">
            <i class="fa-solid fa-filter-circle-xmark" style="font-size:2rem; color:#cbd5e1; display:block; margin-bottom:10px;"></i>
            <strong>No se encontraron comprobantes para los filtros seleccionados</strong><br>
            <span style="color:#94a3b8; font-size:0.82rem;">Prueba cambiando el proveedor o la fecha, o haz clic en "Limpiar Filtros".</span>
          </td>
        </tr>`;
      updatePurchaseCostsKPIs(totalComprasMesGlobal, totalVentasMes, costoComprasPct, purchases.length);
      return;
    }

    // 6. Renderizar filas
    const fmt$ = (v) => { const n = Number(v) || 0; return n > 0 ? formatMoney(n) : '<span class="cell-zero">$ 0</span>'; };
    let sumFilteredTotal = 0;

    filtered.forEach(row => {
      const folio = (row.folio !== undefined && row.folio !== null && row.folio !== '') ? row.folio : '—';
      const factura = (row.factura !== undefined && row.factura !== null && row.factura !== '') ? row.factura : '—';
      const fecha = row.fecha || '';
      const proveedor = row.proveedor || row.name || 'Sin Proveedor';
      const total = Number(row.total) || 0;
      sumFilteredTotal += total;

      const pctVentas = totalVentasMes > 0 ? (total / totalVentasMes) * 100 : 0;
      const pctCompras = totalComprasMesGlobal > 0 ? (total / totalComprasMesGlobal) * 100 : 0;

      // Badge de Impacto según el peso sobre las compras totales
      let impactBadge = '<span class="badge-tag">Bajo</span>';
      if (pctCompras >= 10) {
        impactBadge = '<span class="badge-tag status-pending">Alto</span>';
      } else if (pctCompras >= 4) {
        impactBadge = '<span class="badge-tag status-active">Medio</span>';
      }

      const tr = document.createElement('tr');
      if (total === 0) tr.className = 'row-sales-zero';

      if (isPDSA) {
        const cleanDia = formatSpanishDayName(row.dia, fecha);
        const isWk = (cleanDia === 'Sábado' || cleanDia === 'Domingo');
        tr.innerHTML = `
          <td class="col-fecha text-center"><strong>${formatShortDate(fecha)}</strong></td>
          <td class="text-center col-dia"><span class="badge-day ${isWk ? 'weekend' : ''}">${cleanDia}</span></td>
          <td class="text-center">${factura !== '—' && factura !== '' ? `<strong>${factura}</strong>` : '<span style="color:#94a3b8;">—</span>'}</td>
          <td><strong><i class="fa-solid fa-truck" style="color:var(--accent-gold);margin-right:6px;"></i> ${proveedor}</strong></td>
          <td class="text-right col-highlight"><strong>${fmt$(total)}</strong></td>
          <td class="text-center"><strong>${totalVentasMes > 0 ? Math.round(pctVentas) + '%' : '—'}</strong></td>
          <td class="text-center"><strong>${totalComprasMesGlobal > 0 ? Math.round(pctCompras) + '%' : '—'}</strong></td>
          <td class="text-center">${impactBadge}</td>
        `;
      } else {
        tr.innerHTML = `
          <td class="text-center"><code>${folio}</code></td>
          <td class="text-center">${factura !== '—' && factura !== '' ? `<strong>${factura}</strong>` : '<span style="color:#94a3b8;">—</span>'}</td>
          <td class="col-fecha text-center"><strong>${formatShortDate(fecha)}</strong></td>
          <td><strong><i class="fa-solid fa-truck" style="color:var(--accent-gold);margin-right:6px;"></i> ${proveedor}</strong></td>
          <td class="text-right col-highlight"><strong>${fmt$(total)}</strong></td>
          <td class="text-center"><strong>${totalVentasMes > 0 ? Math.round(pctVentas) + '%' : '—'}</strong></td>
          <td class="text-center"><strong>${totalComprasMesGlobal > 0 ? Math.round(pctCompras) + '%' : '—'}</strong></td>
          <td class="text-center">${impactBadge}</td>
        `;
      }
      tbody.appendChild(tr);
    });

    // 7. Totales en tfoot
    const filteredPctVentas = totalVentasMes > 0 ? (sumFilteredTotal / totalVentasMes) * 100 : 0;
    const filteredPctCompras = totalComprasMesGlobal > 0 ? (sumFilteredTotal / totalComprasMesGlobal) * 100 : 0;

    if (tfoot) {
      tfoot.innerHTML = `
        <tr>
          <td colspan="4"><strong>TOTALES ACUMULADOS (${filtered.length} comprobantes):</strong></td>
          <td class="text-right col-highlight total-gold"><strong>${formatMoney(sumFilteredTotal)}</strong></td>
          <td class="text-center total-gold"><strong>${totalVentasMes > 0 ? Math.round(filteredPctVentas) + '%' : '—'}</strong></td>
          <td class="text-center total-gold"><strong>${totalComprasMesGlobal > 0 ? Math.round(filteredPctCompras) + '%' : '—'}</strong></td>
          <td class="text-center"><strong>${costoComprasPct >= 38 ? '⚠️ ALERTA' : '✓ ÓPTIMO'}</strong></td>
        </tr>`;
    }

    // 8. Actualizar KPIs superiores
    updatePurchaseCostsKPIs(totalComprasMesGlobal, totalVentasMes, costoComprasPct, purchases.length);
  }

  function updatePurchaseCostsKPIs(totalCompras, totalVentas, pctCosto, numFacturas) {
    const elTotal = document.getElementById('kpi-cost-compras-total');
    const elTotalSub = document.getElementById('kpi-cost-compras-total-sub');
    const elVentas = document.getElementById('kpi-cost-compras-ventas');
    const elVentasSub = document.getElementById('kpi-cost-compras-ventas-sub');
    const elPct = document.getElementById('kpi-cost-compras-pct');
    const elPctSub = document.getElementById('kpi-cost-compras-pct-sub');
    const elStatus = document.getElementById('kpi-cost-compras-status');
    const elStatusSub = document.getElementById('kpi-cost-compras-status-sub');

    if (elTotal) elTotal.textContent = formatMoney(totalCompras);
    if (elTotalSub) elTotalSub.textContent = numFacturas > 0 ? `${numFacturas} comprobantes registrados` : 'Suma facturas de proveedores';

    if (elVentas) elVentas.textContent = formatMoney(totalVentas);
    if (elVentasSub) elVentasSub.textContent = totalVentas > 0 ? 'Ventas netas del período' : 'Base de ingresos del mes';

    if (elPct) elPct.textContent = `${Math.round(pctCosto)}%`;
    if (elPctSub) elPctSub.textContent = totalVentas > 0 ? `${formatMoney(totalCompras)} / ${formatMoney(totalVentas)}` : 'Costo compras / Ventas mes';

    if (elStatus) {
      if (totalVentas > 0 && totalCompras > 0) {
        if (pctCosto >= 38) {
          elStatus.innerHTML = '<span style="color:#dc2626; font-weight:700;"><i class="fa-solid fa-triangle-exclamation"></i> COSTO ALTO</span>';
          if (elStatusSub) elStatusSub.textContent = 'Supera el umbral objetivo del 38%';
        } else {
          elStatus.innerHTML = '<span style="color:#16a34a; font-weight:700;"><i class="fa-solid fa-circle-check"></i> COSTO ÓPTIMO</span>';
          if (elStatusSub) elStatusSub.textContent = 'Dentro del umbral objetivo (< 38%)';
        }
      } else {
        elStatus.textContent = '—';
        if (elStatusSub) elStatusSub.textContent = 'Umbral objetivo < 38%';
      }
    }
  }

  // 12. Comparativo de Ventas Mensuales e Interanual
  function renderMonthlyComparisonModule() {
    const tbody = document.getElementById('tbody-monthly-comparison');
    if (!tbody) return;
    tbody.innerHTML = '';

    // Obtener todos los períodos con datos de la empresa activa
    const allSummaries = getAllPeriodsSummary(currentCompany);

    if (allSummaries.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="text-center" style="padding: 32px; color: #64748b;">
            <i class="fa-solid fa-calendar-xmark" style="font-size: 1.6rem; color: #cbd5e1; margin-bottom: 8px; display: block;"></i>
            <strong>No hay meses con información reportada aún.</strong><br>
            Selecciona un mes en el selector de período y sube tus archivos de ventas o costos para comenzar a generar los informes comparativos.
          </td>
        </tr>
      `;
      const elAvg = document.getElementById('kpi-comp-avg-sales');
      const elBest = document.getElementById('kpi-comp-best-month');
      const elGrowth = document.getElementById('kpi-comp-avg-growth');
      const elMargin = document.getElementById('kpi-comp-avg-margin');
      if (elAvg) elAvg.textContent = '$ 0';
      if (elBest) elBest.textContent = '—';
      if (elGrowth) elGrowth.textContent = '—';
      if (elMargin) elMargin.textContent = '—';
    } else {
      // Orden cronológico inverso (meses más recientes arriba)
      const displaySummaries = [...allSummaries].reverse();

      displaySummaries.forEach(s => {
        const isCurrentActive = s.periodKey === currentCompany.selectedPeriod;
        const growthUp = (s.growthPct !== null && s.growthPct >= 0);
        const growthColor = (s.growthPct === null) ? 'text-muted' : (growthUp ? 'positive' : 'negative');
        const growthIcon = (s.growthPct === null) ? '' : (growthUp ? '<i class="fa-solid fa-arrow-trend-up"></i> ' : '<i class="fa-solid fa-arrow-trend-down"></i> ');
        const activeBadge = isCurrentActive ? ' <span class="status-pill status-completed" style="font-size: 0.72rem; padding: 2px 8px; margin-left: 6px;"><i class="fa-solid fa-eye"></i> Período Activo</span>' : '';

        const tr = document.createElement('tr');
        if (isCurrentActive) tr.style.background = 'rgba(212, 175, 55, 0.08)';

        tr.innerHTML = `
          <td>
            <strong><i class="fa-regular fa-calendar-check text-gold"></i> ${s.label}</strong>
            ${activeBadge}
          </td>
          <td class="text-right"><strong>${formatMoney(s.sales)}</strong></td>
          <td class="text-right">${formatMoney(s.cogs)}</td>
          <td class="text-right">${formatMoney(s.opex)}</td>
          <td class="text-right ${s.net >= 0 ? 'positive' : 'negative'}"><strong>${formatMoney(s.net)}</strong></td>
          <td class="text-center"><span class="status-pill ${s.margin >= 15 ? 'status-completed' : (s.margin > 0 ? 'status-pending' : 'status-failed')}">${s.margin}%</span></td>
          <td class="text-center ${growthColor}"><strong>${growthIcon}${s.growthLabel}</strong></td>
          <td>
            <div class="share-cell">
              <div class="share-bar-bg">
                <div class="share-bar-fill" style="width: ${s.barWidth}%;"></div>
              </div>
              <span class="share-percent">${s.barWidth}%</span>
            </div>
          </td>
        `;
        tbody.appendChild(tr);
      });

      // Calcular KPIs de resumen mensual
      const totSales = allSummaries.reduce((sum, s) => sum + s.sales, 0);
      const avgSales = Math.round(totSales / allSummaries.length);
      const bestMonth = [...allSummaries].sort((a, b) => b.sales - a.sales)[0];

      const growthItems = allSummaries.filter(s => s.growthPct !== null);
      let avgGrowth = 0;
      if (growthItems.length > 0) {
        avgGrowth = Math.round(growthItems.reduce((sum, s) => sum + s.growthPct, 0) / growthItems.length);
      }

      const avgMargin = Math.round(allSummaries.reduce((sum, s) => sum + s.margin, 0) / allSummaries.length);

      const elAvg = document.getElementById('kpi-comp-avg-sales');
      const elAvgSub = document.getElementById('kpi-comp-avg-sub');
      const elBest = document.getElementById('kpi-comp-best-month');
      const elBestSub = document.getElementById('kpi-comp-best-sub');
      const elGrowth = document.getElementById('kpi-comp-avg-growth');
      const elGrowthSub = document.getElementById('kpi-comp-avg-growth-sub');
      const elMargin = document.getElementById('kpi-comp-avg-margin');
      const elMarginSub = document.getElementById('kpi-comp-avg-margin-sub');

      if (elAvg) elAvg.textContent = formatMoney(avgSales);
      if (elAvgSub) elAvgSub.textContent = `${allSummaries.length} ${allSummaries.length === 1 ? 'mes reportado' : 'meses consolidados'}`;

      if (elBest && bestMonth) {
        elBest.textContent = bestMonth.label;
        if (elBestSub) elBestSub.textContent = `${formatMoney(bestMonth.sales)} facturados`;
      }

      if (elGrowth) {
        if (growthItems.length > 0) {
          elGrowth.innerHTML = `<i class="fa-solid ${avgGrowth >= 0 ? 'fa-arrow-trend-up' : 'fa-arrow-trend-down'}"></i> ${avgGrowth >= 0 ? '+' : ''}${avgGrowth}%`;
          elGrowth.className = `kpi-val ${avgGrowth >= 0 ? 'positive' : 'negative'}`;
          if (elGrowthSub) elGrowthSub.textContent = 'Variación promedio mes a mes';
        } else {
          elGrowth.textContent = 'Período Base';
          if (elGrowthSub) elGrowthSub.textContent = 'Carga un 2° mes para comparar';
        }
      }

      if (elMargin) {
        elMargin.textContent = `${avgMargin}%`;
        elMargin.className = `kpi-val ${avgMargin >= 10 ? 'positive' : (avgMargin > 0 ? 'warning' : 'negative')}`;
        if (elMarginSub) elMarginSub.textContent = 'Margen neto histórico consolidado';
      }
    }

    // RENDERIZAR SECCIÓN INTERANUAL (AÑO VS AÑO)
    renderYearOverYearSection(allSummaries);
  }

  function renderYearOverYearSection(allSummaries) {
    const tbodyYoy = document.getElementById('tbody-yearly-comparison');
    if (!tbodyYoy) return;
    tbodyYoy.innerHTML = '';

    // Agrupar períodos por año
    const yearsMap = {};
    allSummaries.forEach(s => {
      const parts = s.periodKey.split('-');
      const yyyy = parts[0];
      const mm = parts[1];
      if (!yearsMap[yyyy]) yearsMap[yyyy] = {};
      yearsMap[yyyy][mm] = s.sales;
    });

    const registeredYears = Object.keys(yearsMap).sort();

    // Determinar año actual y año previo
    const currentYear = currentCompany.selectedPeriod ? currentCompany.selectedPeriod.split('-')[0] : String(new Date().getFullYear());
    let prevYear = String(Number(currentYear) - 1);

    if (!yearsMap[prevYear]) {
      const otherYears = registeredYears.filter(y => y !== currentYear);
      if (otherYears.length > 0) {
        prevYear = otherYears[otherYears.length - 1];
      }
    }

    const thPrev = document.getElementById('th-yoy-prev-year');
    const thCurr = document.getElementById('th-yoy-curr-year');
    if (thPrev) thPrev.textContent = `Año ${prevYear} ($)`;
    if (thCurr) thCurr.textContent = `Año ${currentYear} ($)`;

    const currSalesMap = yearsMap[currentYear] || {};
    const prevSalesMap = yearsMap[prevYear] || {};

    const currYearTotal = Object.values(currSalesMap).reduce((s, v) => s + v, 0);
    const prevYearTotal = Object.values(prevSalesMap).reduce((s, v) => s + v, 0);

    const elYoyCurr = document.getElementById('kpi-yoy-current-year-sales');
    const elYoyCurrLbl = document.getElementById('kpi-yoy-current-year-label');
    const elYoyPrev = document.getElementById('kpi-yoy-prev-year-sales');
    const elYoyPrevLbl = document.getElementById('kpi-yoy-prev-year-label');
    const elYoyCash = document.getElementById('kpi-yoy-growth-cash');
    const elYoyCashSub = document.getElementById('kpi-yoy-growth-cash-sub');
    const elYoyPct = document.getElementById('kpi-yoy-growth-pct');
    const elYoyPctSub = document.getElementById('kpi-yoy-growth-pct-sub');

    if (elYoyCurr) elYoyCurr.textContent = formatMoney(currYearTotal);
    if (elYoyCurrLbl) elYoyCurrLbl.textContent = `Año ${currentYear}`;

    if (elYoyPrev) {
      elYoyPrev.textContent = prevYearTotal > 0 ? formatMoney(prevYearTotal) : 'Sin datos';
    }
    if (elYoyPrevLbl) elYoyPrevLbl.textContent = `Año ${prevYear}`;

    if (prevYearTotal > 0 && currYearTotal > 0) {
      const diffCash = currYearTotal - prevYearTotal;
      const diffPct = Math.round((diffCash / prevYearTotal) * 100);
      const isUp = diffCash >= 0;

      if (elYoyCash) {
        elYoyCash.textContent = `${isUp ? '+' : ''}${formatMoney(diffCash)}`;
        elYoyCash.className = `kpi-val ${isUp ? 'positive' : 'negative'}`;
      }
      if (elYoyCashSub) elYoyCashSub.textContent = `Crecimiento neto vs ${prevYear}`;

      if (elYoyPct) {
        elYoyPct.innerHTML = `<i class="fa-solid ${isUp ? 'fa-arrow-trend-up' : 'fa-arrow-trend-down'}"></i> ${isUp ? '+' : ''}${diffPct}%`;
        elYoyPct.className = `kpi-val ${isUp ? 'positive' : 'negative'}`;
      }
      if (elYoyPctSub) elYoyPctSub.textContent = `Crecimiento interanual (${currentYear} vs ${prevYear})`;
    } else {
      if (elYoyCash) {
        elYoyCash.textContent = '—';
        elYoyCash.className = 'kpi-val';
      }
      if (elYoyCashSub) elYoyCashSub.textContent = `Carga meses de ${prevYear} para comparar`;
      if (elYoyPct) {
        elYoyPct.textContent = '—';
        elYoyPct.className = 'kpi-val';
      }
      if (elYoyPctSub) elYoyPctSub.textContent = 'Esperando carga de año comparativo';
    }

    // Tabla mes a mes entre ambos años
    let hasAnyComparisonData = false;
    for (let m = 1; m <= 12; m++) {
      const mm = String(m).padStart(2, '0');
      const mName = SPANISH_MONTHS[m - 1];
      const valPrev = prevSalesMap[mm] || 0;
      const valCurr = currSalesMap[mm] || 0;

      if (valPrev > 0 || valCurr > 0) {
        hasAnyComparisonData = true;
        const diff = valCurr - valPrev;
        let pctLabel = '—';
        let statusBadge = '<span class="status-pill" style="background:#f1f5f9;color:#64748b;">Mes en espera</span>';

        if (valPrev > 0 && valCurr > 0) {
          const pct = Math.round((diff / valPrev) * 100);
          const up = diff >= 0;
          pctLabel = `<strong class="${up ? 'positive' : 'negative'}">${up ? '+' : ''}${pct}%</strong>`;
          statusBadge = up
            ? `<span class="status-pill status-completed"><i class="fa-solid fa-arrow-up"></i> Creció +${pct}%</span>`
            : `<span class="status-pill status-failed"><i class="fa-solid fa-arrow-down"></i> Cayó ${pct}%</span>`;
        } else if (valCurr > 0 && valPrev === 0) {
          pctLabel = '<span class="text-muted">Nuevo en ' + currentYear + '</span>';
          statusBadge = `<span class="status-pill status-completed"><i class="fa-solid fa-plus"></i> Primer reporte</span>`;
        } else if (valPrev > 0 && valCurr === 0) {
          pctLabel = '<span class="text-muted">Pendiente ' + currentYear + '</span>';
          statusBadge = `<span class="status-pill" style="background:#fef3c7;color:#92400e;"><i class="fa-solid fa-clock"></i> Pendiente</span>`;
        }

        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td><strong><i class="fa-regular fa-calendar"></i> ${mName}</strong></td>
          <td class="text-right">${valPrev > 0 ? formatMoney(valPrev) : '<span class="text-muted">—</span>'}</td>
          <td class="text-right"><strong>${valCurr > 0 ? formatMoney(valCurr) : '<span class="text-muted">—</span>'}</strong></td>
          <td class="text-right ${diff >= 0 ? 'positive' : 'negative'}">${(valPrev > 0 && valCurr > 0) ? formatMoney(diff) : '—'}</td>
          <td class="text-center">${pctLabel}</td>
          <td>${statusBadge}</td>
        `;
        tbodyYoy.appendChild(tr);
      }
    }

    if (!hasAnyComparisonData) {
      tbodyYoy.innerHTML = `
        <tr>
          <td colspan="6" class="text-center" style="padding: 28px; color: #64748b;">
            <i class="fa-solid fa-layer-group" style="font-size: 1.5rem; color: #cbd5e1; margin-bottom: 6px; display: block;"></i>
            <strong>Aún no hay datos de múltiples años para comparar.</strong><br>
            Selecciona un año anterior (ej: <strong>${prevYear}</strong>) en el filtro de período y carga sus archivos. El sistema calculará automáticamente la comparación interanual.
          </td>
        </tr>
      `;
    }
  }

  // 13. Análisis Mensual y Diagnóstico de Rentabilidad Integral (P&L Multimódulo)
  function renderMonthlyAnalysisModule() {
    const bd = (currentCompany && currentCompany.businessData) ? currentCompany.businessData : {};

    // 1. OBTENCIÓN CONSOLIDADA DE VENTAS (INGRESOS OPERACIONALES)
    const sales = bd.sales || [];
    let totSales = 0;
    let salesDetail = '';
    if (sales.length > 0) {
      sales.forEach(s => {
        totSales += Number(s.total_vta !== undefined ? s.total_vta : (s.vta_neta !== undefined ? s.vta_neta : (s.total || 0))) || 0;
      });
      salesDetail = `Consolidado de ${sales.length} días facturados (Módulo 1: Ventas Diarias)`;
    } else {
      const monthlyProd = bd.monthlyProducts || [];
      if (monthlyProd.length > 0) {
        monthlyProd.forEach(p => {
          totSales += Number(p.venta_total !== undefined ? p.venta_total : (p.total !== undefined ? p.total : ((p.cant || 0) * (p.precio || 0)))) || 0;
        });
        salesDetail = `Facturación de ${monthlyProd.length} productos mensuales (Módulo 4: Prod. Mensuales)`;
      } else {
        const payMethods = bd.paymentMethods || [];
        if (payMethods.length > 0) {
          payMethods.forEach(pm => {
            totSales += Number(pm.monto !== undefined ? pm.monto : (pm.total || 0)) || 0;
          });
          salesDetail = `Recaudo de ${payMethods.length} formas de pago (Módulo 2: Formas de Pago)`;
        } else {
          salesDetail = 'Sin ventas registradas en el sistema';
        }
      }
    }

    // 2. OBTENCIÓN CONSOLIDADA DE COSTOS DE VENTAS / COMPRAS (COGS)
    const cogs = bd.cogs || [];
    let totCogs = 0;
    let cogsDetail = '';
    let cogsModuleOrigin = '';

    if (cogs.length > 0) {
      cogs.forEach(c => {
        totCogs += Number(c.venta_costo !== undefined ? c.venta_costo : ((c.costo || 0) * (c.cant || 0))) || 0;
      });
      cogsModuleOrigin = 'Módulo 10: Costos de Ventas (COGS)';
      cogsDetail = `Costeo técnico de ${cogs.length} recetas/productos vendidos`;
    } else {
      const suppliers = bd.suppliers || [];
      const purchaseCosts = bd.purchaseCosts || [];
      const purchases = (suppliers.length > 0) ? suppliers : purchaseCosts;

      if (purchases.length > 0) {
        purchases.forEach(p => {
          totCogs += Number(p.total !== undefined ? p.total : (p.total_compra !== undefined ? p.total_compra : (p.amount || 0))) || 0;
        });
        cogsModuleOrigin = (suppliers.length > 0) ? 'Módulo 5: Compras x Proveedor' : 'Módulo 11: Costos de Compras';
        cogsDetail = `Total de compras de insumos (${purchases.length} registros)`;
      } else {
        const supplies = bd.supplies || [];
        if (supplies.length > 0) {
          supplies.forEach(s => {
            totCogs += Number(s.total !== undefined ? s.total : ((s.cant || 0) * (s.precio || 0))) || 0;
          });
          cogsModuleOrigin = 'Módulo 6: Compras x Insumos';
          cogsDetail = `Compras de ${supplies.length} insumos detallados`;
        } else {
          cogsModuleOrigin = 'Módulo de Costos / Compras';
          cogsDetail = 'Sin compras o costos cargados';
        }
      }
    }
    const cogsPct = totSales > 0 ? (totCogs / totSales) * 100 : 0;

    // 3. BAJAS O DESPERDICIOS (MERMAS Y PÉRDIDAS DE INSUMOS)
    const hasWasteModule = Boolean(currentCompany && (!currentCompany.enabledModules || currentCompany.enabledModules.includes('tab-bajas-desperdicios')));
    const rawWaste = hasWasteModule ? (bd.waste || []) : [];
    let totWaste = 0;
    if (hasWasteModule) {
      rawWaste.forEach(r => {
        const cant = Number(r.cantidad) || 0;
        const cost = Number(r.costo !== undefined ? r.costo : (r.costo_unit !== undefined ? r.costo_unit : 0)) || 0;
        totWaste += Number(r.costo_total !== undefined ? r.costo_total : (cant * cost)) || 0;
      });
    }
    const wastePct = totSales > 0 ? (totWaste / totSales) * 100 : 0;

    // 4. UTILIDAD BRUTA OPERATIVA (VENTAS - COGS - BAJAS/DESPERDICIOS)
    const directCosts = totCogs + totWaste;
    const grossProfit = totSales - directCosts;
    const grossMargin = totSales > 0 ? (grossProfit / totSales) * 100 : 0;

    // 5. GASTOS DE PERSONAL (NÓMINA) (Módulo 8)
    const hasPayrollModule = Boolean(currentCompany && (!currentCompany.enabledModules || currentCompany.enabledModules.includes('tab-8-nomina')));
    const payroll = hasPayrollModule ? (bd.payroll || []) : [];
    let totPayroll = 0;
    if (hasPayrollModule) {
      payroll.forEach(p => {
        totPayroll += Number(p.total !== undefined ? p.total : (p.net !== undefined ? p.net : (p.amount || 0))) || 0;
      });
    }
    const payrollPct = totSales > 0 ? (totPayroll / totSales) * 100 : 0;

    // 6. ALMUERZO DE PERSONAL (ALIMENTACIÓN DEL EQUIPO)
    const hasLunchModule = Boolean(currentCompany && (!currentCompany.enabledModules || currentCompany.enabledModules.includes('tab-almuerzo-personal')));
    const rawLunch = hasLunchModule ? (bd.staffLunch || []) : [];
    let totLunch = 0;
    if (hasLunchModule) {
      rawLunch.forEach(r => {
        const cant = Number(r.cantidad) || 0;
        const cost = Number(r.costo !== undefined ? r.costo : (r.costo_unit !== undefined ? r.costo_unit : 0)) || 0;
        totLunch += Number(r.costo_total !== undefined ? r.costo_total : (cant * cost)) || 0;
      });
    }
    const lunchPct = totSales > 0 ? (totLunch / totSales) * 100 : 0;

    // 7. GASTOS OPERATIVOS MENSUALES (Módulo 7: Gastos Mensuales)
    const expenses = bd.expenses || [];
    let totExpenses = 0;
    expenses.forEach(e => {
      totExpenses += Number(e.total !== undefined ? e.total : (e.amount || 0)) || 0;
    });
    const expensesPct = totSales > 0 ? (totExpenses / totSales) * 100 : 0;

    // 8. TOTAL GASTOS OPERACIONALES (OPEX: Nómina + Almuerzo Personal + Gastos Mensuales)
    const totOpex = totPayroll + totLunch + totExpenses;
    const opexPct = totSales > 0 ? (totOpex / totSales) * 100 : 0;

    // 9. UTILIDAD NETA / RESULTADO FINAL DEL EJERCICIO (P&L)
    const netIncome = grossProfit - totOpex;
    const netMargin = totSales > 0 ? (netIncome / totSales) * 100 : 0;

    // 10. PUNTO DE EQUILIBRIO OPERATIVO
    let breakEvenSales = 0;
    let breakEvenCalculable = false;
    let breakEvenReason = '';
    if (totOpex <= 0) {
      breakEvenCalculable = false;
      breakEvenReason = 'Requiere registrar Gastos Operativos (Módulo 7) o Nómina';
    } else if (grossMargin <= 0) {
      breakEvenCalculable = false;
      breakEvenReason = 'Inalcanzable (Margen bruto es menor o igual a 0%)';
    } else {
      breakEvenSales = Math.round(totOpex / (grossMargin / 100));
      breakEvenCalculable = true;
    }

    // 11. ACTUALIZAR TARJETAS KPI (FILA 1 Y FILA 2)
    const elRev = document.getElementById('kpi-pl-revenue');
    const elRevSub = document.getElementById('kpi-pl-revenue-sub');
    const elCogs = document.getElementById('kpi-pl-cogs');
    const elCogsSub = document.getElementById('kpi-pl-cogs-sub');
    const elOpex = document.getElementById('kpi-pl-opex');
    const elOpexSub = document.getElementById('kpi-pl-opex-sub');
    const elNet = document.getElementById('kpi-pl-net-income');
    const elNetMargin = document.getElementById('kpi-pl-net-margin');
    const elGross = document.getElementById('kpi-pl-gross-income');
    const elGrossMargin = document.getElementById('kpi-pl-gross-margin');
    const elWaste = document.getElementById('kpi-pl-waste-cost');
    const elWasteSub = document.getElementById('kpi-pl-waste-sub');
    const elLunch = document.getElementById('kpi-pl-lunch-cost');
    const elLunchSub = document.getElementById('kpi-pl-lunch-sub');
    const elBreakEven = document.getElementById('kpi-pl-breakeven');
    const elBreakEvenSub = document.getElementById('kpi-pl-breakeven-sub');
    const elVerdictTitle = document.getElementById('kpi-pl-verdict-title');
    const elVerdictSub = document.getElementById('kpi-pl-verdict-sub');

    if (elRev) elRev.textContent = formatMoney(totSales);
    if (elRevSub) elRevSub.textContent = totSales > 0 ? '100% de la facturación' : 'Sin ventas';

    if (elCogs) elCogs.textContent = formatMoney(totCogs);
    if (elCogsSub) {
      elCogsSub.textContent = totSales > 0
        ? `${cogsPct.toFixed(1)}% compras • Mermas: ${formatMoney(totWaste)}`
        : 'Sin compras cargadas';
      elCogsSub.className = cogsPct > 40 ? 'kpi-sub warning' : 'kpi-sub';
    }

    if (elOpex) elOpex.textContent = formatMoney(totOpex);
    if (elOpexSub) {
      const parts = [];
      if (hasPayrollModule && totPayroll > 0) parts.push(`Nómina: ${formatMoney(totPayroll)}`);
      if (hasLunchModule && totLunch > 0) parts.push(`Almuerzo: ${formatMoney(totLunch)}`);
      if (totExpenses > 0) parts.push(`Gastos: ${formatMoney(totExpenses)}`);
      elOpexSub.textContent = parts.length > 0 ? parts.join(' • ') : 'Nómina + Almuerzo + Gastos fijos';
    }

    if (elNet) {
      elNet.textContent = formatMoney(netIncome);
      elNet.className = `kpi-val ${netIncome >= 0 ? 'positive' : 'warning'}`;
    }
    if (elNetMargin) {
      elNetMargin.textContent = totSales > 0 ? `${netMargin.toFixed(1)}% margen neto` : '—';
      elNetMargin.className = `kpi-sub ${netIncome >= 0 ? 'positive' : 'warning'}`;
    }

    if (elGross) elGross.textContent = formatMoney(grossProfit);
    if (elGrossMargin) elGrossMargin.textContent = totSales > 0 ? `Margen Bruto: ${grossMargin.toFixed(1)}%` : '—';

    if (elWaste) elWaste.textContent = formatMoney(totWaste);
    if (elWasteSub) {
      elWasteSub.textContent = totSales > 0
        ? `${wastePct.toFixed(1)}% s/ventas (${rawWaste.length} insumos)`
        : (rawWaste.length > 0 ? `${rawWaste.length} mermas reportadas` : 'Sin mermas registradas');
      elWasteSub.className = wastePct > 2.5 ? 'kpi-sub warning' : 'kpi-sub';
    }

    if (elLunch) elLunch.textContent = formatMoney(totLunch);
    if (elLunchSub) {
      elLunchSub.textContent = totSales > 0
        ? `${lunchPct.toFixed(1)}% s/ventas (${rawLunch.length} insumos)`
        : (rawLunch.length > 0 ? `${rawLunch.length} insumos de comida` : 'Sin almuerzo registrado');
      elLunchSub.className = lunchPct > 4 ? 'kpi-sub warning' : 'kpi-sub';
    }

    if (elBreakEven) {
      elBreakEven.textContent = breakEvenCalculable ? formatMoney(breakEvenSales) : '—';
      elBreakEven.className = breakEvenCalculable ? 'kpi-val' : 'kpi-val text-muted';
    }
    if (elBreakEvenSub) {
      if (!breakEvenCalculable) {
        elBreakEvenSub.textContent = totOpex <= 0 ? 'Pendiente de gastos fijos (OPEX)' : 'Margen bruto <= 0%';
        elBreakEvenSub.className = 'kpi-sub';
      } else if (totSales > 0) {
        const deltaBE = totSales - breakEvenSales;
        elBreakEvenSub.textContent = deltaBE >= 0 ? `Superado por +${formatMoney(deltaBE)}` : `Déficit de -${formatMoney(Math.abs(deltaBE))}`;
        elBreakEvenSub.className = deltaBE >= 0 ? 'kpi-sub positive' : 'kpi-sub warning';
      } else {
        elBreakEvenSub.textContent = 'Facturación mínima requerida';
        elBreakEvenSub.className = 'kpi-sub';
      }
    }

    // 12. GENERAR VEREDICTO DE RENTABILIDAD Y DIAGNÓSTICO DC ASESORIAS
    const hasData = (totSales > 0) || (totCogs > 0) || (totWaste > 0) || (totPayroll > 0) || (totLunch > 0) || (totExpenses > 0);
    const advisorBox = document.getElementById('pl-advisor-box');

    // Avisos específicos para mermas y almuerzo personal
    let wasteAlertNote = '';
    if (totWaste > 0) {
      if (wastePct > 2.5) {
        wasteAlertNote = `⚠️ <strong>Alerta en Bajas o Desperdicios:</strong> Las pérdidas por mermas y vencimientos representan el <strong>${wastePct.toFixed(1)}% de las ventas (${formatMoney(totWaste)})</strong>, superando el límite técnico del 2.5%. Esta fuga deteriora directamente el margen bruto de tu negocio. Se recomienda auditoría de compras perecederas y rotación estricta PEPS.`;
      } else {
        wasteAlertNote = `✅ <strong>Control de Mermas:</strong> Las bajas y desperdicios (${wastePct.toFixed(1)}% / ${formatMoney(totWaste)}) se encuentran bajo control operativo.`;
      }
    }

    let lunchAlertNote = '';
    if (totLunch > 0) {
      if (lunchPct > 4.0) {
        lunchAlertNote = `⚠️ <strong>Atención en Almuerzo de Personal:</strong> La alimentación del equipo representa el <strong>${lunchPct.toFixed(1)}% de las ventas (${formatMoney(totLunch)})</strong>. Sugerimos estandarizar porciones y menú de empleados con insumos de costo controlado.`;
      } else {
        lunchAlertNote = `✅ <strong>Almuerzo de Personal Equilibrado:</strong> El costo de alimentación del equipo (${lunchPct.toFixed(1)}% / ${formatMoney(totLunch)}) está dentro del rango operativo normal.`;
      }
    }

    if (!hasData) {
      if (elVerdictTitle) elVerdictTitle.textContent = 'Esperando Datos';
      if (elVerdictSub) elVerdictSub.textContent = 'Sube ventas y costos en sus módulos';

      if (advisorBox) {
        advisorBox.className = 'advisor-box sin-datos';
        advisorBox.innerHTML = `
          <div class="advisor-verdict-badge sin-datos"><i class="fa-solid fa-circle-info"></i> Esperando Información de los Módulos</div>
          <h5><i class="fa-solid fa-magnifying-glass-chart"></i> Diagnóstico de Rentabilidad DC ASESORIAS</h5>
          <p>Para emitir el informe financiero consolidado, sube la información en los módulos correspondientes: <strong>Módulo 1 (Ventas Diarias)</strong> y los módulos de costos (<strong>Compras</strong>, <strong>Bajas o Desperdicios</strong>, <strong>Almuerzo Personal</strong>${hasPayrollModule ? ', <strong>Nómina</strong>' : ''} y <strong>Gastos Mensuales</strong>). El sistema evaluará en tiempo real la rentabilidad neta real de tu negocio.</p>
        `;
      }
    } else if (totSales === 0 && (totCogs > 0 || totWaste > 0 || totOpex > 0)) {
      const totOutflows = directCosts + totOpex;
      if (elVerdictTitle) elVerdictTitle.textContent = 'Déficit (Sin Ventas)';
      if (elVerdictSub) elVerdictSub.textContent = `Costos acumulados: ${formatMoney(totOutflows)}`;

      if (advisorBox) {
        advisorBox.className = 'advisor-box perdida';
        advisorBox.innerHTML = `
          <div class="advisor-verdict-badge perdida"><i class="fa-solid fa-triangle-exclamation"></i> Alerta: Costos sin Ventas Registradas</div>
          <h5><i class="fa-solid fa-triangle-exclamation"></i> Diagnóstico Financiero DC ASESORIAS</h5>
          <p>Se registran costos de mercancía (${formatMoney(totCogs)}), bajas/desperdicios (${formatMoney(totWaste)}), almuerzo de personal (${formatMoney(totLunch)})${hasPayrollModule ? `, nómina (${formatMoney(totPayroll)})` : ''} y gastos operativos (${formatMoney(totExpenses)}) por un total de <strong>${formatMoney(totOutflows)}</strong>, pero aún no se han registrado ventas en el período. Carga las ventas en el Módulo 1 para determinar la rentabilidad neta.</p>
        `;
      }
    } else if (totSales > 0 && directCosts === 0 && totOpex === 0) {
      if (elVerdictTitle) elVerdictTitle.textContent = 'Solo Ventas Registradas';
      if (elVerdictSub) elVerdictSub.textContent = 'Pendiente de costos y gastos';
      if (elNetMargin) {
        elNetMargin.textContent = 'Pendiente de costos y OPEX';
        elNetMargin.className = 'kpi-sub';
      }
      if (advisorBox) {
        advisorBox.className = 'advisor-box alerta';
        advisorBox.innerHTML = `
          <div class="advisor-verdict-badge alerta"><i class="fa-solid fa-clock-rotate-left"></i> Información Parcial: Solo Ventas Registradas</div>
          <h5><i class="fa-solid fa-file-invoice-dollar"></i> Diagnóstico Financiero Parcial - DC ASESORIAS</h5>
          <p>Se ha consolidado una facturación de <strong>${formatMoney(totSales)}</strong>, pero <strong>aún no se han registrado compras de mercancía ni gastos operativos fijos (arriendo, servicios públicos, etc.)</strong> en este período.</p>
          <p>Para determinar la rentabilidad neta real de tu negocio y calcular el punto de equilibrio operativo exacto, ingresa los registros en los módulos de <strong>Compras</strong> y <strong>Gastos Mensuales (Módulo 7)</strong>.</p>
          <div class="advisor-metrics-summary">
            <div class="summary-pill"><i class="fa-solid fa-chart-line positive"></i> <strong>Ventas:</strong> ${formatMoney(totSales)}</div>
            <div class="summary-pill"><i class="fa-solid fa-cart-shopping warning"></i> <strong>Compras / COGS:</strong> $ 0 (Sin cargar)</div>
            <div class="summary-pill"><i class="fa-solid fa-receipt warning"></i> <strong>Gastos OPEX:</strong> $ 0 (Sin cargar)</div>
            <div class="summary-pill"><i class="fa-solid fa-scale-balanced warning"></i> <strong>Punto de Equilibrio:</strong> Pendiente de Gastos</div>
          </div>
        `;
      }
    } else if (totSales > 0 && directCosts > 0 && totOpex === 0) {
      if (elVerdictTitle) elVerdictTitle.textContent = 'Ventas y Compras Cargadas';
      if (elVerdictSub) elVerdictSub.textContent = 'Pendiente de gastos fijos (Módulo 7)';
      if (advisorBox) {
        advisorBox.className = 'advisor-box alerta';
        advisorBox.innerHTML = `
          <div class="advisor-verdict-badge alerta"><i class="fa-solid fa-clock-rotate-left"></i> Margen Bruto Calculado • Falta OPEX</div>
          <h5><i class="fa-solid fa-scale-balanced"></i> Diagnóstico Financiero Parcial - DC ASESORIAS</h5>
          <p>Se registran ventas por <strong>${formatMoney(totSales)}</strong> y costos directos de compras/mermas por <strong>${formatMoney(directCosts)}</strong>, generando un margen bruto del <strong>${grossMargin.toFixed(1)}%</strong> (${formatMoney(grossProfit)}). Sin embargo, <strong>no se han registrado Gastos Operativos Mensuales (Módulo 7)</strong>.</p>
          <p>Para calcular la Utilidad Neta definitiva y el Punto de Equilibrio Operativo exacto, registra los gastos fijos del mes en el <strong>Módulo 7: Gastos Mensuales</strong>.</p>
          <div class="advisor-metrics-summary">
            <div class="summary-pill"><i class="fa-solid fa-shield-halved positive"></i> <strong>Margen Bruto:</strong> ${grossMargin.toFixed(1)}% (${formatMoney(grossProfit)})</div>
            <div class="summary-pill"><i class="fa-solid fa-cart-shopping"></i> <strong>COGS:</strong> ${cogsPct.toFixed(1)}% (${formatMoney(totCogs)})</div>
            <div class="summary-pill"><i class="fa-solid fa-receipt warning"></i> <strong>Gastos OPEX:</strong> $ 0 (Sin cargar)</div>
            <div class="summary-pill"><i class="fa-solid fa-scale-balanced warning"></i> <strong>Punto de Equilibrio:</strong> Pendiente de Gastos</div>
          </div>
        `;
      }
    } else if (netIncome > 0 && netMargin >= 12) {
      if (elVerdictTitle) elVerdictTitle.textContent = 'Negocio Rentable';
      if (elVerdictSub) elVerdictSub.textContent = `Saludable (${netMargin.toFixed(1)}% margen neto)`;

      if (advisorBox) {
        advisorBox.className = 'advisor-box rentable';
        advisorBox.innerHTML = `
          <div class="advisor-verdict-badge rentable"><i class="fa-solid fa-circle-check"></i> Veredicto: EMPRESA ALTAMENTE RENTABLE</div>
          <h5><i class="fa-solid fa-award"></i> Diagnóstico Financiero Integral DC ASESORIAS</h5>
          <p>¡Excelente salud financiera! La empresa es <strong>plenamente rentable</strong>, generando una <strong>Utilidad Neta de ${formatMoney(netIncome)}</strong> que equivale a un margen neto del <strong>${netMargin.toFixed(1)}%</strong> sobre las ventas totales (${formatMoney(totSales)}), tras deducir compras de mercancía, mermas/desperdicios, alimentación de empleados, nómina y gastos fijos.</p>
          <div class="advisor-metrics-summary">
            <div class="summary-pill"><i class="fa-solid fa-shield-halved positive"></i> <strong>Margen Bruto:</strong> ${grossMargin.toFixed(1)}% (${formatMoney(grossProfit)})</div>
            <div class="summary-pill"><i class="fa-solid fa-cart-shopping"></i> <strong>COGS:</strong> ${cogsPct.toFixed(1)}% (${formatMoney(totCogs)})</div>
            <div class="summary-pill"><i class="fa-solid fa-trash-can-arrow-up ${wastePct > 2.5 ? 'warning' : 'positive'}"></i> <strong>Mermas / Bajas:</strong> ${wastePct.toFixed(1)}% (${formatMoney(totWaste)})</div>
            <div class="summary-pill"><i class="fa-solid fa-bowl-food ${lunchPct > 4 ? 'warning' : 'positive'}"></i> <strong>Almuerzo Personal:</strong> ${lunchPct.toFixed(1)}% (${formatMoney(totLunch)})</div>
            ${hasPayrollModule ? `<div class="summary-pill"><i class="fa-solid fa-users"></i> <strong>Nómina:</strong> ${payrollPct.toFixed(1)}% (${formatMoney(totPayroll)})</div>` : ''}
            <div class="summary-pill"><i class="fa-solid fa-scale-balanced text-gold"></i> <strong>Punto de Equilibrio:</strong> ${formatMoney(breakEvenSales)}/mes</div>
          </div>
          <div class="advisor-recommendation">
            <i class="fa-solid fa-lightbulb text-gold"></i> <strong>Dictamen y Recomendación de DC Asesorías:</strong>
            <div style="margin-top:6px; line-height:1.5;">
              ${wasteAlertNote ? `<div>${wasteAlertNote}</div>` : ''}
              ${lunchAlertNote ? `<div>${lunchAlertNote}</div>` : ''}
              <div style="margin-top:4px;">Tu negocio posee una estructura operativa sólida. Mantén el monitoreo sobre el costo de insumos y mermas, y destina un 20% de las utilidades líquidas a un fondo de reserva para contingencias e inversión.</div>
            </div>
          </div>
        `;
      }
    } else if (netIncome > 0 && netMargin < 12) {
      if (elVerdictTitle) elVerdictTitle.textContent = 'Rentable (Margen Ajustado)';
      if (elVerdictSub) elVerdictSub.textContent = `Margen Estrecho (${netMargin.toFixed(1)}%)`;

      if (advisorBox) {
        advisorBox.className = 'advisor-box alerta';
        advisorBox.innerHTML = `
          <div class="advisor-verdict-badge alerta"><i class="fa-solid fa-triangle-exclamation"></i> Veredicto: NEGOCIO RENTABLE CON MARGEN AJUSTADO</div>
          <h5><i class="fa-solid fa-award"></i> Diagnóstico Financiero Integral DC ASESORIAS</h5>
          <p>La empresa es <strong>rentable</strong> y genera una <strong>Utilidad Neta de ${formatMoney(netIncome)}</strong>, pero opera con un margen ajustado del <strong>${netMargin.toFixed(1)}%</strong>. El margen de maniobra es estrecho: una leve subida en las mermas de insumos o en los costos de alimentación del personal podría poner en riesgo los excedentes.</p>
          <div class="advisor-metrics-summary">
            <div class="summary-pill"><i class="fa-solid fa-cart-shopping ${cogsPct > 40 ? 'warning' : 'positive'}"></i> <strong>Costo Mercancía:</strong> ${cogsPct.toFixed(1)}% (${formatMoney(totCogs)})</div>
            <div class="summary-pill"><i class="fa-solid fa-trash-can-arrow-up ${wastePct > 2.5 ? 'warning' : 'positive'}"></i> <strong>Mermas / Bajas:</strong> ${wastePct.toFixed(1)}% (${formatMoney(totWaste)})</div>
            <div class="summary-pill"><i class="fa-solid fa-bowl-food ${lunchPct > 4 ? 'warning' : 'positive'}"></i> <strong>Almuerzo Personal:</strong> ${lunchPct.toFixed(1)}% (${formatMoney(totLunch)})</div>
            ${hasPayrollModule ? `<div class="summary-pill"><i class="fa-solid fa-users ${payrollPct > 35 ? 'warning' : 'positive'}"></i> <strong>Nómina:</strong> ${payrollPct.toFixed(1)}% (${formatMoney(totPayroll)})</div>` : ''}
            <div class="summary-pill"><i class="fa-solid fa-scale-balanced text-gold"></i> <strong>Punto de Equilibrio:</strong> ${formatMoney(breakEvenSales)}/mes</div>
          </div>
          <div class="advisor-recommendation">
            <i class="fa-solid fa-lightbulb text-gold"></i> <strong>Plan de Optimización DC Asesorías:</strong>
            <div style="margin-top:6px; line-height:1.5;">
              ${wasteAlertNote ? `<div>${wasteAlertNote}</div>` : ''}
              ${lunchAlertNote ? `<div>${lunchAlertNote}</div>` : ''}
              <div style="margin-top:4px;">${cogsPct > 40 ? 'El costo de compras/insumos supera el 40%. Consolidar proveedores y negociar descuentos.' : (hasPayrollModule && payrollPct > 35 ? 'La nómina supera el 35% de las ventas. Optimizar turnos en horas de menor afluencia.' : 'Revisar gastos administrativos y fomentar ventas de productos con mayor margen de contribución.')}</div>
            </div>
          </div>
        `;
      }
    } else {
      if (elVerdictTitle) elVerdictTitle.textContent = 'No Rentable (Pérdida)';
      if (elVerdictSub) elVerdictSub.textContent = `Déficit de -${formatMoney(Math.abs(netIncome))}`;

      if (advisorBox) {
        advisorBox.className = 'advisor-box perdida';
        advisorBox.innerHTML = `
          <div class="advisor-verdict-badge perdida"><i class="fa-solid fa-circle-xmark"></i> Veredicto: EMPRESA NO RENTABLE EN ESTE PERÍODO</div>
          <h5><i class="fa-solid fa-triangle-exclamation"></i> Diagnóstico de Urgencia Financiera DC ASESORIAS</h5>
          <p>La empresa presenta un <strong style="color:#b91c1c;">déficit operativo de -${formatMoney(Math.abs(netIncome))}</strong> (Margen Neto: <strong>${netMargin.toFixed(1)}%</strong>). La facturación actual (${formatMoney(totSales)}) es insuficiente para absorber los costos directos (${formatMoney(directCosts)}, incluyendo compras de ${formatMoney(totCogs)} y mermas de ${formatMoney(totWaste)}) y los gastos de operación (${formatMoney(totOpex)}, que incluyen almuerzo de personal de ${formatMoney(totLunch)}${hasPayrollModule ? ` y nómina de ${formatMoney(totPayroll)}` : ''}).</p>
          <div class="advisor-metrics-summary">
            <div class="summary-pill"><i class="fa-solid fa-scale-balanced" style="color:#dc2626;"></i> <strong>Venta Mínima de Equilibrio:</strong> ${formatMoney(breakEvenSales)}/mes</div>
            <div class="summary-pill"><i class="fa-solid fa-triangle-exclamation" style="color:#dc2626;"></i> <strong>Faltante para cubrir costos:</strong> -${formatMoney(Math.abs(totSales - breakEvenSales))}</div>
            <div class="summary-pill"><i class="fa-solid fa-trash-can-arrow-up" style="color:#dc2626;"></i> <strong>Pérdida por Mermas:</strong> ${formatMoney(totWaste)} (${wastePct.toFixed(1)}%)</div>
            <div class="summary-pill"><i class="fa-solid fa-bowl-food" style="color:#dc2626;"></i> <strong>Costo Almuerzo Equipo:</strong> ${formatMoney(totLunch)} (${lunchPct.toFixed(1)}%)</div>
          </div>
          <div class="advisor-recommendation">
            <i class="fa-solid fa-kit-medical" style="color:#dc2626;"></i> <strong>Plan de Choque Inmediato DC Asesorías:</strong>
            <div style="margin-top:6px; line-height:1.5;">
              <div>1) <strong>Frenar Mermas y Bajas:</strong> Las pérdidas por mermas de ${formatMoney(totWaste)} deben reducirse de inmediato ajustando el stock de compras a la rotación real diaria.</div>
              <div>2) <strong>Ajustar Alimentación de Personal:</strong> Revisar el costo de ${formatMoney(totLunch)} en almuerzo de equipo, estableciendo menús presupuestados.</div>
              <div>3) <strong>Reestructurar Precios y Ventas:</strong> Incrementar la meta comercial mensual al umbral de equilibrio de ${formatMoney(breakEvenSales)} para evitar el desangre de caja.</div>
            </div>
          </div>
        `;
      }
    }

    // 13. GENERAR FILAS CONSOLIDADAS DEL ESTADO DE RESULTADOS (P&L)
    const consolidatedPLRows = [
      {
        item: '(+) 1. Ingresos Operacionales (Ventas)',
        module: 'Módulo 1: Ventas Diarias',
        detail: salesDetail,
        amount: totSales,
        percent: '100%',
        evaluation: totSales > 0 ? 'Base de facturación del período' : 'Sin ventas registradas'
      },
      {
        item: '(-) 2. Costo de Ventas y Compras (COGS)',
        module: cogsModuleOrigin,
        detail: cogsDetail,
        amount: totCogs,
        percent: totSales > 0 ? `${cogsPct.toFixed(1)}%` : '—',
        evaluation: cogsPct === 0 ? 'Sin compras/costos' : (cogsPct <= 35 ? 'Excelente control de insumos' : (cogsPct <= 45 ? 'Costo en rango aceptable' : 'Alerta: Costo elevado de insumos'))
      },
      hasWasteModule ? {
        item: '(-) 3. Bajas o Desperdicios (Mermas / Pérdidas)',
        module: 'Módulo: Bajas o Desperdicios',
        detail: rawWaste.length > 0 ? `Total de ${rawWaste.length} insumos de baja reportados` : 'Sin mermas registradas',
        amount: totWaste,
        percent: totSales > 0 ? `${wastePct.toFixed(1)}%` : '—',
        evaluation: totWaste === 0 ? 'Sin mermas reportadas' : (wastePct <= 2.5 ? 'Pérdidas dentro de tolerancia normal (<2.5%)' : 'Alerta: Mermas elevadas deterioran el margen bruto (>2.5%)')
      } : {
        item: '(-) 3. Bajas o Desperdicios (Mermas / Pérdidas)',
        module: 'Módulo: Bajas o Desperdicios',
        detail: 'Módulo no activo para esta empresa',
        amount: 0,
        percent: 'N/A',
        evaluation: 'No aplica (Módulo inactivo)'
      },
      {
        item: '(=) 4. UTILIDAD BRUTA OPERATIVA',
        module: 'Cálculo de Margen Bruto',
        detail: `Ventas ($ ${totSales.toLocaleString('es-CO')}) - Compras ($ ${totCogs.toLocaleString('es-CO')}) - Mermas ($ ${totWaste.toLocaleString('es-CO')})`,
        amount: grossProfit,
        percent: totSales > 0 ? `${grossMargin.toFixed(1)}%` : '—',
        evaluation: grossMargin >= 55 ? 'Margen bruto saludable (>=55%)' : (grossMargin > 0 ? 'Margen bruto ajustado (<55%)' : 'Margen bruto negativo')
      },
      hasPayrollModule ? {
        item: '(-) 5. Gastos de Personal (Nómina)',
        module: 'Módulo 8: Nómina',
        detail: payroll.length > 0 ? `Total devengado (${payroll.length} registros)` : 'Sin registros de nómina',
        amount: totPayroll,
        percent: totSales > 0 ? `${payrollPct.toFixed(1)}%` : '—',
        evaluation: totPayroll === 0 ? 'Sin nómina registrada' : (payrollPct <= 30 ? 'Carga laboral balanceada' : 'Alerta: Nómina supera el 30%')
      } : {
        item: '(-) 5. Gastos de Personal (Nómina)',
        module: 'Módulo 8: Nómina',
        detail: 'Módulo no activo para esta empresa',
        amount: 0,
        percent: 'N/A',
        evaluation: 'No aplica (Módulo inactivo para esta empresa)'
      },
      hasLunchModule ? {
        item: '(-) 6. Costo de Almuerzo de Personal',
        module: 'Módulo: Almuerzo Personal',
        detail: rawLunch.length > 0 ? `Total de ${rawLunch.length} insumos de alimentación consumidos` : 'Sin registros de almuerzo personal',
        amount: totLunch,
        percent: totSales > 0 ? `${lunchPct.toFixed(1)}%` : '—',
        evaluation: totLunch === 0 ? 'Sin almuerzo de personal registrado' : (lunchPct <= 4 ? 'Costo de alimentación dentro de parámetro (<4%)' : 'Alerta: Almuerzo de personal supera el 4%')
      } : {
        item: '(-) 6. Costo de Almuerzo de Personal',
        module: 'Módulo: Almuerzo Personal',
        detail: 'Módulo no activo para esta empresa',
        amount: 0,
        percent: 'N/A',
        evaluation: 'No aplica (Módulo inactivo)'
      },
      {
        item: '(-) 7. Gastos Operativos y Generales',
        module: 'Módulo 7: Gastos Mensuales',
        detail: expenses.length > 0 ? `Total de ${expenses.length} conceptos (servicios, arriendos, varios)` : 'Sin gastos registrados',
        amount: totExpenses,
        percent: totSales > 0 ? `${expensesPct.toFixed(1)}%` : '—',
        evaluation: totExpenses === 0 ? 'Sin gastos registrados' : (expensesPct <= 20 ? 'Gastos generales controlados' : 'Gastos fijos elevados')
      },
      {
        item: '(=) 8. UTILIDAD NETA / RESULTADO FINAL',
        module: 'Dictamen de Rentabilidad',
        detail: 'Utilidad Bruta - OPEX (Nómina + Almuerzo Personal + Gastos Operativos)',
        amount: netIncome,
        percent: (totCogs === 0 && totOpex === 0 && totSales > 0) ? 'Parcial' : (totSales > 0 ? `${netMargin.toFixed(1)}%` : '—'),
        evaluation: (totCogs === 0 && totOpex === 0 && totSales > 0)
          ? 'Parcial: Pendiente de compras y gastos operativos'
          : (totOpex === 0 && totSales > 0)
            ? 'Parcial: Pendiente de registrar Gastos Operativos (Módulo 7)'
            : (netIncome > 0 ? (netMargin >= 12 ? 'Empresa Altamente Rentable' : 'Rentable con Margen Moderado') : (netIncome === 0 ? 'Punto de Equilibrio Exacto' : 'Empresa en Pérdida Operativa'))
      },
      {
        item: '(⚖) 9. Punto de Equilibrio Operativo',
        module: 'Meta Mínima de Sostenibilidad',
        detail: 'Facturación mensual requerida para no ganar ni perder',
        amount: breakEvenCalculable ? breakEvenSales : 0,
        displayAmount: breakEvenCalculable ? formatMoney(breakEvenSales) : '—',
        percent: breakEvenCalculable ? 'Umbral Mínimo' : 'Pendiente',
        evaluation: !breakEvenCalculable
          ? `No calculable: ${breakEvenReason}`
          : ((totSales >= breakEvenSales && totSales > 0)
              ? `Superado por +${formatMoney(totSales - breakEvenSales)}`
              : `Déficit de ventas: -${formatMoney(Math.abs(totSales - breakEvenSales))}`)
      }
    ];

    // 14. RENDERIZAR TABLA EN PANTALLA
    const tbody = document.getElementById('tbody-monthly-pl');
    if (tbody) {
      tbody.innerHTML = '';
      consolidatedPLRows.forEach(item => {
        const isResult = item.item.startsWith('(=)');
        const isEquilibrium = item.item.startsWith('(⚖)');
        const tr = document.createElement('tr');
        if (isResult) {
          tr.style.background = item.amount >= 0 ? '#f0fdf4' : '#fef2f2';
          tr.style.fontWeight = '700';
        } else if (isEquilibrium) {
          tr.style.background = '#fefce8';
          tr.style.fontWeight = '600';
        }

        let evalIcon = 'fa-circle-check positive';
        if (item.evaluation.includes('Alerta') || item.evaluation.includes('Déficit') || item.evaluation.includes('negativo') || item.evaluation.includes('Pérdida') || item.evaluation.includes('Inalcanzable')) {
          evalIcon = 'fa-triangle-exclamation warning';
        } else if (item.evaluation.includes('No calculable') || item.evaluation.includes('Parcial') || item.evaluation.includes('Pendiente')) {
          evalIcon = 'fa-circle-info text-warning';
        }

        const formattedVal = (item.displayAmount !== undefined && item.displayAmount !== null) ? item.displayAmount : formatMoney(item.amount);
        const statusClass = (item.percent === 'Pendiente' || item.percent === 'N/A' || item.percent === 'Parcial') ? 'status-pending' : 'status-active';

        tr.innerHTML = `
          <td><strong>${item.item}</strong></td>
          <td><span class="badge-tag" style="margin-right:6px;">${item.module}</span> <small style="color:#64748b;">${item.detail}</small></td>
          <td class="text-right"><strong>${formattedVal}</strong></td>
          <td class="text-center"><span class="status-pill ${statusClass}">${item.percent}</span></td>
          <td><i class="fa-solid ${evalIcon}"></i> ${item.evaluation}</td>
        `;
        tbody.appendChild(tr);
      });
    }

    // 15. PERSISTIR PARA DESCARGA DE EXCEL
    currentCompany.businessData.monthlyPL = consolidatedPLRows;
    updateCurrentCompanyData();
  }

  // ==========================================================================
  // 14. CONSOLIDADO ANUAL ACUMULADO
  // Consolidación de Ventas, Productos, Compras Proveedor, Compras Insumo, Gastos, Nómina y Márgenes
  // ==========================================================================
  let currentAnnualSelectedYear = null;
  let annualConsolidatedCache = null;

  function getAnnualConsolidatedData(company, targetYear) {
    if (!company) return null;
    const allPeriods = company.periods ? { ...company.periods } : {};
    if (company.selectedPeriod && company.businessData) {
      allPeriods[company.selectedPeriod] = company.businessData;
    }

    const yearStr = String(targetYear);
    const periodKeys = Object.keys(allPeriods).filter(pk => pk.startsWith(yearStr + '-')).sort();

    let totSales = 0;
    let totCogs = 0;
    let totPurchases = 0;
    let totExpenses = 0;
    let totPayroll = 0;

    const monthsData = [];
    const productsMap = {};
    const suppliersMap = {};
    const suppliesMap = {};
    const expensesMap = {};
    const payrollMap = {};

    periodKeys.forEach(pk => {
      const bd = allPeriods[pk];
      if (!bd) return;
      const monthSummary = getMonthlyPeriodSummary(bd, pk);
      const mSales = monthSummary ? monthSummary.sales : 0;
      let mCogs = monthSummary ? monthSummary.cogs : 0;
      let mExpenses = monthSummary ? monthSummary.expenses : 0;
      let mPayroll = monthSummary ? monthSummary.payroll : 0;

      // Respaldo directo para Costos de Ventas (COGS) si monthSummary devolvió 0
      if (mCogs === 0 && Array.isArray(bd.cogs) && bd.cogs.length > 0) {
        mCogs = bd.cogs.reduce((sum, r) => sum + (Number(r.venta_costo !== undefined ? r.venta_costo : (r.costo_total !== undefined ? r.costo_total : (r.total !== undefined ? r.total : ((Number(r.costo || r.rawCost || 0)) * (Number(r.cant || r.cantidad || 0))))))) || 0, 0);
      }

      // Compras a proveedores / insumos del mes
      let mPurchases = 0;
      if (Array.isArray(bd.suppliers) && bd.suppliers.length > 0) {
        mPurchases = bd.suppliers.reduce((sum, s) => sum + (Number(s.total !== undefined ? s.total : (s.total_compra !== undefined ? s.total_compra : (s.subtotal || 0))) || 0), 0);
      } else if (Array.isArray(bd.supplies) && bd.supplies.length > 0) {
        mPurchases = bd.supplies.reduce((sum, s) => sum + (Number(s.total !== undefined ? s.total : ((Number(s.costo || 0)) * (Number(s.cant || 0)))) || 0), 0);
      } else if (Array.isArray(bd.purchaseCosts) && bd.purchaseCosts.length > 0) {
        mPurchases = bd.purchaseCosts.reduce((sum, s) => sum + (Number(s.costo_total !== undefined ? s.costo_total : (s.total || 0)) || 0), 0);
      } else {
        mPurchases = mCogs;
      }

      // Reconciliación cruzada: si no se cargó COGS pero sí compras, usar compras como costo de ventas
      if (mCogs === 0 && mPurchases > 0) {
        mCogs = mPurchases;
      }
      if (mPurchases === 0 && mCogs > 0) {
        mPurchases = mCogs;
      }

      // Respaldo directo para Gastos Operativos
      if (mExpenses === 0 && Array.isArray(bd.expenses) && bd.expenses.length > 0) {
        mExpenses = bd.expenses.reduce((sum, e) => sum + (Number(e.monto !== undefined ? e.monto : (e.total || 0)) || 0), 0);
      }

      // Respaldo directo para Nómina de Personal
      if (mPayroll === 0 && Array.isArray(bd.payroll) && bd.payroll.length > 0) {
        mPayroll = bd.payroll.reduce((sum, p) => {
          const val = Number(
            p.total !== undefined ? p.total :
            (p.net !== undefined ? p.net :
            (p.total_devengado !== undefined ? p.total_devengado :
            (p.total_pago !== undefined ? p.total_pago :
            (p.neto !== undefined ? p.neto :
            (p.salario !== undefined ? p.salario :
            (p.salario_base !== undefined ? p.salario_base :
            (p.sueldo !== undefined ? p.sueldo :
            (p.amount !== undefined ? p.amount : (p.monto || 0)))))))))
          ) || 0;
          return sum + val;
        }, 0);
      }

      const mNet = mSales - mCogs - mExpenses - mPayroll;
      const mMargin = mSales > 0 ? Math.round((mNet / mSales) * 100) : 0;

      totSales += mSales;
      totCogs += mCogs;
      totPurchases += mPurchases;
      totExpenses += mExpenses;
      totPayroll += mPayroll;

      monthsData.push({
        periodKey: pk,
        label: getPeriodLabel(pk),
        sales: mSales,
        cogs: mCogs,
        purchases: mPurchases,
        expenses: mExpenses,
        payroll: mPayroll,
        net: mNet,
        margin: mMargin
      });

      // 1. Consolidar Productos Vendidos
      if (Array.isArray(bd.dailyProducts) && bd.dailyProducts.length > 0) {
        bd.dailyProducts.forEach(p => {
          const name = (p.producto || p.name || '').trim();
          if (!name) return;
          const key = name.toLowerCase();
          const cant = Number(p.cantidad !== undefined ? p.cantidad : p.quantity) || 0;
          const precio = Number(p.precio !== undefined ? p.precio : p.price) || 0;
          const total = Number(p.venta_total !== undefined ? p.venta_total : p.total) || (cant * precio);
          const cat = p.grupo || p.category || 'General';
          const code = p.codigo || p.code || '—';

          if (!productsMap[key]) {
            productsMap[key] = { codigo: code, producto: name, categoria: cat, cantidad: 0, total_venta: 0, sumPrecios: 0, countPrecios: 0 };
          }
          productsMap[key].cantidad += cant;
          productsMap[key].total_venta += total;
          if (precio > 0) {
            productsMap[key].sumPrecios += precio;
            productsMap[key].countPrecios++;
          }
          if (code !== '—') productsMap[key].codigo = code;
        });
      } else if (Array.isArray(bd.monthlyProducts) && bd.monthlyProducts.length > 0) {
        bd.monthlyProducts.forEach(p => {
          const name = (p.producto || p.name || '').trim();
          if (!name) return;
          const key = name.toLowerCase();
          const cant = Number(p.cantidad !== undefined ? p.cantidad : (p.cant !== undefined ? p.cant : p.quantity)) || 0;
          const precio = Number(p.precio_unitario !== undefined ? p.precio_unitario : (p.precio !== undefined ? p.precio : p.price)) || 0;
          const total = Number(p.total_venta !== undefined ? p.total_venta : (p.total !== undefined ? p.total : (p.venta_total !== undefined ? p.venta_total : (cant * precio)))) || 0;
          const cat = p.categoria || p.grupo || p.category || 'General';
          const code = p.codigo || p.code || '—';

          if (!productsMap[key]) {
            productsMap[key] = { codigo: code, producto: name, categoria: cat, cantidad: 0, total_venta: 0, sumPrecios: 0, countPrecios: 0 };
          }
          productsMap[key].cantidad += cant;
          productsMap[key].total_venta += total;
          if (precio > 0) {
            productsMap[key].sumPrecios += precio;
            productsMap[key].countPrecios++;
          }
          if (code !== '—') productsMap[key].codigo = code;
        });
      }

      // 2. Consolidar Proveedores
      if (Array.isArray(bd.suppliers) && bd.suppliers.length > 0) {
        bd.suppliers.forEach(s => {
          const name = (s.proveedor || s.name || '').trim();
          if (!name) return;
          const key = name.toLowerCase();
          const total = Number(s.total !== undefined ? s.total : (s.subtotal !== undefined ? s.subtotal : (s.total_compra || 0))) || 0;
          const nit = s.nit || '—';

          if (!suppliersMap[key]) {
            suppliersMap[key] = { proveedor: name, nit: nit, total: 0, count: 0 };
          }
          suppliersMap[key].total += total;
          suppliersMap[key].count++;
          if (nit !== '—') suppliersMap[key].nit = nit;
        });
      } else if (Array.isArray(bd.supplies) && bd.supplies.length > 0) {
        bd.supplies.forEach(s => {
          const name = (s.proveedor || s.supplier || '').trim();
          if (!name || name === '—') return;
          const key = name.toLowerCase();
          const costo = Number(s.costo !== undefined ? s.costo : s.unitCost) || 0;
          const cant = Number(s.cant !== undefined ? s.cant : s.quantity) || 0;
          const total = Number(s.total) || (costo * cant);

          if (!suppliersMap[key]) {
            suppliersMap[key] = { proveedor: name, nit: s.nit || '—', total: 0, count: 0 };
          }
          suppliersMap[key].total += total;
          suppliersMap[key].count++;
        });
      }

      // 3. Consolidar Insumos
      if (Array.isArray(bd.supplies) && bd.supplies.length > 0) {
        bd.supplies.forEach(s => {
          const name = (s.insumo || s.name || '').trim();
          if (!name) return;
          const key = name.toLowerCase();
          const grupo = s.grupo || s.category || 'General';
          const prov = s.proveedor || s.supplier || '—';
          const costo = Number(s.costo !== undefined ? s.costo : s.unitCost) || 0;
          const cant = Number(s.cant !== undefined ? s.cant : s.quantity) || 0;
          const total = Number(s.total) || (costo * cant);

          if (!suppliesMap[key]) {
            suppliesMap[key] = { insumo: name, grupo: grupo, proveedor: prov, cantidad: 0, total: 0, count: 0 };
          }
          suppliesMap[key].cantidad += cant;
          suppliesMap[key].total += total;
          suppliesMap[key].count++;
          if (prov !== '—') suppliesMap[key].proveedor = prov;
        });
      }

      // 4. Consolidar Gastos Operativos
      if (Array.isArray(bd.expenses) && bd.expenses.length > 0) {
        bd.expenses.forEach(e => {
          const cat = (e.categoria || e.category || 'Otros Gastos').trim();
          const key = cat.toLowerCase();
          const desc = e.descripcion || e.description || '—';
          const monto = Number(e.monto !== undefined ? e.monto : (e.total || 0)) || 0;

          if (!expensesMap[key]) {
            expensesMap[key] = { categoria: cat, descripcion: desc, total: 0, months: new Set() };
          }
          expensesMap[key].total += monto;
          expensesMap[key].months.add(pk);
          if (desc !== '—' && !expensesMap[key].descripcion.includes(desc)) {
            expensesMap[key].descripcion += (expensesMap[key].descripcion === '—' ? '' : ', ') + desc;
          }
        });
      }

      // 5. Consolidar Nómina de Personal
      if (Array.isArray(bd.payroll) && bd.payroll.length > 0) {
        bd.payroll.forEach(p => {
          const emp = (p.empleado || p.name || '').trim();
          if (!emp) return;
          const key = emp.toLowerCase();
          const cargo = p.cargo || p.concepto || p.role || p.position || 'Colaborador';
          const devengado = Number(
            p.total !== undefined ? p.total :
            (p.net !== undefined ? p.net :
            (p.total_devengado !== undefined ? p.total_devengado :
            (p.total_pago !== undefined ? p.total_pago :
            (p.neto !== undefined ? p.neto :
            (p.salario !== undefined ? p.salario :
            (p.salario_base !== undefined ? p.salario_base :
            (p.sueldo !== undefined ? p.sueldo :
            (p.amount !== undefined ? p.amount : (p.monto || 0)))))))))
          ) || 0;

          if (!payrollMap[key]) {
            payrollMap[key] = { empleado: emp, cargo: cargo, total: 0, months: new Set() };
          }
          payrollMap[key].total += devengado;
          payrollMap[key].months.add(pk);
          if (cargo !== 'Colaborador' && (payrollMap[key].cargo === 'Colaborador' || !payrollMap[key].cargo)) {
            payrollMap[key].cargo = cargo;
          }
        });
      }
    });

    // Reconciliación final de acumulados si se consolidaron en los mapas detallados
    const sumPayrollFromMap = Object.values(payrollMap).reduce((s, p) => s + (p.total || 0), 0);
    if (totPayroll === 0 && sumPayrollFromMap > 0) {
      totPayroll = sumPayrollFromMap;
    }
    const sumExpensesFromMap = Object.values(expensesMap).reduce((s, e) => s + (e.total || 0), 0);
    if (totExpenses === 0 && sumExpensesFromMap > 0) {
      totExpenses = sumExpensesFromMap;
    }
    const sumPurchasesSuppliers = Object.values(suppliersMap).reduce((s, p) => s + (p.total || 0), 0);
    const sumPurchasesSupplies = Object.values(suppliesMap).reduce((s, p) => s + (p.total || 0), 0);
    if (totPurchases === 0) {
      totPurchases = sumPurchasesSuppliers || sumPurchasesSupplies || totCogs;
    }
    if (totCogs === 0 && totPurchases > 0) {
      totCogs = totPurchases;
    }

    const grossProfit = totSales - totCogs;
    const opex = totExpenses + totPayroll;
    const netIncome = grossProfit - opex;
    const grossMargin = totSales > 0 ? ((grossProfit / totSales) * 100).toFixed(1) : '0.0';
    const netMargin = totSales > 0 ? ((netIncome / totSales) * 100).toFixed(1) : '0.0';
    const cogsPct = totSales > 0 ? ((totCogs / totSales) * 100).toFixed(1) : '0.0';
    const purchasesPct = totSales > 0 ? ((totPurchases / totSales) * 100).toFixed(1) : '0.0';
    const opexPct = totSales > 0 ? ((opex / totSales) * 100).toFixed(1) : '0.0';

    const productsList = Object.values(productsMap).map(p => {
      const avgPrice = p.countPrecios > 0 ? Math.round(p.sumPrecios / p.countPrecios) : (p.cantidad > 0 ? Math.round(p.total_venta / p.cantidad) : 0);
      return { ...p, precio_promedio: avgPrice };
    }).sort((a, b) => b.total_venta - a.total_venta);

    const suppliersList = Object.values(suppliersMap).sort((a, b) => b.total - a.total);
    const suppliesList = Object.values(suppliesMap).sort((a, b) => b.total - a.total);
    const expensesList = Object.values(expensesMap).map(e => ({
      ...e,
      monthsCount: e.months.size
    })).sort((a, b) => b.total - a.total);
    const payrollList = Object.values(payrollMap).map(p => ({
      ...p,
      monthsCount: p.months.size
    })).sort((a, b) => b.total - a.total);

    return {
      targetYear,
      periodKeys,
      totSales,
      totCogs,
      totPurchases,
      totExpenses,
      totPayroll,
      grossProfit,
      opex,
      netIncome,
      grossMargin,
      netMargin,
      cogsPct,
      purchasesPct,
      opexPct,
      monthsData,
      productsList,
      suppliersList,
      suppliesList,
      expensesList,
      payrollList
    };
  }

  function renderAnnualConsolidatedModule(overrideYear = null) {
    if (!currentCompany) return;
    const tabAnnual = document.getElementById('tab-15-consolidado-anual');
    if (!tabAnnual) return;

    // 1. Determinar años registrados y año actual
    const allPeriods = currentCompany.periods || {};
    const registeredYears = new Set();
    Object.keys(allPeriods).forEach(pk => {
      const m = pk.match(/^(\d{4})/);
      if (m) registeredYears.add(m[1]);
    });
    if (currentCompany.selectedPeriod) {
      const m = currentCompany.selectedPeriod.match(/^(\d{4})/);
      if (m) registeredYears.add(m[1]);
    }
    registeredYears.add(String(new Date().getFullYear()));
    const sortedYears = Array.from(registeredYears).sort().reverse();

    const activeYearFromPeriod = currentCompany.selectedPeriod ? currentCompany.selectedPeriod.split('-')[0] : String(new Date().getFullYear());
    const targetYear = overrideYear || currentAnnualSelectedYear || activeYearFromPeriod;
    currentAnnualSelectedYear = targetYear;

    // 2. Poblar selector de año
    const selectYear = document.getElementById('select-annual-year');
    if (selectYear) {
      selectYear.innerHTML = '';
      sortedYears.forEach(y => {
        const opt = document.createElement('option');
        opt.value = y;
        opt.textContent = `Año ${y}`;
        if (y === targetYear) opt.selected = true;
        selectYear.appendChild(opt);
      });
    }

    // 3. Obtener datos consolidados del año
    const data = getAnnualConsolidatedData(currentCompany, targetYear);
    annualConsolidatedCache = data;

    // Actualizar etiquetas de año
    const lblYear = document.getElementById('lbl-annual-summary-year');
    if (lblYear) lblYear.textContent = targetYear;

    const lblMonthsBadge = document.getElementById('lbl-annual-months-badge');
    if (lblMonthsBadge) {
      lblMonthsBadge.textContent = `${data.periodKeys.length} ${data.periodKeys.length === 1 ? 'Mes Reportado' : 'Meses Consolidados'}`;
    }

    // 4. Actualizar KPIs Principales
    const elSales = document.getElementById('kpi-annual-sales');
    const elSalesSub = document.getElementById('kpi-annual-sales-sub');
    const elCogs = document.getElementById('kpi-annual-cogs');
    const elCogsSub = document.getElementById('kpi-annual-cogs-sub');
    const elPurchases = document.getElementById('kpi-annual-purchases');
    const elPurchasesSub = document.getElementById('kpi-annual-purchases-sub');
    const elExpenses = document.getElementById('kpi-annual-expenses');
    const elExpensesSub = document.getElementById('kpi-annual-expenses-sub');
    const elPayroll = document.getElementById('kpi-annual-payroll');
    const elPayrollSub = document.getElementById('kpi-annual-payroll-sub');
    const elNet = document.getElementById('kpi-annual-net');
    const elNetSub = document.getElementById('kpi-annual-net-sub');

    if (elSales) elSales.textContent = formatMoney(data.totSales);
    if (elSalesSub) {
      const avgM = data.periodKeys.length > 0 ? Math.round(data.totSales / data.periodKeys.length) : 0;
      elSalesSub.textContent = `Promedio mensual: ${formatMoney(avgM)}`;
    }

    if (elCogs) elCogs.textContent = formatMoney(data.totCogs);
    if (elCogsSub) elCogsSub.textContent = `${data.cogsPct}% sobre ventas del año`;

    if (elPurchases) elPurchases.textContent = formatMoney(data.totPurchases);
    if (elPurchasesSub) elPurchasesSub.textContent = `${data.suppliersList.length} prov. / ${data.suppliesList.length} insumos (${data.purchasesPct}%)`;

    if (elExpenses) elExpenses.textContent = formatMoney(data.totExpenses);
    if (elExpensesSub) elExpensesSub.textContent = `${data.expensesList.length} categorías registradas (${data.opexPct}%)`;

    if (elPayroll) elPayroll.textContent = formatMoney(data.totPayroll);
    if (elPayrollSub) elPayrollSub.textContent = `${data.payrollList.length} colaboradores devengados`;

    if (elNet) {
      elNet.textContent = formatMoney(data.netIncome);
      elNet.className = `kpi-val ${data.netIncome >= 0 ? 'positive' : 'negative'}`;
    }
    if (elNetSub) {
      elNetSub.textContent = `Margen Neto Anual: ${data.netMargin}% (${data.netIncome >= 0 ? 'Superávit Operacional' : 'Déficit Operacional'})`;
    }

    // 5. Cascada de Rentabilidad Anual (Waterfall Grid)
    const waterfallGrid = document.getElementById('annual-waterfall-grid');
    if (waterfallGrid) {
      waterfallGrid.innerHTML = `
        <div class="waterfall-card" style="border-left: 3.5px solid #0284c7;">
          <span class="wf-label">1. Venta Total Acumulada</span>
          <span class="wf-val" style="color:#0284c7;">${formatMoney(data.totSales)}</span>
          <span class="wf-sub">100% Ingresos Operacionales</span>
        </div>
        <div class="waterfall-card" style="border-left: 3.5px solid #d97706;">
          <span class="wf-label">2. (-) Costo de Ventas (COGS)</span>
          <span class="wf-val" style="color:#d97706;">${formatMoney(data.totCogs)}</span>
          <span class="wf-sub">${data.cogsPct}% de la venta anual</span>
        </div>
        <div class="waterfall-card" style="border-left: 3.5px solid #059669;">
          <span class="wf-label">3. (=) Utilidad Bruta Anual</span>
          <span class="wf-val" style="color:#059669;">${formatMoney(data.grossProfit)}</span>
          <span class="wf-sub">Margen Bruto: ${data.grossMargin}%</span>
        </div>
        <div class="waterfall-card" style="border-left: 3.5px solid #dc2626;">
          <span class="wf-label">4. (-) Gastos Operacionales</span>
          <span class="wf-val" style="color:#dc2626;">${formatMoney(data.totExpenses)}</span>
          <span class="wf-sub">${data.expensesList.length} categorías de gasto</span>
        </div>
        <div class="waterfall-card" style="border-left: 3.5px solid #9333ea;">
          <span class="wf-label">5. (-) Nómina de Personal</span>
          <span class="wf-val" style="color:#9333ea;">${formatMoney(data.totPayroll)}</span>
          <span class="wf-sub">${data.payrollList.length} colaboradores</span>
        </div>
        <div class="waterfall-card" style="border-left: 3.5px solid ${data.netIncome >= 0 ? '#10b981' : '#ef4444'}; background:${data.netIncome >= 0 ? '#f0fdf4' : '#fef2f2'};">
          <span class="wf-label">6. (=) Utilidad Neta (EBITDA)</span>
          <span class="wf-val" style="color:${data.netIncome >= 0 ? '#047857' : '#b91c1c'};">${formatMoney(data.netIncome)}</span>
          <span class="wf-sub">Margen Neto: ${data.netMargin}%</span>
        </div>
      `;
    }

    // 6. Sub-pestaña 1: Desglose Mes a Mes
    renderAnnualMonthsTable(data);

    // 7. Sub-pestaña 2: Productos Vendidos
    renderAnnualProductsTable(data.productsList, data.totSales);

    // 8. Sub-pestaña 3: Compras x Proveedor
    renderAnnualSuppliersTable(data.suppliersList, data.totPurchases);

    // 9. Sub-pestaña 4: Compras x Insumos
    renderAnnualSuppliesTable(data.suppliesList);

    // 10. Sub-pestaña 5: Gastos Operativos
    renderAnnualExpensesTable(data.expensesList, data.totExpenses);

    // 11. Sub-pestaña 6: Nómina de Personal
    renderAnnualPayrollTable(data.payrollList, data.totPayroll);
  }

  function renderAnnualMonthsTable(data) {
    const tbody = document.getElementById('tbody-annual-months');
    const tfoot = document.getElementById('tfoot-annual-months');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (tfoot) tfoot.innerHTML = '';

    if (data.monthsData.length === 0) {
      tbody.innerHTML = `<tr><td colspan="9" class="text-center" style="padding:32px; color:#64748b;">No hay meses registrados para el año ${data.targetYear}.</td></tr>`;
      return;
    }

    data.monthsData.forEach(m => {
      const sharePct = data.totSales > 0 ? ((m.sales / data.totSales) * 100).toFixed(1) : '0.0';
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td><strong><i class="fa-regular fa-calendar-check text-gold"></i> ${m.label}</strong></td>
        <td class="text-right"><strong>${formatMoney(m.sales)}</strong></td>
        <td class="text-right">${formatMoney(m.cogs)}</td>
        <td class="text-right">${formatMoney(m.purchases)}</td>
        <td class="text-right">${formatMoney(m.expenses)}</td>
        <td class="text-right">${formatMoney(m.payroll)}</td>
        <td class="text-right ${m.net >= 0 ? 'positive' : 'negative'}"><strong>${formatMoney(m.net)}</strong></td>
        <td class="text-center"><span class="status-pill ${m.margin >= 15 ? 'status-completed' : (m.margin > 0 ? 'status-pending' : 'status-failed')}">${m.margin}%</span></td>
        <td class="text-center"><strong>${sharePct}%</strong></td>
      `;
      tbody.appendChild(tr);
    });

    if (tfoot) {
      tfoot.innerHTML = `
        <tr style="font-weight:800; background:#f8fafc; border-top:2px solid #cbd5e1;">
          <td>TOTAL AÑO ${data.targetYear} (${data.monthsData.length} meses):</td>
          <td class="text-right col-highlight total-gold">${formatMoney(data.totSales)}</td>
          <td class="text-right">${formatMoney(data.totCogs)}</td>
          <td class="text-right">${formatMoney(data.totPurchases)}</td>
          <td class="text-right">${formatMoney(data.totExpenses)}</td>
          <td class="text-right">${formatMoney(data.totPayroll)}</td>
          <td class="text-right ${data.netIncome >= 0 ? 'positive' : 'negative'}">${formatMoney(data.netIncome)}</td>
          <td class="text-center"><span class="status-pill ${data.netIncome >= 0 ? 'status-completed' : 'status-failed'}">${data.netMargin}%</span></td>
          <td class="text-center">100%</td>
        </tr>
      `;
    }
  }

  function renderAnnualProductsTable(products, totSales) {
    const tbody = document.getElementById('tbody-annual-products');
    const tfoot = document.getElementById('tfoot-annual-products');
    const lblCount = document.getElementById('lbl-annual-products-count');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (tfoot) tfoot.innerHTML = '';
    if (lblCount) lblCount.textContent = String(products.length);

    if (products.length === 0) {
      tbody.innerHTML = `<tr><td colspan="8" class="text-center" style="padding:32px; color:#64748b;">No hay productos vendidos registrados en los meses de este año.</td></tr>`;
      return;
    }

    let sumCant = 0;
    let sumTotal = 0;

    products.forEach((p, idx) => {
      sumCant += p.cantidad;
      sumTotal += p.total_venta;
      const share = totSales > 0 ? ((p.total_venta / totSales) * 100).toFixed(1) : '0.0';

      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td class="text-center"><strong>${idx + 1}</strong></td>
        <td><code>${p.codigo || '—'}</code></td>
        <td><strong>${p.producto}</strong></td>
        <td><span class="status-pill status-active">${p.categoria}</span></td>
        <td class="text-center"><strong>${p.cantidad.toLocaleString('es-CO')}</strong></td>
        <td class="text-right">${formatMoney(p.precio_promedio)}</td>
        <td class="text-right col-highlight"><strong>${formatMoney(p.total_venta)}</strong></td>
        <td class="text-center"><span class="status-pill status-pending">${share}%</span></td>
      `;
      tbody.appendChild(tr);
    });

    if (tfoot) {
      tfoot.innerHTML = `
        <tr style="font-weight:800; background:#f8fafc; border-top:2px solid #cbd5e1;">
          <td colspan="4">TOTALES ACUMULADOS (${products.length} productos):</td>
          <td class="text-center">${sumCant.toLocaleString('es-CO')}</td>
          <td class="text-right">—</td>
          <td class="text-right col-highlight total-gold">${formatMoney(sumTotal)}</td>
          <td class="text-center">${totSales > 0 ? ((sumTotal / totSales) * 100).toFixed(1) : 100}%</td>
        </tr>
      `;
    }
  }

  function renderAnnualSuppliersTable(suppliers, totPurchases) {
    const tbody = document.getElementById('tbody-annual-suppliers');
    const tfoot = document.getElementById('tfoot-annual-suppliers');
    const lblCount = document.getElementById('lbl-annual-suppliers-count');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (tfoot) tfoot.innerHTML = '';
    if (lblCount) lblCount.textContent = String(suppliers.length);

    if (suppliers.length === 0) {
      tbody.innerHTML = `<tr><td colspan="6" class="text-center" style="padding:32px; color:#64748b;">No hay compras por proveedor registradas en este año.</td></tr>`;
      return;
    }

    let sumPurchases = 0;
    let sumInvoices = 0;

    suppliers.forEach((s, idx) => {
      sumPurchases += s.total;
      sumInvoices += s.count;
      const share = totPurchases > 0 ? ((s.total / totPurchases) * 100).toFixed(1) : '0.0';

      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td class="text-center"><strong>${idx + 1}</strong></td>
        <td><strong><i class="fa-solid fa-truck text-gold" style="margin-right:6px;"></i> ${s.proveedor}</strong></td>
        <td><code>${s.nit}</code></td>
        <td class="text-center"><strong>${s.count}</strong></td>
        <td class="text-right col-highlight"><strong>${formatMoney(s.total)}</strong></td>
        <td class="text-center"><span class="status-pill status-pending">${share}%</span></td>
      `;
      tbody.appendChild(tr);
    });

    if (tfoot) {
      tfoot.innerHTML = `
        <tr style="font-weight:800; background:#f8fafc; border-top:2px solid #cbd5e1;">
          <td colspan="3">TOTALES ACUMULADOS (${suppliers.length} proveedores):</td>
          <td class="text-center">${sumInvoices}</td>
          <td class="text-right col-highlight total-gold">${formatMoney(sumPurchases)}</td>
          <td class="text-center">100%</td>
        </tr>
      `;
    }
  }

  function renderAnnualSuppliesTable(supplies) {
    const tbody = document.getElementById('tbody-annual-supplies');
    const tfoot = document.getElementById('tfoot-annual-supplies');
    const lblCount = document.getElementById('lbl-annual-supplies-count');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (tfoot) tfoot.innerHTML = '';
    if (lblCount) lblCount.textContent = String(supplies.length);

    if (supplies.length === 0) {
      tbody.innerHTML = `<tr><td colspan="7" class="text-center" style="padding:32px; color:#64748b;">No hay insumos o materias primas registrados en este año.</td></tr>`;
      return;
    }

    const totSuppliesSpend = supplies.reduce((sum, s) => sum + s.total, 0);
    let sumCant = 0;

    supplies.forEach((s, idx) => {
      sumCant += s.cantidad;
      const share = totSuppliesSpend > 0 ? ((s.total / totSuppliesSpend) * 100).toFixed(1) : '0.0';
      const fmtCant = Number.isInteger(s.cantidad) ? s.cantidad.toLocaleString('es-CO') : s.cantidad.toLocaleString('es-CO', { minimumFractionDigits: 1, maximumFractionDigits: 2 });

      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td class="text-center"><strong>${idx + 1}</strong></td>
        <td><strong>${s.insumo}</strong></td>
        <td><span class="status-pill status-active">${s.grupo}</span></td>
        <td>${s.proveedor}</td>
        <td class="text-center"><strong>${fmtCant}</strong></td>
        <td class="text-right col-highlight"><strong>${formatMoney(s.total)}</strong></td>
        <td class="text-center"><span class="status-pill status-pending">${share}%</span></td>
      `;
      tbody.appendChild(tr);
    });

    if (tfoot) {
      tfoot.innerHTML = `
        <tr style="font-weight:800; background:#f8fafc; border-top:2px solid #cbd5e1;">
          <td colspan="4">TOTALES ACUMULADOS (${supplies.length} insumos):</td>
          <td class="text-center">${sumCant.toLocaleString('es-CO')}</td>
          <td class="text-right col-highlight total-gold">${formatMoney(totSuppliesSpend)}</td>
          <td class="text-center">100%</td>
        </tr>
      `;
    }
  }

