  let pendingExclusiveUpload = null;

  function parseExclusiveNumVal(val) {
    if (val === undefined || val === null || val === '') return 0;
    if (typeof val === 'number') return isNaN(val) ? 0 : val;
    const cleaned = String(val).replace(/[\$,\s]/g, '').replace(/\.(?=\d{3})/g, '').replace(',', '.');
    return Number(cleaned) || 0;
  }

  function parseExclusiveFechaVal(rawVal) {
    if (!rawVal) return '';
    if (rawVal instanceof Date && !isNaN(rawVal.getTime())) {
      const yyyy = rawVal.getFullYear();
      const mm = String(rawVal.getMonth() + 1).padStart(2, '0');
      const dd = String(rawVal.getDate()).padStart(2, '0');
      return `${yyyy}-${mm}-${dd}`;
    }
    if (typeof rawVal === 'number' && rawVal > 1000) {
      const excelEpoch = new Date(1899, 11, 30);
      const d = new Date(excelEpoch.getTime() + rawVal * 86400000);
      if (!isNaN(d.getTime())) {
        const yyyy = d.getFullYear();
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        return `${yyyy}-${mm}-${dd}`;
      }
    }
    if (typeof rawVal === 'string') {
      const trimmed = rawVal.trim();
      if (/^\d{4}-\d{2}-\d{2}/.test(trimmed)) return trimmed.slice(0, 10);
      if (/^\d{1,2}\/\d{1,2}\/\d{4}/.test(trimmed)) {
        const parts = trimmed.split('/');
        return `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
      }
      if (/^\d{1,2}-\d{1,2}-\d{4}/.test(trimmed)) {
        const parts = trimmed.split('-');
        return `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
      }
      return trimmed;
    }
    return String(rawVal).trim();
  }

  function handleExclusiveFileUpload(moduleKey, file) {
    if (currentUserRole !== 'master') {
      showToast('Acceso denegado: solo el Usuario Master puede subir plantillas exclusivas.', 'error');
      return;
    }
    if (!currentCompany) {
      showToast('No hay una empresa activa seleccionada.', 'error');
      return;
    }

    const isExcel = /\.xlsx?$/i.test(file.name);
    if (isExcel && typeof XLSX === 'undefined') {
      showToast('La librería de lectura Excel (SheetJS) no está cargada. Recarga la página para solucionarlo.', 'error');
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        let rawRows = [];
        if (isExcel) {
          const data = new Uint8Array(e.target.result);
          const workbook = XLSX.read(data, { type: 'array', cellDates: true });
          const worksheet = resolveTargetWorksheet(workbook, moduleKey);
          rawRows = worksheet ? XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: 0 }) : [];
        } else {
          const decoder = new TextDecoder('utf-8');
          const text = decoder.decode(e.target.result);
          const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
          if (lines.length > 0) {
            const sep = lines[0].includes(';') ? ';' : ',';
            rawRows = lines.map(line => line.split(sep).map(c => c.trim().replace(/^["']|["']$/g, '')));
          }
        }

        if (!rawRows || rawRows.length <= 1) {
          showToast('El archivo cargado está vacío o no contiene filas de datos.', 'error');
          return;
        }

        let headerIdx = -1;
        for (let i = 0; i < Math.min(10, rawRows.length); i++) {
          const rowStr = (rawRows[i] || []).map(c => String(c || '').toUpperCase().trim()).join(' ');
          if (rowStr.includes('FECHA') || rowStr.includes('ALIMENTOS') || rowStr.includes('VENTA') || rowStr.includes('PROVEEDOR') || rowStr.includes('PRODUCTO') || rowStr.includes('CONCEPTO') || rowStr.includes('TOTAL') || rowStr.includes('NOMBRE') || rowStr.includes('VALOR') || rowStr.includes('NETO') || rowStr.includes('EFECTIVO')) {
            headerIdx = i;
            break;
          }
        }
        if (headerIdx === -1) headerIdx = 0;

        const headerRowFull = rawRows[headerIdx] || [];
        let colOffset = 0;
        for (let c = 0; c < headerRowFull.length; c++) {
          const v = String(headerRowFull[c] || '').trim();
          if (v.length > 0) { colOffset = c; break; }
        }

        const rawHeaders = headerRowFull.slice(colOffset).map(c => String(c || '').trim()).filter(c => c.length > 0);
        if (rawHeaders.length === 0) {
          showToast('No se pudieron identificar columnas válidas en el archivo exclusivo.', 'error');
          return;
        }

        // Abrir SIEMPRE el modal de mapeo inteligente exclusivo para que el usuario visualice
        // las columnas detectadas, confirme la asignación y revise la vista previa de datos.
        openExclusiveTemplateModal(moduleKey, file.name, rawRows, headerIdx, colOffset, rawHeaders);

      } catch (err) {
        console.error('Error al procesar plantilla exclusiva:', err);
        showToast('Error al leer el archivo. Verifica que sea un Excel o CSV válido.', 'error');
      }
    };

    reader.readAsArrayBuffer(file);
  }

  function openExclusiveTemplateModal(moduleKey, fileName, rawRows, headerIdx, colOffset, rawHeaders) {
    const modal = document.getElementById('modal-exclusive-template');
    if (!modal) return;

    pendingExclusiveUpload = {
      moduleKey,
      fileName,
      rawRows,
      headerIdx,
      colOffset,
      rawHeaders
    };

    const compName = currentCompany ? (currentCompany.companyName || 'Empresa') : 'Empresa';
    const modTitle = (moduleTemplates[moduleKey] && moduleTemplates[moduleKey].title) ? moduleTemplates[moduleKey].title : moduleKey;

    const lblComp = document.getElementById('lbl-exclusive-company-name');
    const lblMod = document.getElementById('lbl-exclusive-module-name');
    const lblFile = document.getElementById('lbl-exclusive-file-name');
    if (lblComp) lblComp.textContent = compName;
    if (lblMod) lblMod.textContent = modTitle;
    if (lblFile) lblFile.textContent = fileName;

    const fields = EXCLUSIVE_MODULE_FIELDS[moduleKey] || [
      { key: 'fecha', label: 'Fecha', required: true, synonyms: ['FECHA', 'DATE'] },
      { key: 'total', label: 'Total / Valor', required: true, synonyms: ['TOTAL', 'VALOR', 'MONTO'] }
    ];

    const mappingContainer = document.getElementById('exclusive-template-mapping-container');
    if (!mappingContainer) return;
    mappingContainer.innerHTML = '';

    const savedConfig = (currentCompany && currentCompany.exclusiveTemplates) ? currentCompany.exclusiveTemplates[moduleKey] : null;
    const savedMapping = savedConfig ? savedConfig.fieldMapping : null;

    fields.forEach(f => {
      let matchedIdx = -1;

      // 1. Si ya existía un mapeo previo guardado para esta empresa:
      if (savedMapping && savedMapping[f.key] !== undefined && savedMapping[f.key] >= 0 && savedMapping[f.key] < rawHeaders.length) {
        matchedIdx = savedMapping[f.key];
      } else {
        // 2. Coincidencia inteligente por sinónimos
        const fSynonyms = f.synonyms || [f.key.toUpperCase()];
        for (let hIdx = 0; hIdx < rawHeaders.length; hIdx++) {
          const normH = String(rawHeaders[hIdx] || '').toUpperCase().trim();
          if (fSynonyms.some(s => normH === s.toUpperCase())) {
            matchedIdx = hIdx;
            break;
          }
        }
        if (matchedIdx === -1) {
          for (let hIdx = 0; hIdx < rawHeaders.length; hIdx++) {
            const normH = String(rawHeaders[hIdx] || '').toUpperCase().trim();
            if (fSynonyms.some(s => normH.includes(s.toUpperCase()) || s.toUpperCase().includes(normH))) {
              matchedIdx = hIdx;
              break;
            }
          }
        }
      }

      const formGroup = document.createElement('div');
      formGroup.className = 'form-group';
      formGroup.style.margin = '0';
      formGroup.innerHTML = `
        <label style="font-size: 0.8rem; font-weight: 700; color: #334155; margin-bottom: 4px; display: block;">
          ${f.label}
        </label>
        <select class="form-select exclusive-field-select" data-field-key="${f.key}" data-required="false" style="width: 100%; padding: 7px 10px; font-size: 0.84rem; border-radius: 8px; border: 1.5px solid #cbd5e1;">
          <option value="-1">-- No Asignar / Dejar en 0 / Omitir --</option>
          ${rawHeaders.map((h, i) => `<option value="${i}" ${i === matchedIdx ? 'selected' : ''}>Columna: ${h}</option>`).join('')}
        </select>
      `;
      mappingContainer.appendChild(formGroup);
    });

    const previewContainer = document.getElementById('exclusive-template-preview-table');
    const previewRows = rawRows.slice(headerIdx + 1, Math.min(headerIdx + 5, rawRows.length));
    if (previewRows.length > 0 && previewContainer) {
      let tableHtml = '<table style="width: 100%; border-collapse: collapse; font-size: 0.78rem; text-align: left;"><thead><tr style="background:#e2e8f0; color:#1e293b;">';
      rawHeaders.forEach(h => {
        tableHtml += `<th style="padding: 4px 8px; border: 1px solid #cbd5e1; white-space: nowrap;">${h}</th>`;
      });
      tableHtml += '</tr></thead><tbody>';
      previewRows.forEach(r => {
        tableHtml += '<tr style="border-bottom: 1px solid #e2e8f0;">';
        const rowSlice = colOffset > 0 ? r.slice(colOffset) : r;
        rawHeaders.forEach((_, colI) => {
          tableHtml += `<td style="padding: 4px 8px; border: 1px solid #e2e8f0; white-space: nowrap;">${rowSlice[colI] !== undefined ? rowSlice[colI] : ''}</td>`;
        });
        tableHtml += '</tr>';
      });
      tableHtml += '</tbody></table>';
      previewContainer.innerHTML = tableHtml;
    } else if (previewContainer) {
      previewContainer.innerHTML = '<span style="color:#94a3b8;">No hay filas de muestra disponibles.</span>';
    }

    modal.classList.remove('hidden');
  }

  function closeExclusiveTemplateModal() {
    const modal = document.getElementById('modal-exclusive-template');
    if (modal) modal.classList.add('hidden');
    pendingExclusiveUpload = null;
  }

  function processRowsWithExclusiveMapping(moduleKey, rawRows, headerIdx, colOffset, rawHeaders, fieldMapping, fileName) {
    const daysEs = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'];
    const parsedRows = [];

    let targetPeriodKey = currentCompany.selectedPeriod || getCurrentSystemPeriod();

    // Si alguna fila tiene columna fecha asignada con formato YYYY-MM, adoptar ese período primero
    for (let i = headerIdx + 1; i < rawRows.length; i++) {
      const rawRow = rawRows[i];
      if (!rawRow) continue;
      const row = colOffset > 0 ? rawRow.slice(colOffset) : rawRow;
      if (fieldMapping.fecha !== undefined && fieldMapping.fecha >= 0 && fieldMapping.fecha < row.length) {
        const rawF = parseExclusiveFechaVal(row[fieldMapping.fecha]);
        const m = String(rawF || '').trim().match(/^(\d{4})-(\d{2})/);
        if (m) {
          targetPeriodKey = `${m[1]}-${m[2]}`;
          break;
        }
      }
    }

    for (let i = headerIdx + 1; i < rawRows.length; i++) {
      const rawRow = rawRows[i];
      if (!rawRow || !rawRow.some(c => c !== 0 && c !== '' && c !== null && c !== undefined)) {
        continue;
      }

      const row = colOffset > 0 ? rawRow.slice(colOffset) : rawRow;
      const firstCellStr = String(row[0] || '').trim().toUpperCase();
      if (firstCellStr.includes('TOTAL') || firstCellStr.includes('SUMA') || firstCellStr.startsWith('=')) {
        continue;
      }

      const rowObj = {};
      for (const fieldKey in fieldMapping) {
        const colI = fieldMapping[fieldKey];
        if (colI >= 0 && colI < row.length) {
          const val = row[colI];
          if (fieldKey === 'fecha') {
            rowObj.fecha = parseExclusiveFechaVal(val);
          } else if (fieldKey === 'dia') {
            rowObj.dia = formatSpanishDayName(val, rowObj.fecha);
          } else if (['total', 'total_vta', 'venta_dia', 'alimentos', 'bebidas', 'otros', 'cortesias', 'descuentos', 'vta_bruta', 'impo', 'propina', 'no_pax', 'no_ctas', 'prom_x_pax', 'prom_x_cuenta', 'efectivo', 'tarjetas', 'nequi', 'daviplata', 'qr', 'precio', 'cantidad', 'venta_total', 'costo', 'cant', 'costo_unit', 'costo_total', 'venta_costo', 'vta_total_sin_impo', 'folio_ini', 'folio_fin', 'no_folios', 'cxc_pendientes', 'nequi_transferencias'].includes(fieldKey)) {
            rowObj[fieldKey] = parseExclusiveNumVal(val);
          } else {
            rowObj[fieldKey] = String(val || '').trim();
          }
        }
      }

      // Si la fecha no fue mapeada en la plantilla exclusiva o viene vacía, asignar una fecha válida del período activo
      if (!rowObj.fecha) {
        if (moduleKey === 'sales' || moduleKey === 'paymentMethods') {
          const dayIdx = Math.min(31, Math.max(1, i - headerIdx));
          const dayStr = String(dayIdx).padStart(2, '0');
          rowObj.fecha = `${targetPeriodKey}-${dayStr}`;
        } else {
          rowObj.fecha = `${targetPeriodKey}-01`;
        }
      }

      // Asegurar que el campo "dia" contenga siempre y exclusivamente el nombre del día en español (Lunes..Domingo)
      rowObj.dia = formatSpanishDayName(rowObj.dia, rowObj.fecha);

      // Consistencia y valores por defecto automáticos según el módulo:
      if (moduleKey === 'sales') {
        if (!rowObj.total_vta && rowObj.vta_bruta) {
          rowObj.total_vta = (rowObj.vta_bruta || 0) + (rowObj.impo || 0) - (rowObj.descuentos || 0);
        } else if (!rowObj.vta_bruta && rowObj.total_vta) {
          rowObj.vta_bruta = rowObj.total_vta;
        }
        if (!rowObj.vta_bruta && (rowObj.alimentos || rowObj.bebidas || rowObj.otros)) {
          rowObj.vta_bruta = (rowObj.alimentos || 0) + (rowObj.bebidas || 0) + (rowObj.otros || 0);
          if (!rowObj.total_vta) rowObj.total_vta = rowObj.vta_bruta;
        }
        if (!rowObj.no_pax && (rowObj.total_vta > 0 || rowObj.vta_bruta > 0)) rowObj.no_pax = 1;
        if (!rowObj.no_ctas && (rowObj.total_vta > 0 || rowObj.vta_bruta > 0)) rowObj.no_ctas = 1;
        if (!rowObj.prom_x_pax && rowObj.no_pax > 0) {
          rowObj.prom_x_pax = Math.round((rowObj.total_vta || 0) / rowObj.no_pax);
        }
        if (!rowObj.prom_x_cuenta && rowObj.no_ctas > 0) {
          rowObj.prom_x_cuenta = Math.round((rowObj.total_vta || 0) / rowObj.no_ctas);
        }
      } else if (moduleKey === 'paymentMethods') {
        const sumMethods = (rowObj.efectivo || 0) + (rowObj.tarjetas || 0) + (rowObj.nequi || 0) + (rowObj.daviplata || 0) + (rowObj.qr || 0) + (rowObj.cxc_pendientes || 0);
        if (!rowObj.venta_dia && sumMethods > 0) {
          rowObj.venta_dia = sumMethods;
        } else if (rowObj.venta_dia > 0 && sumMethods === 0) {
          rowObj.efectivo = rowObj.venta_dia;
        }
        if (rowObj.cxc_pendientes === undefined) rowObj.cxc_pendientes = 0;
        if (rowObj.nequi_transferencias === undefined) rowObj.nequi_transferencias = (rowObj.nequi || 0);
      } else if (moduleKey === 'dailyProducts' || moduleKey === 'monthlyProducts') {
        if (!rowObj.producto) rowObj.producto = 'Producto General';
        if (!rowObj.grupo) rowObj.grupo = 'General';
        if (rowObj.und_vendidas !== undefined && (rowObj.cantidad === undefined || rowObj.cantidad === null || rowObj.cantidad === '')) {
          rowObj.cantidad = rowObj.und_vendidas;
        }
        if (rowObj.cantidad === undefined || rowObj.cantidad === null || rowObj.cantidad === '') {
          rowObj.cantidad = rowObj.venta_total ? 1 : 0;
        }
        if (rowObj.und_vendidas === undefined) {
          rowObj.und_vendidas = rowObj.cantidad;
        }
        if (!rowObj.precio && rowObj.precio_con_impo) {
          rowObj.precio = rowObj.precio_con_impo;
        }
        if (!rowObj.precio && rowObj.cantidad > 0 && rowObj.venta_total) {
          rowObj.precio = Math.round(rowObj.venta_total / rowObj.cantidad);
        }
        if (!rowObj.venta_total && rowObj.precio && rowObj.cantidad) {
          rowObj.venta_total = Math.round(rowObj.precio * rowObj.cantidad);
        }
      } else if (moduleKey === 'suppliers' || moduleKey === 'purchaseCosts') {
        if (!rowObj.proveedor) rowObj.proveedor = 'Proveedor General';
        if (!rowObj.total) rowObj.total = 0;
      } else if (moduleKey === 'supplies') {
        if (!rowObj.insumo) rowObj.insumo = 'Insumo General';
        if (!rowObj.grupo) rowObj.grupo = 'General';
        if (rowObj.cant === undefined || rowObj.cant === null || rowObj.cant === '') rowObj.cant = 1;
        if (!rowObj.total && rowObj.costo && rowObj.cant) rowObj.total = Math.round(rowObj.costo * rowObj.cant);
      } else if (moduleKey === 'expenses') {
        if (!rowObj.concepto) rowObj.concepto = 'Gasto General';
        if (!rowObj.total) rowObj.total = 0;
      } else if (moduleKey === 'payroll') {
        if (!rowObj.empleado) rowObj.empleado = 'Colaborador';
        if (!rowObj.total) rowObj.total = 0;
      } else if (moduleKey === 'tips') {
        if (!rowObj.nombre) rowObj.nombre = 'Vendedor';
        if (!rowObj.venta_total) rowObj.venta_total = 0;
      } else if (moduleKey === 'staffLunch' || moduleKey === 'waste') {
        if (!rowObj.insumo) rowObj.insumo = 'Insumo';
        if (!rowObj.grupo) rowObj.grupo = 'General';
        if (rowObj.cant === undefined || rowObj.cant === null || rowObj.cant === '') rowObj.cant = 1;
        if (!rowObj.costo_total && rowObj.costo_unit) rowObj.costo_total = Math.round(rowObj.costo_unit * rowObj.cant);
      } else if (moduleKey === 'cogs') {
        if (!rowObj.producto) rowObj.producto = 'Producto';
        if (!rowObj.venta_costo) rowObj.venta_costo = 0;
        if (!rowObj.vta_total_sin_impo) rowObj.vta_total_sin_impo = 0;
      }

      parsedRows.push(rowObj);
    }

    if (parsedRows.length === 0) {
      showToast('No se pudieron extraer registros con el mapeo de la plantilla exclusiva.', 'error');
      return;
    }

    const sanitized = parsedRows.map(r => {
      const clean = {};
      for (const k in r) {
        const v = r[k];
        if (v === null || v === undefined) {
          clean[k] = typeof r[k] === 'number' ? 0 : '';
        } else if (typeof v === 'number' && isNaN(v)) {
          clean[k] = 0;
        } else {
          clean[k] = v;
        }
      }
      return clean;
    });

    for (const r of sanitized) {
      if (r && r.fecha) {
        const m = String(r.fecha).trim().match(/^(\d{4})-(\d{2})/);
        if (m) {
          targetPeriodKey = `${m[1]}-${m[2]}`;
          break;
        }
      }
    }

    if (targetPeriodKey !== currentCompany.selectedPeriod) {
      if (!currentCompany.periods) currentCompany.periods = {};
      if (!currentCompany.periods[targetPeriodKey]) {
        currentCompany.periods[targetPeriodKey] = getDefaultBusinessData();
      }
      currentCompany.selectedPeriod = targetPeriodKey;
      currentCompany.businessData = currentCompany.periods[targetPeriodKey];
      showToast(`Archivo exclusivo identificado para el período ${getPeriodLabel(targetPeriodKey)}. Período activado.`, 'info');
    }

    currentCompany.businessData[moduleKey] = sanitized;
    if (moduleKey === 'suppliers') {
      currentCompany.businessData.purchaseCosts = sanitized;
    } else if (moduleKey === 'purchaseCosts') {
      currentCompany.businessData.suppliers = sanitized;
    }

    if (!currentCompany.periods) currentCompany.periods = {};
    currentCompany.periods[currentCompany.selectedPeriod] = currentCompany.businessData;

    updateCurrentCompanyData(true);
    updatePeriodControlUI();
    if (moduleKey === 'sales') updateAuditPeriodBadge();

    syncModuleWithBackend(moduleKey, sanitized, rawHeaders);
    if (moduleKey === 'suppliers') syncModuleWithBackend('purchaseCosts', sanitized, rawHeaders);
    else if (moduleKey === 'purchaseCosts') syncModuleWithBackend('suppliers', sanitized, rawHeaders);

    renderAll14Modules();
    if (selectChartPeriod) renderChartsModule(selectChartPeriod.value);

    showToast(`¡Plantilla exclusiva procesada con éxito para "${currentCompany.companyName}"! (${sanitized.length} registros cargados)`, 'success');
  }

  // Vincular inputs de archivo plano con plantilla exclusiva
  document.querySelectorAll('.input-flat-file-exclusive').forEach(input => {
    input.addEventListener('change', (e) => {
      const file = e.target.files[0];
      const moduleKey = input.getAttribute('data-module');
      if (file && moduleKey) {
        handleExclusiveFileUpload(moduleKey, file);
        input.value = '';
      }
    });
  });

  // Vincular eventos del modal de plantilla exclusiva
  const btnCloseExcl = document.getElementById('btn-close-modal-exclusive');
  const btnCancelExcl = document.getElementById('btn-cancel-exclusive-modal');
  const btnSaveExcl = document.getElementById('btn-save-and-process-exclusive');

  if (btnCloseExcl) btnCloseExcl.addEventListener('click', closeExclusiveTemplateModal);
  if (btnCancelExcl) btnCancelExcl.addEventListener('click', closeExclusiveTemplateModal);

  if (btnSaveExcl) {
    btnSaveExcl.addEventListener('click', () => {
      if (!pendingExclusiveUpload) return;
      const { moduleKey, fileName, rawRows, headerIdx, colOffset, rawHeaders } = pendingExclusiveUpload;

      const mapping = {};

      document.querySelectorAll('.exclusive-field-select').forEach(sel => {
        const fieldKey = sel.getAttribute('data-field-key');
        const val = parseInt(sel.value, 10);
        if (val >= 0) {
          mapping[fieldKey] = val;
        }
      });

      if (Object.keys(mapping).length === 0) {
        showToast('Por favor selecciona al menos una columna de tu archivo para poder procesar la plantilla.', 'error');
        return;
      }

      // Guardar configuración exclusiva para esta empresa de forma 100% aislada
      if (!currentCompany.exclusiveTemplates) {
        currentCompany.exclusiveTemplates = {};
      }
      currentCompany.exclusiveTemplates[moduleKey] = {
        fieldMapping: mapping,
        headers: rawHeaders,
        fileName: fileName,
        savedAt: new Date().toISOString()
      };

      closeExclusiveTemplateModal();
      processRowsWithExclusiveMapping(moduleKey, rawRows, headerIdx, colOffset, rawHeaders, mapping, fileName);
    });
  }

  // ==========================================================================
  // FILTROS INTERACTIVOS: PRODUCTOS DIARIOS Y MENSUALES
  // ==========================================================================
  const filterDailyFecha = document.getElementById('filter-daily-prod-fecha');
  const filterDailyGrupo = document.getElementById('filter-daily-prod-grupo');
  const btnResetDailyFilter = document.getElementById('btn-reset-daily-prod-filter');

  if (filterDailyFecha) {
    filterDailyFecha.addEventListener('change', (e) => {
      filterDailyProdState.fecha = e.target.value;
      renderDailyProductsModule();
    });
  }
  if (filterDailyGrupo) {
    filterDailyGrupo.addEventListener('change', (e) => {
      filterDailyProdState.grupo = e.target.value;
      renderDailyProductsModule();
    });
  }
  if (btnResetDailyFilter) {
    btnResetDailyFilter.addEventListener('click', () => {
      filterDailyProdState = { fecha: 'ALL', grupo: 'ALL' };
      if (filterDailyFecha) filterDailyFecha.value = 'ALL';
      if (filterDailyGrupo) filterDailyGrupo.value = 'ALL';
      renderDailyProductsModule();
    });
  }

  const filterMonthlyFecha = document.getElementById('filter-monthly-prod-fecha');
  const filterMonthlyGrupo = document.getElementById('filter-monthly-prod-grupo');
  const btnResetMonthlyFilter = document.getElementById('btn-reset-monthly-prod-filter');

  if (filterMonthlyFecha) {
    filterMonthlyFecha.addEventListener('change', (e) => {
      filterMonthlyProdState.fecha = e.target.value;
      renderMonthlyProductsModule();
    });
  }
  if (filterMonthlyGrupo) {
    filterMonthlyGrupo.addEventListener('change', (e) => {
      filterMonthlyProdState.grupo = e.target.value;
      renderMonthlyProductsModule();
    });
  }
  if (btnResetMonthlyFilter) {
    btnResetMonthlyFilter.addEventListener('click', () => {
      filterMonthlyProdState = { fecha: 'ALL', grupo: 'ALL' };
      if (filterMonthlyFecha) filterMonthlyFecha.value = 'ALL';
      if (filterMonthlyGrupo) filterMonthlyGrupo.value = 'ALL';
      renderMonthlyProductsModule();
    });
  }

  // ==========================================================================
  // FILTROS INTERACTIVOS: COMPRAS X PROVEEDOR
  // ==========================================================================
  const filterSuppliersProv = document.getElementById('filter-suppliers-prov');
  const filterSuppliersFecha = document.getElementById('filter-suppliers-fecha');
  const btnResetSuppliersFilter = document.getElementById('btn-reset-suppliers-filter');

  if (filterSuppliersProv) {
    filterSuppliersProv.addEventListener('change', (e) => {
      filterSuppliersState.proveedor = e.target.value;
      renderSuppliersModule();
    });
  }
  if (filterSuppliersFecha) {
    filterSuppliersFecha.addEventListener('change', (e) => {
      filterSuppliersState.fecha = e.target.value;
      renderSuppliersModule();
    });
  }
  if (btnResetSuppliersFilter) {
    btnResetSuppliersFilter.addEventListener('click', () => {
      filterSuppliersState = { proveedor: 'ALL', fecha: 'ALL' };
      if (filterSuppliersProv) filterSuppliersProv.value = 'ALL';
      if (filterSuppliersFecha) filterSuppliersFecha.value = 'ALL';
      renderSuppliersModule();
    });
  }

  // ==========================================================================
  // FILTROS INTERACTIVOS: COMPRAS X INSUMOS
  // ==========================================================================
  const filterSuppliesFecha = document.getElementById('filter-supplies-fecha');
  const filterSuppliesGrupo = document.getElementById('filter-supplies-grupo');
  const filterSuppliesInsumo = document.getElementById('filter-supplies-insumo');
  const filterSuppliesProv = document.getElementById('filter-supplies-prov');
  const btnResetSuppliesFilter = document.getElementById('btn-reset-supplies-filter');

  if (filterSuppliesFecha) {
    filterSuppliesFecha.addEventListener('change', (e) => {
      filterSuppliesState.fecha = e.target.value;
      renderSuppliesModule();
    });
  }
  if (filterSuppliesGrupo) {
    filterSuppliesGrupo.addEventListener('change', (e) => {
      filterSuppliesState.grupo = e.target.value;
      renderSuppliesModule();
    });
  }
  if (filterSuppliesInsumo) {
    filterSuppliesInsumo.addEventListener('change', (e) => {
      filterSuppliesState.insumo = e.target.value;
      renderSuppliesModule();
    });
  }
  if (filterSuppliesProv) {
    filterSuppliesProv.addEventListener('change', (e) => {
      filterSuppliesState.proveedor = e.target.value;
      renderSuppliesModule();
    });
  }
  if (btnResetSuppliesFilter) {
    btnResetSuppliesFilter.addEventListener('click', () => {
      filterSuppliesState = { fecha: 'ALL', grupo: 'ALL', insumo: 'ALL', proveedor: 'ALL' };
      if (filterSuppliesFecha) filterSuppliesFecha.value = 'ALL';
      if (filterSuppliesGrupo) filterSuppliesGrupo.value = 'ALL';
      if (filterSuppliesInsumo) filterSuppliesInsumo.value = 'ALL';
      if (filterSuppliesProv) filterSuppliesProv.value = 'ALL';
      renderSuppliesModule();
    });
  }

  // ==========================================================================
