  function getActiveCompanyRecipes() {
    if (!currentCompany) return [];
    const storageKey = `dc_recipes_${currentCompany.id}`;
    const local = localStorage.getItem(storageKey);
    if (local) {
      try { return JSON.parse(local); } catch (e) {}
    }
    if (currentCompany.recipes && Array.isArray(currentCompany.recipes)) {
      return currentCompany.recipes;
    }
    // Si es la empresa de pruebas, entregar las 5 recetas maestras por defecto
    if (currentCompany.id === 'comp_demo_pruebas_sandbox') {
      saveActiveCompanyRecipes(DEFAULT_SANDBOX_RECIPES);
      return DEFAULT_SANDBOX_RECIPES;
    }
    return [];
  }

  function saveActiveCompanyRecipes(recipesList) {
    if (!currentCompany) return;
    const storageKey = `dc_recipes_${currentCompany.id}`;
    localStorage.setItem(storageKey, JSON.stringify(recipesList));
    currentCompany.recipes = recipesList;
    if (firestoreDb && currentCompany.id) {
      firestoreDb.collection('companies').doc(currentCompany.id).update({
        recipes: recipesList,
        _syncedAt: Date.now()
      }).catch(err => console.log('Firestore recipes sync note:', err));
    }
  }

  // RENDERIZADOR DEL RECETARIO
  function renderRecipesModule() {
    const grid = document.getElementById('recipes-cards-grid');
    if (!grid) return;

    const recipes = getActiveCompanyRecipes();
    const selCat = document.getElementById('filter-recipe-cat');
    const txtSearch = document.getElementById('search-recipe-query');
    const badgeCount = document.getElementById('filter-recipe-count');

    // Categorías únicas
    if (selCat) {
      const currentCat = selCat.value || 'ALL';
      const cats = Array.from(new Set(recipes.map(r => r.category || 'General'))).sort();
      selCat.innerHTML = '<option value="ALL">-- Todas las Categorías --</option>' +
        cats.map(c => `<option value="${c}" ${c === currentCat ? 'selected' : ''}>${c}</option>`).join('');
    }

    // Filtrar recetas
    const catVal = selCat ? selCat.value : 'ALL';
    const query = txtSearch ? (txtSearch.value || '').trim().toLowerCase() : '';

    const filtered = recipes.filter(r => {
      const matchCat = (catVal === 'ALL') || (r.category === catVal);
      const matchQuery = !query ||
        (r.name && r.name.toLowerCase().includes(query)) ||
        (r.category && r.category.toLowerCase().includes(query)) ||
        (r.ingredients && r.ingredients.some(i => i.name && i.name.toLowerCase().includes(query)));
      return matchCat && matchQuery;
    });

    if (badgeCount) badgeCount.textContent = `${filtered.length} de ${recipes.length} recetas`;

    // Métricas globales (KPIs)
    let totalCosto = 0;
    let totalPrecio = 0;
    let alertCount = 0;

    recipes.forEach(r => {
      const cost = (r.ingredients || []).reduce((acc, i) => acc + (Number(i.subtotal) || 0), 0);
      const price = Number(r.salePrice) || 0;
      totalCosto += cost;
      totalPrecio += price;
      const fc = price > 0 ? (cost / price) * 100 : 0;
      if (fc > 35) alertCount++;
    });

    const avgFc = totalPrecio > 0 ? (totalCosto / totalPrecio) * 100 : 0;
    const avgMargin = 100 - avgFc;

    const elKpiTotal = document.getElementById('kpi-rec-total');
    const elKpiFc = document.getElementById('kpi-rec-fc');
    const elKpiMargin = document.getElementById('kpi-rec-margin');
    const elKpiAlerts = document.getElementById('kpi-rec-alerts');

    if (elKpiTotal) elKpiTotal.textContent = recipes.length;
    if (elKpiFc) elKpiFc.textContent = `${avgFc.toFixed(1)}%`;
    if (elKpiMargin) elKpiMargin.textContent = `${avgMargin.toFixed(1)}%`;
    if (elKpiAlerts) {
      elKpiAlerts.textContent = alertCount;
      const sub = document.getElementById('kpi-rec-alerts-sub');
      if (sub) sub.textContent = `${alertCount} plato(s) con Food Cost > 35%`;
    }

    // Renderizar tarjetas
    grid.innerHTML = '';
    if (filtered.length === 0) {
      grid.innerHTML = `
        <div style="grid-column:1/-1; text-align:center; padding:40px; background:#ffffff; border-radius:12px; border:1px solid #e2e8f0; color:#64748b;">
          <i class="fa-solid fa-utensils" style="font-size:2.5rem; color:#cbd5e1; margin-bottom:12px; display:block;"></i>
          <strong>No se encontraron recetas con los filtros seleccionados</strong>
          <p style="font-size:0.84rem; color:#94a3b8; margin-top:4px;">Haz clic en "Nueva Receta" o borra el término de búsqueda.</p>
        </div>`;
      return;
    }

    filtered.forEach(r => {
      const cost = (r.ingredients || []).reduce((acc, i) => acc + (Number(i.subtotal) || 0), 0);
      const price = Number(r.salePrice) || 0;
      const profit = price - cost;
      const fc = price > 0 ? (cost / price) * 100 : 0;
      const margin = 100 - fc;
      const isOptimal = fc <= 35;

      const card = document.createElement('div');
      card.className = 'recipe-card';
      card.innerHTML = `
        <div>
          <div class="recipe-card-header">
            <div>
              <h5 class="recipe-card-title">${r.name}</h5>
              <span class="badge-tag" style="background:#f1f5f9; color:#475569; font-size:0.72rem;">
                <i class="fa-solid fa-tag" style="margin-right:4px;"></i>${r.category || 'General'}
              </span>
            </div>
            <span class="badge-tag ${isOptimal ? 'status-active' : 'status-pending'}" style="font-size:0.75rem; font-weight:800;">
              ${isOptimal ? '<i class="fa-solid fa-circle-check"></i> ' : '<i class="fa-solid fa-triangle-exclamation"></i> '}${fc.toFixed(1)}% FC
            </span>
          </div>

          <div class="recipe-card-metrics">
            <div class="recipe-metric-item">
              <span class="recipe-metric-label">Costo Receta:</span>
              <span class="recipe-metric-val" style="color:#b45309;">${formatMoney(cost)}</span>
            </div>
            <div class="recipe-metric-item">
              <span class="recipe-metric-label">Precio Carta:</span>
              <span class="recipe-metric-val" style="color:#0284c7;">${formatMoney(price)}</span>
            </div>
            <div class="recipe-metric-item">
              <span class="recipe-metric-label">Margen Bruto:</span>
              <span class="recipe-metric-val" style="color:${isOptimal ? '#16a34a' : '#d97706'};">${margin.toFixed(1)}%</span>
            </div>
            <div class="recipe-metric-item">
              <span class="recipe-metric-label">Ganancia / Plato:</span>
              <span class="recipe-metric-val" style="color:#16a34a;">${formatMoney(profit)}</span>
            </div>
          </div>

          <div style="font-size:0.76rem; color:#64748b; margin-top:6px;">
            <i class="fa-solid fa-basket-shopping" style="color:var(--accent-gold); margin-right:4px;"></i>
            <strong>${(r.ingredients || []).length} ingredientes</strong> &bull; Rinde: ${r.portion || '1 porción'}
          </div>
        </div>

        <div class="recipe-card-footer">
          <button type="button" class="btn btn-xs btn-outline-primary btn-view-recipe" data-id="${r.id}">
            <i class="fa-solid fa-eye"></i> Ver Ficha
          </button>
          <div style="display:inline-flex; gap:6px;">
            <button type="button" class="btn btn-xs btn-outline-gold btn-sim-recipe" data-id="${r.id}" title="Simular variaciones en el cotizador">
              <i class="fa-solid fa-calculator"></i> Cotizar
            </button>
            <button type="button" class="btn btn-xs btn-outline-danger btn-del-recipe" data-id="${r.id}" title="Eliminar receta">
              <i class="fa-solid fa-trash-can"></i>
            </button>
          </div>
        </div>
      `;

      // Eventos de botones
      card.querySelector('.btn-view-recipe').addEventListener('click', () => openRecipeDetailModal(r.id));
      card.querySelector('.btn-sim-recipe').addEventListener('click', () => sendRecipeToSimulator(r.id));
      card.querySelector('.btn-del-recipe').addEventListener('click', () => deleteRecipe(r.id));

      grid.appendChild(card);
    });
  }

  // MODAL DETALLE DE FICHA TÉCNICA
  function openRecipeDetailModal(recipeId) {
    const recipes = getActiveCompanyRecipes();
    const r = recipes.find(x => x.id === recipeId);
    if (!r) return;

    const modal = document.getElementById('modal-recipe-view');
    const title = document.getElementById('view-recipe-title');
    const cat = document.getElementById('view-recipe-category');
    const body = document.getElementById('view-recipe-body');
    const btnQuote = document.getElementById('btn-quote-from-recipe');
    const btnPrint = document.getElementById('btn-print-recipe');

    if (title) title.textContent = r.name;
    if (cat) cat.textContent = `${r.category || 'General'} • ${r.portion || '1 porción'}`;

    const cost = (r.ingredients || []).reduce((acc, i) => acc + (Number(i.subtotal) || 0), 0);
    const price = Number(r.salePrice) || 0;
    const profit = price - cost;
    const fc = price > 0 ? (cost / price) * 100 : 0;
    const margin = 100 - fc;

    let rowsHtml = '';
    (r.ingredients || []).forEach((ing, idx) => {
      const part = cost > 0 ? ((Number(ing.subtotal) || 0) / cost) * 100 : 0;
      rowsHtml += `
        <tr>
          <td><strong>${idx + 1}. ${ing.name}</strong></td>
          <td class="text-center">${ing.qty}</td>
          <td class="text-center"><span class="badge-tag" style="background:#f1f5f9;">${ing.unit}</span></td>
          <td class="text-right">${formatMoney(ing.unitCost)}</td>
          <td class="text-right" style="font-weight:700; color:#091728;">${formatMoney(ing.subtotal)}</td>
          <td class="text-center"><span style="color:#64748b; font-size:0.75rem;">${part.toFixed(1)}%</span></td>
        </tr>`;
    });

    body.innerHTML = `
      <!-- Cabecera Financiera de la Ficha -->
      <div style="display:grid; grid-template-columns: repeat(4, 1fr); gap:12px; margin-bottom:18px;">
        <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:8px; padding:10px; text-align:center;">
          <span style="font-size:0.70rem; color:#64748b; font-weight:700; text-transform:uppercase;">Costo Primo / Porción</span>
          <div style="font-size:1.15rem; font-weight:800; color:#b45309;">${formatMoney(cost)}</div>
        </div>
        <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:8px; padding:10px; text-align:center;">
          <span style="font-size:0.70rem; color:#64748b; font-weight:700; text-transform:uppercase;">Precio de Venta Carta</span>
          <div style="font-size:1.15rem; font-weight:800; color:#0284c7;">${formatMoney(price)}</div>
        </div>
        <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:8px; padding:10px; text-align:center;">
          <span style="font-size:0.70rem; color:#64748b; font-weight:700; text-transform:uppercase;">Food Cost Teórico</span>
          <div style="font-size:1.15rem; font-weight:800; color:${fc <= 35 ? '#16a34a' : '#dc2626'};">${fc.toFixed(1)}%</div>
        </div>
        <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:8px; padding:10px; text-align:center;">
          <span style="font-size:0.70rem; color:#64748b; font-weight:700; text-transform:uppercase;">Ganancia Bruta</span>
          <div style="font-size:1.15rem; font-weight:800; color:#16a34a;">${formatMoney(profit)}</div>
        </div>
      </div>

      <!-- Tabla de Ingredientes -->
      <h6 style="font-weight:800; color:#091728; margin:16px 0 8px 0;"><i class="fa-solid fa-list-check text-gold"></i> Desglose de Insumos e Ingredientes:</h6>
      <div class="table-responsive" style="border:1px solid #e2e8f0; border-radius:8px;">
        <table class="data-table" style="width:100%; font-size:0.80rem;">
          <thead>
            <tr>
              <th>Ingrediente / Materia Prima</th>
              <th class="text-center">Cantidad</th>
              <th class="text-center">Unidad</th>
              <th class="text-right">Costo Unit.</th>
              <th class="text-right">Subtotal</th>
              <th class="text-center">% Costo</th>
            </tr>
          </thead>
          <tbody>
            ${rowsHtml}
          </tbody>
          <tfoot>
            <tr style="background:#091728; color:#ffffff; font-weight:800;">
              <td colspan="4">TOTAL COSTO PRIMO DE INGREDIENTES:</td>
              <td class="text-right" style="color:#fbbf24; font-size:0.92rem;">${formatMoney(cost)}</td>
              <td class="text-center">100%</td>
            </tr>
          </tfoot>
        </table>
      </div>

      <!-- Notas de Cocina -->
      ${r.notes ? `
      <div style="margin-top:16px; background:#fffbeb; border:1px solid #fef3c7; border-radius:8px; padding:12px; font-size:0.82rem; color:#92400e;">
        <strong style="display:block; margin-bottom:4px;"><i class="fa-solid fa-fire-burner"></i> Instrucciones de Preparación / Procedimiento Estándar:</strong>
        ${r.notes}
      </div>` : ''}
    `;

    if (btnQuote) {
      btnQuote.onclick = () => {
        closeRecipeModal();
        sendRecipeToSimulator(r.id);
      };
    }
    if (btnPrint) {
      btnPrint.onclick = () => window.print();
    }

    modal.style.display = 'flex';
  }

  function closeRecipeModal() {
    const modal = document.getElementById('modal-recipe-view');
    if (modal) modal.style.display = 'none';
  }

  function deleteRecipe(recipeId) {
    if (!confirm('¿Estás seguro de eliminar esta receta del catálogo de pruebas?')) return;
    const recipes = getActiveCompanyRecipes().filter(r => r.id !== recipeId);
    saveActiveCompanyRecipes(recipes);
    renderRecipesModule();
    showToast('Receta eliminada del catálogo.', 'success');
  }

  // ==========================================================================
  // RENDERIZADOR Y LÓGICA DEL COTIZADOR Y SIMULADOR
  // ==========================================================================

  let currentSimulatorIngredients = [];
  let currentEventDishes = [];
  let currentEventServices = [];

  function sendRecipeToSimulator(recipeId) {
    const recipes = getActiveCompanyRecipes();
    const r = recipes.find(x => x.id === recipeId);
    if (!r) return;

    activateTab('tab-cotizador');
    const tabBtn = document.querySelector('.tab-btn[data-tab="tab-cotizador"]');
    if (tabBtn) tabBtn.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

    // Activar subpestaña simulador
    switchQuoterSubtab('simulador');

    const txtDish = document.getElementById('sim-dish-name');
    const txtCat = document.getElementById('sim-dish-category');
    const rangeMargin = document.getElementById('sim-margin-range');

    if (txtDish) txtDish.value = r.name;
    if (txtCat) txtCat.value = r.category || 'General';
    if (rangeMargin && r.suggestedMargin) rangeMargin.value = r.suggestedMargin;

    currentSimulatorIngredients = JSON.parse(JSON.stringify(r.ingredients || []));
    renderSimulatorIngredientsTable();
    recalculateSimulatorFinancials();
    showToast(`Receta "${r.name}" cargada en el simulador.`, 'success');
  }

  function renderQuoterModule() {
    if (currentSimulatorIngredients.length === 0) {
      const recipes = getActiveCompanyRecipes();
      if (recipes.length > 0) {
        currentSimulatorIngredients = JSON.parse(JSON.stringify(recipes[0].ingredients || []));
        const txtDish = document.getElementById('sim-dish-name');
        const txtCat = document.getElementById('sim-dish-category');
        if (txtDish) txtDish.value = recipes[0].name;
        if (txtCat) txtCat.value = recipes[0].category || 'General';
      }
    }
    renderSimulatorIngredientsTable();
    recalculateSimulatorFinancials();

    // Eventos del Cotizador de Eventos si están vacíos
    if (currentEventDishes.length === 0) {
      const recipes = getActiveCompanyRecipes();
      if (recipes.length >= 2) {
        currentEventDishes = [
          { recipeId: recipes[0].id, name: recipes[0].name, pax: 50, costUnit: calculateRecipeCost(recipes[0]) },
          { recipeId: recipes[4] ? recipes[4].id : recipes[1].id, name: recipes[4] ? recipes[4].name : recipes[1].name, pax: 50, costUnit: calculateRecipeCost(recipes[4] || recipes[1]) }
        ];
      }
    }
    if (currentEventServices.length === 0) {
      currentEventServices = [
        { name: 'Servicio de Meseros y Personal de Barra (4 personas)', qty: 1, total: 360000 },
        { name: 'Alquiler de Cristalería y Mantelería Premium', qty: 50, total: 250000 }
      ];
    }
    renderEventDishesTable();
    renderEventServicesTable();
    recalculateEventFinancials();
  }

  function calculateRecipeCost(rec) {
    return (rec.ingredients || []).reduce((acc, i) => acc + (Number(i.subtotal) || 0), 0);
  }

  function renderSimulatorIngredientsTable() {
    const tbody = document.getElementById('tbody-sim-ingredients');
    if (!tbody) return;
    tbody.innerHTML = '';

    currentSimulatorIngredients.forEach((ing, idx) => {
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td><input type="text" class="form-control ing-name" value="${ing.name}" style="padding:4px 8px; font-size:0.80rem; width:100%;"></td>
        <td><input type="number" class="form-control text-center ing-qty" value="${ing.qty}" step="any" min="0" style="padding:4px 6px; font-size:0.80rem; width:100%;"></td>
        <td><input type="text" class="form-control text-center ing-unit" value="${ing.unit}" style="padding:4px 6px; font-size:0.80rem; width:100%;"></td>
        <td class="text-right" style="font-weight:700; color:#091728;">${formatMoney(ing.subtotal)}</td>
        <td class="text-center">
          <button type="button" class="btn btn-xs btn-outline-danger btn-remove-ing" data-idx="${idx}" style="border:none; color:#ef4444; background:transparent;">
            <i class="fa-solid fa-circle-xmark"></i>
          </button>
        </td>
      `;

      // Eventos de edición
      const inName = tr.querySelector('.ing-name');
      const inQty = tr.querySelector('.ing-qty');
      const inUnit = tr.querySelector('.ing-unit');
      const btnRem = tr.querySelector('.btn-remove-ing');

      inName.addEventListener('input', (e) => { ing.name = e.target.value; });
      inQty.addEventListener('input', (e) => {
        ing.qty = Number(e.target.value) || 0;
        ing.subtotal = Math.round(ing.qty * (Number(ing.unitCost) || 0));
        renderSimulatorIngredientsTable();
        recalculateSimulatorFinancials();
      });
      inUnit.addEventListener('input', (e) => { ing.unit = e.target.value; });
      btnRem.addEventListener('click', () => {
        currentSimulatorIngredients.splice(idx, 1);
        renderSimulatorIngredientsTable();
        recalculateSimulatorFinancials();
      });

      tbody.appendChild(tr);
    });
  }

  function recalculateSimulatorFinancials() {
    const cost = currentSimulatorIngredients.reduce((acc, i) => acc + (Number(i.subtotal) || 0), 0);
    const range = document.getElementById('sim-margin-range');
    const marginPct = range ? Number(range.value) : 68;
    const taxRegime = document.getElementById('sim-tax-regime');
    const taxType = taxRegime ? taxRegime.value : 'impo_8';

    const lblMargin = document.getElementById('lbl-sim-margin-val');
    if (lblMargin) lblMargin.textContent = `${marginPct}%`;

    const elCosto = document.getElementById('sim-costo-total');
    if (elCosto) elCosto.textContent = formatMoney(cost);

    // Margen deseado = (Venta - Costo) / Venta => Venta = Costo / (1 - Margen)
    const factor = Math.max(0.05, 1 - (marginPct / 100));
    const basePrice = Math.round(cost / factor);

    let taxPct = 0.08;
    if (taxType === 'iva_19') taxPct = 0.19;
    if (taxType === 'exento') taxPct = 0;

    const taxAmount = Math.round(basePrice * taxPct);
    const finalPrice = basePrice + taxAmount;
    const profitNet = basePrice - cost;

    const elNet = document.getElementById('sim-price-net');
    const elTax = document.getElementById('sim-price-tax');
    const elFinal = document.getElementById('sim-price-final');
    const elProfit = document.getElementById('sim-profit-net');

    if (elNet) elNet.textContent = formatMoney(basePrice);
    if (elTax) elTax.textContent = `${formatMoney(taxAmount)} (${Math.round(taxPct * 100)}%)`;
    if (elFinal) elFinal.textContent = formatMoney(finalPrice);
    if (elProfit) elProfit.textContent = `${formatMoney(profitNet)} (${marginPct}% margen)`;
  }

  function switchQuoterSubtab(subtab) {
    const pSim = document.getElementById('panel-simulador-plato');
    const pEv = document.getElementById('panel-cotizador-eventos');
    const bSim = document.getElementById('btn-subtab-sim-plato');
    const bEv = document.getElementById('btn-subtab-cot-evento');

    if (subtab === 'simulador') {
      if (pSim) pSim.style.display = 'block';
      if (pEv) pEv.style.display = 'none';
      if (bSim) { bSim.className = 'btn btn-sm btn-primary'; }
      if (bEv) { bEv.className = 'btn btn-sm btn-outline-secondary'; }
    } else {
      if (pSim) pSim.style.display = 'none';
      if (pEv) pEv.style.display = 'block';
      if (bSim) { bSim.className = 'btn btn-sm btn-outline-secondary'; }
      if (bEv) { bEv.className = 'btn btn-sm btn-primary'; }
    }
  }

  function renderEventDishesTable() {
    const tbody = document.getElementById('tbody-ev-dishes');
    if (!tbody) return;
    tbody.innerHTML = '';

    currentEventDishes.forEach((d, idx) => {
      const tot = Math.round(d.pax * d.costUnit);
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td><strong>${d.name}</strong></td>
        <td><input type="number" class="form-control text-center d-pax" value="${d.pax}" min="1" style="padding:4px; font-size:0.80rem; width:100%;"></td>
        <td class="text-right">${formatMoney(d.costUnit)}</td>
        <td class="text-right" style="font-weight:700; color:#091728;">${formatMoney(tot)}</td>
        <td class="text-center">
          <button type="button" class="btn btn-xs btn-outline-danger btn-del-ev-dish" data-idx="${idx}" style="border:none; color:#ef4444; background:transparent;">
            <i class="fa-solid fa-circle-xmark"></i>
          </button>
        </td>
      `;

      tr.querySelector('.d-pax').addEventListener('input', (e) => {
        d.pax = Number(e.target.value) || 0;
        renderEventDishesTable();
        recalculateEventFinancials();
      });

      tr.querySelector('.btn-del-ev-dish').addEventListener('click', () => {
        currentEventDishes.splice(idx, 1);
        renderEventDishesTable();
        recalculateEventFinancials();
      });

      tbody.appendChild(tr);
    });
  }

  function renderEventServicesTable() {
    const tbody = document.getElementById('tbody-ev-services');
    if (!tbody) return;
    tbody.innerHTML = '';

    currentEventServices.forEach((s, idx) => {
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td><input type="text" class="form-control s-name" value="${s.name}" style="padding:4px 8px; font-size:0.80rem; width:100%;"></td>
        <td><input type="number" class="form-control text-center s-qty" value="${s.qty}" min="1" style="padding:4px; font-size:0.80rem; width:100%;"></td>
        <td><input type="number" class="form-control text-right s-tot" value="${s.total}" step="5000" style="padding:4px; font-size:0.80rem; width:100%;"></td>
        <td class="text-center">
          <button type="button" class="btn btn-xs btn-outline-danger btn-del-ev-serv" data-idx="${idx}" style="border:none; color:#ef4444; background:transparent;">
            <i class="fa-solid fa-circle-xmark"></i>
          </button>
        </td>
      `;

      tr.querySelector('.s-name').addEventListener('input', (e) => { s.name = e.target.value; });
      tr.querySelector('.s-qty').addEventListener('input', (e) => { s.qty = Number(e.target.value) || 0; });
      tr.querySelector('.s-tot').addEventListener('input', (e) => {
        s.total = Number(e.target.value) || 0;
        recalculateEventFinancials();
      });
      tr.querySelector('.btn-del-ev-serv').addEventListener('click', () => {
        currentEventServices.splice(idx, 1);
        renderEventServicesTable();
        recalculateEventFinancials();
      });

      tbody.appendChild(tr);
    });
  }

  function recalculateEventFinancials() {
    const costFood = currentEventDishes.reduce((acc, d) => acc + (d.pax * d.costUnit), 0);
    const costServices = currentEventServices.reduce((acc, s) => acc + (Number(s.total) || 0), 0);
    const costTotal = costFood + costServices;

    const inPax = document.getElementById('ev-pax');
    const paxCount = inPax ? Math.max(1, Number(inPax.value) || 1) : 50;

    const range = document.getElementById('ev-margin-range');
    const marginPct = range ? Number(range.value) : 55;
    const lblMargin = document.getElementById('lbl-ev-margin-val');
    if (lblMargin) lblMargin.textContent = `${marginPct}%`;

    const elCostFood = document.getElementById('ev-costo-alimentos');
    const elCostServ = document.getElementById('ev-costo-servicios');
    const elCostTot = document.getElementById('ev-costo-total-evento');
    const elBadgePax = document.getElementById('ev-badge-pax');

    if (elCostFood) elCostFood.textContent = formatMoney(costFood);
    if (elCostServ) elCostServ.textContent = formatMoney(costServices);
    if (elCostTot) elCostTot.textContent = formatMoney(costTotal);
    if (elBadgePax) elBadgePax.textContent = `${paxCount} Pax`;

    const factor = Math.max(0.1, 1 - (marginPct / 100));
    const basePrice = Math.round(costTotal / factor);
    const taxAmount = Math.round(basePrice * 0.08); // 8% impoconsumo
    const totalPrice = basePrice + taxAmount;
    const pricePerPax = Math.round(totalPrice / paxCount);

    const elNet = document.getElementById('ev-price-net');
    const elTax = document.getElementById('ev-price-tax');
    const elPriceTot = document.getElementById('ev-price-total');
    const elPricePax = document.getElementById('ev-price-per-pax');

    if (elNet) elNet.textContent = formatMoney(basePrice);
    if (elTax) elTax.textContent = formatMoney(taxAmount);
    if (elPriceTot) elPriceTot.textContent = formatMoney(totalPrice);
    if (elPricePax) elPricePax.textContent = formatMoney(pricePerPax);
  }

  // Inicializar listeners de Recetario y Cotizador al cargar DOM
  function initRecipeAndQuoterListeners() {
    const btnNew = document.getElementById('btn-new-recipe');
    if (btnNew) {
      btnNew.addEventListener('click', () => {
        activateTab('tab-cotizador');
        switchQuoterSubtab('simulador');
        const txtDish = document.getElementById('sim-dish-name');
        if (txtDish) txtDish.value = 'Nueva Receta';
        currentSimulatorIngredients = [
          { name: 'Ingrediente Base 1', qty: 100, unit: 'gr', unitCost: 15, subtotal: 1500 }
        ];
        renderSimulatorIngredientsTable();
        recalculateSimulatorFinancials();
        showToast('Completa los ingredientes en el simulador y haz clic en "Guardar como Ficha Técnica".', 'info');
      });
    }

    const selCat = document.getElementById('filter-recipe-cat');
    if (selCat) selCat.addEventListener('change', renderRecipesModule);

    const txtSearch = document.getElementById('search-recipe-query');
    if (txtSearch) txtSearch.addEventListener('input', renderRecipesModule);

    const btnReset = document.getElementById('btn-reset-recipe-filters');
    if (btnReset) {
      btnReset.addEventListener('click', () => {
        if (selCat) selCat.value = 'ALL';
        if (txtSearch) txtSearch.value = '';
        renderRecipesModule();
      });
    }

    const btnCloseModal = document.getElementById('btn-close-recipe-modal');
    if (btnCloseModal) btnCloseModal.addEventListener('click', closeRecipeModal);
    const btnCloseFooter = document.getElementById('btn-close-recipe-footer');
    if (btnCloseFooter) btnCloseFooter.addEventListener('click', closeRecipeModal);

    // Subtabs Cotizador
    const btnSubSim = document.getElementById('btn-subtab-sim-plato');
    if (btnSubSim) btnSubSim.addEventListener('click', () => switchQuoterSubtab('simulador'));
    const btnSubEv = document.getElementById('btn-subtab-cot-evento');
    if (btnSubEv) btnSubEv.addEventListener('click', () => switchQuoterSubtab('eventos'));

    // Slider Margen Simulador
    const rangeSim = document.getElementById('sim-margin-range');
    if (rangeSim) rangeSim.addEventListener('input', recalculateSimulatorFinancials);

    const selTax = document.getElementById('sim-tax-regime');
    if (selTax) selTax.addEventListener('change', recalculateSimulatorFinancials);

    const btnAddSimIng = document.getElementById('btn-add-sim-ingredient');
    if (btnAddSimIng) {
      btnAddSimIng.addEventListener('click', () => {
        currentSimulatorIngredients.push({ name: 'Nuevo Insumo', qty: 50, unit: 'gr', unitCost: 20, subtotal: 1000 });
        renderSimulatorIngredientsTable();
        recalculateSimulatorFinancials();
      });
    }

    const btnClearSim = document.getElementById('btn-clear-sim-ingredients');
    if (btnClearSim) {
      btnClearSim.addEventListener('click', () => {
        currentSimulatorIngredients = [];
        renderSimulatorIngredientsTable();
        recalculateSimulatorFinancials();
      });
    }

    const btnSaveSimRecipe = document.getElementById('btn-save-sim-as-recipe');
    if (btnSaveSimRecipe) {
      btnSaveSimRecipe.addEventListener('click', () => {
        const dishName = (document.getElementById('sim-dish-name')?.value || 'Plato Simulado').trim();
        const dishCat = (document.getElementById('sim-dish-category')?.value || 'Platos Fuertes').trim();
        const cost = currentSimulatorIngredients.reduce((acc, i) => acc + (Number(i.subtotal) || 0), 0);
        const marginPct = Number(document.getElementById('sim-margin-range')?.value) || 68;
        const factor = Math.max(0.05, 1 - (marginPct / 100));
        const finalPrice = Math.round(cost / factor);

        const newRec = {
          id: 'rec_' + Date.now(),
          name: dishName,
          category: dishCat,
          portion: '1 porción',
          prepTime: '15 min',
          salePrice: finalPrice,
          suggestedMargin: marginPct,
          notes: 'Creado desde el simulador de recetas de DC RestoData.',
          ingredients: JSON.parse(JSON.stringify(currentSimulatorIngredients))
        };

        const recipes = getActiveCompanyRecipes();
        recipes.unshift(newRec);
        saveActiveCompanyRecipes(recipes);
        showToast(`Ficha técnica "${dishName}" guardada con éxito en el recetario.`, 'success');
        activateTab('tab-recetario');
        renderRecipesModule();
      });
    }

    // Slider Eventos
    const rangeEv = document.getElementById('ev-margin-range');
    if (rangeEv) rangeEv.addEventListener('input', recalculateEventFinancials);

    const inEvPax = document.getElementById('ev-pax');
    if (inEvPax) inEvPax.addEventListener('input', (e) => {
      const p = Number(e.target.value) || 50;
      currentEventDishes.forEach(d => d.pax = p);
      renderEventDishesTable();
      recalculateEventFinancials();
    });

    const btnAddEvDish = document.getElementById('btn-add-event-dish');
    if (btnAddEvDish) {
      btnAddEvDish.addEventListener('click', () => {
        const recipes = getActiveCompanyRecipes();
        const first = recipes[0] || { id: 'dummy', name: 'Plato General', ingredients: [] };
        currentEventDishes.push({
          recipeId: first.id,
          name: first.name,
          pax: Number(inEvPax?.value) || 50,
          costUnit: calculateRecipeCost(first)
        });
        renderEventDishesTable();
        recalculateEventFinancials();
      });
    }

    const btnAddEvServ = document.getElementById('btn-add-event-service');
    if (btnAddEvServ) {
      btnAddEvServ.addEventListener('click', () => {
        currentEventServices.push({ name: 'Nuevo Servicio Logístico', qty: 1, total: 100000 });
        renderEventServicesTable();
        recalculateEventFinancials();
      });
    }

    const btnPrintEv = document.getElementById('btn-print-event-quotation');
    if (btnPrintEv) {
      btnPrintEv.addEventListener('click', () => {
        window.print();
      });
    }
  }

  // Hook en inicialización
  setTimeout(() => {
    initRecipeAndQuoterListeners();
  }, 1000);



  // ==========================================================================
  // EVENTOS PARA EDICIÓN DE PRECIOS Y TARIFAS DE PLANES (CORRECTAMENTE DENTRO DE DOMContentLoaded)
  // ==========================================================================
  function handleSavePlanPrices() {
    const parseVal = (id, def) => {
      const el = document.getElementById(id);
      if (!el || !el.value) return def;
      const cleaned = String(el.value).replace(/[^0-9]/g, '');
      const num = Number(cleaned);
      return isNaN(num) || num <= 0 ? def : num;
    };

    const cfg = {
      basico: parseVal('cfg-fee-basico', DEFAULT_PLANS_PRICING.basico),
      estandar: parseVal('cfg-fee-estandar', DEFAULT_PLANS_PRICING.estandar),
      pro: parseVal('cfg-fee-pro', DEFAULT_PLANS_PRICING.pro),
      premium: parseVal('cfg-fee-premium', DEFAULT_PLANS_PRICING.premium),
      descTrimestral: Number(document.getElementById('cfg-desc-trimestral')?.value) || DEFAULT_PLANS_PRICING.descTrimestral,
      descSemestral: Number(document.getElementById('cfg-desc-semestral')?.value) || DEFAULT_PLANS_PRICING.descSemestral,
      mesesAnual: Number(document.getElementById('cfg-meses-anual')?.value) || DEFAULT_PLANS_PRICING.mesesAnual
    };

    localStorage.setItem('dc_plans_pricing_config', JSON.stringify(cfg));
    applyPlansPricingConfig(cfg);

    // Sincronizar en la nube en Firestore
    if (firestoreDb) {
      firestoreDb.collection('system').doc('plans_pricing').set(cfg, { merge: true })
        .then(() => console.log('Tarifas de planes guardadas en Firestore exitosamente.'))
        .catch(err => console.warn('Error guardando tarifas en Firestore:', err));
    }

    // Actualizar campos en el modal de editar empresa si está abierto
    const servicePlanEl = document.getElementById('edit-company-service-plan');
    const billingPeriodEl = document.getElementById('edit-company-billing-period');
    const contractFeeEl = document.getElementById('edit-company-contract-fee');
    const planFeeHint = document.getElementById('plan-fee-hint');
    if (servicePlanEl && billingPeriodEl) {
      const p = servicePlanEl.value;
      const b = billingPeriodEl.value;
      const fee = calculateSuggestedFee(p, b);
      if (planFeeHint) {
        if (p === 'plan_personalizado') {
          planFeeHint.textContent = 'Tarifa Personalizada';
        } else {
          const savings = b === 'trimestral' ? ' (5% desc)' : (b === 'semestral' ? ' (10% desc)' : (b === 'anual' ? ' (2 meses gratis)' : ''));
          planFeeHint.textContent = `Sugerido: ${formatMoney(fee)} [${b}]${savings}`;
        }
      }
      if (contractFeeEl && p !== 'plan_personalizado') {
        contractFeeEl.value = fee;
      }
    }

    // Actualizar campos en el registro si está abierto
    const regPlanEl = document.getElementById('reg-service-plan');
    const regPeriodEl = document.getElementById('reg-billing-period');
    const regFeeEl = document.getElementById('reg-contract-fee');
    const regHintEl = document.getElementById('reg-plan-fee-hint');
    if (regPlanEl && regPeriodEl) {
      const p = regPlanEl.value;
      const b = regPeriodEl.value;
      const fee = calculateSuggestedFee(p, b);
      if (regHintEl) {
        if (p === 'plan_personalizado') {
          regHintEl.textContent = 'Tarifa Personalizada';
        } else {
          const savings = b === 'trimestral' ? ' (5% desc)' : (b === 'semestral' ? ' (10% desc)' : (b === 'anual' ? ' (2 meses gratis)' : ''));
          regHintEl.textContent = `Sugerido: ${formatMoney(fee)} [${b}]${savings}`;
        }
      }
      if (regFeeEl && p !== 'plan_personalizado') {
        regFeeEl.value = fee;
      }
    }

    // Refrescar cuadrícula de empresas
    if (typeof renderMasterCompaniesGrid === 'function') {
      const inputSearch = document.getElementById('input-search-companies');
      renderMasterCompaniesGrid(inputSearch ? inputSearch.value : '');
    }

    // Cerrar ventana de tarifas primero
    closeManagePlanPricesModal();

    // Si el modal de editar empresa estaba abierto detrás, guardar los cambios de la empresa y cerrarlo automáticamente
    const modalEditCompany = document.getElementById('modal-edit-company');
    if (modalEditCompany && !modalEditCompany.classList.contains('hidden')) {
      const btnSaveEditCompany = document.getElementById('btn-save-edit-company');
      if (btnSaveEditCompany) {
        btnSaveEditCompany.click();
      } else {
        closeEditCompanyModal();
      }
    }

    showToast('¡Tarifas de los planes guardadas y actualizadas correctamente!', 'success');
  }
  window.handleSavePlanPrices = handleSavePlanPrices;

  const btnMasterEditPlans = document.getElementById('btn-master-edit-plans');
  if (btnMasterEditPlans) {
    btnMasterEditPlans.addEventListener('click', (e) => {
      e.preventDefault();
      openManagePlanPricesModal();
    });
  }

  const btnQuickEditPlans = document.getElementById('btn-quick-edit-plans');
  if (btnQuickEditPlans) {
    btnQuickEditPlans.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      openManagePlanPricesModal();
    });
  }

  const btnClosePlanPrices = document.getElementById('btn-close-plan-prices');
  if (btnClosePlanPrices) btnClosePlanPrices.addEventListener('click', closeManagePlanPricesModal);

  const btnCancelPlanPrices = document.getElementById('btn-cancel-plan-prices');
  if (btnCancelPlanPrices) btnCancelPlanPrices.addEventListener('click', closeManagePlanPricesModal);

  const modalManagePlanPrices = document.getElementById('modal-manage-plan-prices');
  if (modalManagePlanPrices) {
    modalManagePlanPrices.addEventListener('click', (e) => {
      if (e.target === modalManagePlanPrices) {
        closeManagePlanPricesModal();
      }
    });
  }
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modalManagePlanPrices && !modalManagePlanPrices.classList.contains('hidden')) {
      closeManagePlanPricesModal();
    }
  });

  const btnResetPlanPrices = document.getElementById('btn-reset-default-plan-prices');
  if (btnResetPlanPrices) {
    btnResetPlanPrices.addEventListener('click', () => {
      const inBasico = document.getElementById('cfg-fee-basico');
      const inEstandar = document.getElementById('cfg-fee-estandar');
      const inPro = document.getElementById('cfg-fee-pro');
      const inTrim = document.getElementById('cfg-desc-trimestral');
      const inSem = document.getElementById('cfg-desc-semestral');
      const inAnual = document.getElementById('cfg-meses-anual');

      if (inBasico) inBasico.value = DEFAULT_PLANS_PRICING.basico;
      if (inEstandar) inEstandar.value = DEFAULT_PLANS_PRICING.estandar;
      if (inPro) inPro.value = DEFAULT_PLANS_PRICING.pro;
      if (inPremium) inPremium.value = DEFAULT_PLANS_PRICING.premium;
      if (inTrim) inTrim.value = DEFAULT_PLANS_PRICING.descTrimestral;
      if (inSem) inSem.value = DEFAULT_PLANS_PRICING.descSemestral;
      if (inAnual) inAnual.value = DEFAULT_PLANS_PRICING.mesesAnual;

      if (inBasico) inBasico.dispatchEvent(new Event('input'));
      showToast('Valores por defecto restablecidos en el formulario.', 'info');
    });
  }

  const btnSavePlanPrices = document.getElementById('btn-save-plan-prices');
  if (btnSavePlanPrices) {
    btnSavePlanPrices.addEventListener('click', (e) => {
      e.preventDefault();
      handleSavePlanPrices();
    });
  }

  // Botón para aplicar tarifa sugerida en modal de editar empresa
  const btnApplySuggested = document.getElementById('btn-apply-suggested-fee');
  if (btnApplySuggested) {
    btnApplySuggested.addEventListener('click', (e) => {
      e.preventDefault();
      const servicePlanEl = document.getElementById('edit-company-service-plan');
      const billingPeriodEl = document.getElementById('edit-company-billing-period');
      const contractFeeEl = document.getElementById('edit-company-contract-fee');
      if (servicePlanEl && billingPeriodEl && contractFeeEl) {
        const p = servicePlanEl.value;
        const b = billingPeriodEl.value;
        const fee = calculateSuggestedFee(p, b);
        contractFeeEl.value = fee;
        showToast(`Tarifa sugerida aplicada: ${formatMoney(fee)}`, 'info');
      }
    });
  }



